		AnnotationManager manager = new AnnotationManager(new Gson(), new File(dir, "annotations.json"));
		manager.load();
		manager.setTarget("abc123", new WorldPoint(1000, 2000, 0));

		assertEquals(AnnotationManager.ClearResult.REMOVED_LOCAL, manager.clearTarget("abc123"));
		assertNull(manager.getTarget("abc123"));
		assertEquals(AnnotationManager.ClearResult.NOTHING, manager.clearTarget("abc123"));
	}

	/** Test double with one bundled target — a wrong seeded pin. */
	private static AnnotationManager withBundledTarget(File file, String stepId)
	{
		StepAnnotation bundled = new StepAnnotation();
		bundled.target = new StepAnnotation.Target();
		bundled.target.x = 2624;
		bundled.target.y = 3300;
		java.util.Map<String, StepAnnotation> corpus = new java.util.HashMap<>();
		corpus.put(stepId, bundled);
		return new AnnotationManager(new Gson(), file)
		{
			@Override
			java.util.Map<String, StepAnnotation> readBundled()
			{
				return corpus;
			}
		};
	}

	@Test
	public void clearMasksWrongBundledPinAndCaptureReplacesIt() throws Exception
	{
		File dir = Files.createTempDirectory("ironscape-test").toFile();
		File file = new File(dir, "annotations.json");
		AnnotationManager manager = withBundledTarget(file, "shop");
		manager.load();
		assertEquals(2624, manager.getTarget("shop").x);

		// Removing with no local capture tombstones the bundled pin...
		assertEquals(AnnotationManager.ClearResult.MASKED_BUNDLED, manager.clearTarget("shop"));
		assertNull(manager.getTarget("shop"));
		assertEquals(AnnotationManager.ClearResult.NOTHING, manager.clearTarget("shop"));

		// ...the mask survives a client restart...
		AnnotationManager reloaded = withBundledTarget(file, "shop");
		reloaded.load();
		assertNull(reloaded.getTarget("shop"));

		// ...and capturing the right spot replaces the tombstone.
		reloaded.setTarget("shop", new WorldPoint(2645, 3360, 0));
		assertEquals(2645, reloaded.getTarget("shop").x);
	}

	@Test
	public void clearOverBundledDropsLocalAndMasksInOneGo() throws Exception
	{
		File dir = Files.createTempDirectory("ironscape-test").toFile();
		AnnotationManager manager = withBundledTarget(new File(dir, "annotations.json"), "shop");
		manager.load();
		manager.setTarget("shop", new WorldPoint(9, 9, 0));

		// The player standing at the wrong pin means "no pin here" — falling
		// back to the (equally wrong) bundled pin would force a second remove.
		assertEquals(AnnotationManager.ClearResult.MASKED_BUNDLED, manager.clearTarget("shop"));
		assertNull(manager.getTarget("shop"));
	}
}

package com.ironscape.annotations;

import com.ironscape.guide.Guide;
import com.ironscape.guide.GuideLoader;
import com.ironscape.guide.GuideStep;
import com.ironscape.guide.GuideVariant;
import com.ironscape.guide.SubStep;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertTrue;

/**
 * Every key in the BUNDLED annotations file must resolve against the
 * bundled guide as loaded by the real loader (including the clause
 * splitter). Sub-keyed annotations ("stepId:N") are the dangerous case:
 * a splitter change or upstream edit can silently shift which clause an
 * index points at — this test turns that silence into a build failure.
 */
public class BundledAnnotationKeysTest
{
	@Test
	public void ozirisAnnotationKeysResolve() throws Exception
	{
		assertKeysResolve("annotations_oziris.json", GuideVariant.OZIRIS);
	}

	private static void assertKeysResolve(String resource, GuideVariant variant) throws Exception
	{
		Guide guide = new GuideLoader(new Gson()).load(variant);
		Set<String> validIds = new HashSet<>(guide.getStepsById().keySet());
		for (GuideStep step : guide.getAllSteps())
		{
			for (SubStep sub : step.getSubSteps())
			{
				validIds.add(sub.getId());
			}
		}

		JsonObject file;
		try (Reader reader = new InputStreamReader(
			StepAnnotation.class.getResourceAsStream(resource), StandardCharsets.UTF_8))
		{
			// RuneLite ships an older Gson without JsonParser.parseReader.
			file = new Gson().fromJson(reader, JsonObject.class);
		}

		for (String key : file.getAsJsonObject("annotations").keySet())
		{
			assertTrue(resource + " key '" + key + "' matches no step or sub-step "
					+ "in the " + variant + " guide (upstream edit or splitter change?)",
				validIds.contains(key));
		}
	}
}

package com.ironscape;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Every JEditorPane in the panel must have its caret muted.
 *
 * <p>An un-muted caret scrolls the entire guide panel to whichever row it
 * belongs to. Each pane carries one; when the pane's document changes — which
 * happens to any row whose item counts are rewritten — the caret moves, and a
 * moving caret calls {@code scrollRectToVisible} on itself, which walks up to
 * the JScrollPane and drags the view there.
 *
 * <p>It cost six rounds of diagnosis, because the panel's own scrolling code
 * is not involved and therefore logs nothing: the view simply leaves. The
 * owner met it as the panel "jumping to steps I've completed", then to steps
 * far AHEAD, on opening a bank and then a shop. It was finally pinned by a
 * change listener on the viewport printing the caller —
 * {@code DefaultCaret.adjustVisibility}, moving the view 366 -> 6855.
 *
 * <p>Nothing in the compiler or the LAF prevents the next pane from being
 * added without the call, and the symptom would be blamed on the scroll code
 * again, so the pairing is asserted here.
 */
public class CaretMutedTest
{
	@Test
	public void everyEditorPaneMutesItsCaret() throws IOException
	{
		int panes = 0;
		int muted = 0;
		List<String> files = new ArrayList<>();
		Path root = Paths.get("src/main/java");
		if (!Files.isDirectory(root))
		{
			// Say so rather than pass silently — a check that quietly measures
			// nothing is worse than no check (wave 25).
			throw new IOException("cannot find src/main/java from " + Paths.get("").toAbsolutePath());
		}
		try (Stream<Path> tree = Files.walk(root))
		{
			for (Path file : (Iterable<Path>) tree.filter(p -> p.toString().endsWith(".java"))::iterator)
			{
				String source = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
				int here = count(source, "new JEditorPane()");
				if (here > 0)
				{
					panes += here;
					files.add(file.toString());
				}
				// The declaration reads "private static void muteCaret(", which
				// must not be counted as one of its own call sites.
				muted += count(source, "muteCaret(") - count(source, "void muteCaret(");
			}
		}
		assertEquals("Every JEditorPane must be passed to muteCaret(), or it will"
				+ " scroll the whole panel to itself whenever its text changes."
				+ " Panes live in: " + files,
			panes, muted);
	}

	private static int count(String haystack, String needle)
	{
		int n = 0;
		for (int at = haystack.indexOf(needle); at >= 0; at = haystack.indexOf(needle, at + 1))
		{
			n++;
		}
		return n;
	}
}

package com.ironscape.places;

import com.google.gson.Gson;
import java.io.File;

/**
 * Authoring/debug aid: does a given phrase linkify and resolve? Run like
 * PrintSubIdProbe (classpath = main+test classes + gson + runelite-api +
 * resources). Prints the resolution of every argument, plus the linkified
 * form of a sample sentence.
 */
public final class PlaceLinkProbe
{
	public static void main(String[] args) throws Exception
	{
		java.io.InputStream in = PlaceManager.class.getResourceAsStream("places.json");
		System.out.println("resource stream: " + in);
		if (in != null)
		{
			try (java.io.Reader r = new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8))
			{
				com.google.gson.JsonObject root = new com.google.gson.JsonParser().parse(r).getAsJsonObject();
				com.google.gson.JsonObject placesObj = root.getAsJsonObject("places");
				System.out.println("raw places entries: " + placesObj.size()
					+ ", has zmi bank: " + placesObj.has("zmi bank"));
			}
		}
		PlaceManager places = new PlaceManager(new Gson(), new File("no-local-places.json"));
		places.load();
		if (args.length > 0)
		{
			// Each argument: a phrase to resolve, or a sentence to linkify.
			for (String arg : args)
			{
				System.out.println("get(" + arg + ")      = " + places.get(arg));
				System.out.println("getLoose(" + arg + ") = " + places.getLoose(arg));
				System.out.println("linkify:  " + places.linkify(arg));
			}
			return;
		}
		System.out.println("get(zmi bank)        = " + places.get("zmi bank"));
		System.out.println("getLoose(ZMI Bank)   = " + places.getLoose("ZMI Bank"));
		System.out.println("getLoose(Khazard Battlefield) = " + places.getLoose("Khazard Battlefield"));
		System.out.println("linkify: " + places.linkify(
			"Run to ZMI bank and safespot the zamorak warrior until you get a rune scimitar"));
	}
}

