package com.ironscape.places;

import com.google.gson.Gson;
import java.io.File;
import java.nio.file.Files;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class PlaceManagerTest
{
	private PlaceManager freshManager() throws Exception
	{
		File dir = Files.createTempDirectory("ironscape-places").toFile();
		PlaceManager manager = new PlaceManager(new Gson(), new File(dir, "places.json"));
		manager.load();
		return manager;
	}

	@Test
	public void linkifiesKnownNamesCaseInsensitively() throws Exception
	{
		PlaceManager manager = freshManager();
		manager.add("Duke Horacio", new WorldPoint(3210, 3220, 1));

		String html = manager.linkify("Talk to duke horacio upstairs.");
		assertEquals("Talk to <a href='bruh:place:duke%20horacio'>duke horacio</a> upstairs.", html);

		// unknown names pass through untouched
		assertEquals("Talk to Hans.", manager.linkify("Talk to Hans."));
	}

	@Test
	public void toleratesApostropheAndAmpersandVariants() throws Exception
	{
		PlaceManager manager = freshManager();
		manager.add("Daddy's Home", new WorldPoint(3241, 3398, 0));
		manager.add("Romeo & Juliet", new WorldPoint(3211, 3424, 0));

		// guide text uses a curly apostrophe; ours is straight
		String html = manager.linkify("complete Daddy’s Home quickly");
		assertEquals("complete <a href='bruh:place:daddy%27s%20home'>Daddy’s Home</a> quickly", html);

		// linkify runs on HTML-escaped text where & became &amp;
		String escaped = manager.linkify("progress Romeo &amp; Juliet.");
		assertEquals("progress <a href='bruh:place:romeo%20%26%20juliet'>Romeo &amp; Juliet</a>.", escaped);

		// lookups normalize the same way
		assertEquals(3241, manager.get("daddy’s home").getX());
	}

	@Test
	public void lookupAndPersistence() throws Exception
	{
		File dir = Files.createTempDirectory("ironscape-places").toFile();
		File file = new File(dir, "places.json");

		PlaceManager manager = new PlaceManager(new Gson(), file);
		manager.load();
		manager.add("Grand Exchange", new WorldPoint(3164, 3487, 0));

		PlaceManager reloaded = new PlaceManager(new Gson(), file);
		reloaded.load();
		WorldPoint point = reloaded.get("grand exchange");
		assertEquals(3164, point.getX());
		assertEquals(3487, point.getY());
		// a name that will never exist in the bundled seed data
		assertNull(reloaded.get("definitely not a real place"));
	}

	/**
	 * Place links carry their target inside a Swing href, encoded on the way
	 * in and decoded on click. The pair replaced java.net.URLEncoder /
	 * URLDecoder — which never made a network call, but read as networking
	 * to the plugin hub's automated review and cost us the fast lane for a
	 * string utility.
	 *
	 * A drift between the two halves would break every link in the panel
	 * silently, so the round trip is asserted on the shapes that actually
	 * occur: apostrophes, spaces, ampersands, punctuation and non-ASCII.
	 */
	@Test
	public void linkPayloadsSurviveTheRoundTrip()
	{
		String[] names = {
			"varrock",
			"black knight's fortress",
			"the shrimp & parrot",
			"al kharid",
			"seers' village",
			"port sarim jail",
			"100% not a place",
			"café",
			"a+b=c?&#",
			"",
		};
		for (String name : names)
		{
			String encoded = PlaceManager.encode(name);
			assertEquals(name, PlaceManager.decode(encoded));
			// The payload rides in an HTML attribute, so it must come out
			// as plain ASCII with nothing that could close the tag.
			for (char c : encoded.toCharArray())
			{
				assertTrue("unsafe character " + c + " in encoded \"" + name + "\"",
					(c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
						|| (c >= '0' && c <= '9') || c == '%');
			}
		}
	}
}

package com.ironscape.items;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ItemAliasTest
{
	@org.junit.Test
	public void metalArrowheadsAreArrowtipsInGame()
	{
		org.junit.Assert.assertEquals("bronze arrowtips", ItemTracker.aliases("bronze arrowheads")[0]);
		org.junit.Assert.assertEquals("rune arrowtips", ItemTracker.aliases("rune arrowhead")[0]);
		// Broad arrowheads are genuinely named arrowheads — untouched.
		org.junit.Assert.assertEquals("broad arrowheads", ItemTracker.aliases("broad arrowheads")[0]);
	}

	private static boolean hasAlias(String guidePhrase, String realItemName)
	{
		return Arrays.asList(ItemTracker.aliases(guidePhrase)).contains(realItemName);
	}

	@Test
	public void guidePhrasesResolveToRealItemNames()
	{
		assertTrue(hasAlias("noted bolts of cloth", "bolt of cloth"));
		assertTrue(hasAlias("noted planks", "plank"));
		assertTrue(hasAlias("poh tab", "teleport to house"));
		assertTrue(hasAlias("gp", "coins"));
		assertTrue(hasAlias("mind", "mind rune"));
		assertTrue(hasAlias("log", "logs"));
	}

	/**
	 * "Grab 4 copper" is what every guide says; the item is "Copper ore".
	 * The badge sat at 0/4 next to a copper-ore icon, because item_ids gave
	 * the name a SPRITE while counting matched by NAME and found nothing
	 * (owner, in play). Same shorthand as the elemental runes, one metal
	 * over.
	 */
	@Test
	public void bareOreNamesResolveToTheOre()
	{
		assertTrue(hasAlias("copper", "copper ore"));
		assertTrue(hasAlias("tin", "tin ore"));
		assertTrue(hasAlias("iron", "iron ore"));
		// The plural the guide actually writes must work too.
		assertTrue(hasAlias("coppers", "copper ore"));
	}

	/**
	 * A goal that spells out a dose means THAT dose.
	 *
	 * canonical() folds "(4)" away so that "drink a restore potion" is
	 * satisfied by any dose, which is right nearly everywhere and wrong
	 * for "decant them until you have like 6 full pots": before this,
	 * twenty-four 1-dose vials read 6/6 while the step's entire job is
	 * turning them into four-dose ones. Written to fail under the old
	 * rule — the first assertion is the one that did.
	 */
	@Test
	public void aStatedDoseMeansThatDose()
	{
		assertFalse(ItemTracker.nameMatchesGoal("Superantipoison(1)", "superantipoison(4)"));
		assertFalse(ItemTracker.nameMatchesGoal("Superantipoison(2)", "superantipoison(4)"));
		assertTrue(ItemTracker.nameMatchesGoal("Superantipoison(4)", "superantipoison(4)"));
		// Dose-LESS goals keep taking any dose, which is most of the guide.
		assertTrue(ItemTracker.nameMatchesGoal("Superantipoison(1)", "super antipoison"));
		assertTrue(ItemTracker.nameMatchesGoal("Restore potion(3)", "restore potion"));
	}

	@Test
	public void teleportTabPhrasesResolveToWikiNames()
	{
		assertTrue(hasAlias("house teleport", "teleport to house"));
		assertTrue(hasAlias("house teleports", "teleport to house"));
		assertTrue(hasAlias("rellekka tab", "rellekka teleport"));
		assertTrue(hasAlias("rimmington tab", "rimmington teleport"));
		assertTrue(hasAlias("trollheim tab", "trollheim teleport"));
	}

	/**
	 * Two items, ONE in-game name — count them, do not try to tell them
	 * apart.
	 *
	 * The priest gown is a top and a bottom, both needed for Biohazard, and
	 * in game BOTH are called exactly "Priest gown" (owner, in the shop:
	 * "they both have the same name in game, just different items"). Only
	 * the WIKI distinguishes them, as page titles — "Priest gown (top)" is
	 * not a name any item has.
	 *
	 * So a first attempt annotated the halves separately, and each entry
	 * read the same number: counts are keyed by in-game name and summed
	 * (countByName), and the alias chain drops a trailing parenthetical, so
	 * both entries resolved to the same "priest gown" total and one half
	 * showed as 1/1 twice. No name-based matcher can separate them; the
	 * quantity is what carries the meaning.
	 */
	@Test
	public void bothPriestGownHalvesShareOneInGameName()
	{
		assertTrue(ItemTracker.nameMatchesGoal("Priest gown", "priest gown"));
		// The wiki's disambiguating title still resolves, via the
		// paren-dropping alias — which is exactly why it could not
		// distinguish the halves.
		assertTrue(ItemTracker.nameMatchesGoal("Priest gown", "priest gown (top)"));
		assertTrue(ItemTracker.nameMatchesGoal("Priest gown", "priest gown (bottom)"));
	}
}

package com.ironscape;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Rules the Plugin Hub enforces that our own build does not.
 *
 * <p>The hub rejects a plugin outright for these, and it only finds out
 * when the pin is bumped and its check runs — so the failure arrives
 * hours later, on a public PR, after a "clean build passed locally". That
 * happened on 2026-08-12: a `new Gson()` in a field initialiser passed
 * every local check and failed the hub with "Do not create fresh Gson
 * instances, always @Inject the client's Gson."
 *
 * <p>Cheaper to fail here. Add a rule whenever the hub teaches us one.
 */
public class HubComplianceTest
{
	/**
	 * The client's Gson is injectable and configured; a fresh one has
	 * different settings and the hub treats it as a terminally deprecated
	 * API. Customise with {@code gson.newBuilder()} if needed.
	 *
	 * <p>MAIN sources only: tests are not shipped in the jar, and the hub
	 * never sees them.
	 */
	@Test
	public void noFreshGsonInstances() throws IOException
	{
		List<String> offenders = scanMainSources("new Gson(", "new GsonBuilder(",
			"new com.google.gson.Gson(", "new com.google.gson.GsonBuilder(");
		assertTrue("The Plugin Hub rejects fresh Gson instances — @Inject the"
				+ " client's Gson instead (use .newBuilder() to customise). Found in:\n  "
				+ String.join("\n  ", offenders),
			offenders.isEmpty());
	}

	/** Reflection is forbidden by the hub; it cost us the Quest Helper handoff in review round 1. */
	@Test
	public void noReflection() throws IOException
	{
		List<String> offenders = scanMainSources(".getDeclaredMethod(", ".getDeclaredField(",
			"java.lang.reflect.");
		assertTrue("The Plugin Hub forbids reflection. Found in:\n  "
			+ String.join("\n  ", offenders), offenders.isEmpty());
	}

	private static List<String> scanMainSources(String... banned) throws IOException
	{
		Path root = Paths.get("src/main/java");
		if (!Files.isDirectory(root))
		{
			// Run from an unexpected working directory — better to say so
			// than to pass silently, which is how a check stops meaning
			// anything.
			throw new IOException("cannot find src/main/java from " + Paths.get("").toAbsolutePath());
		}
		List<String> offenders = new ArrayList<>();
		try (Stream<Path> tree = Files.walk(root))
		{
			for (Path file : (Iterable<Path>) tree.filter(p -> p.toString().endsWith(".java"))::iterator)
			{
				String source = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
				String[] lines = source.split("\r?\n");
				for (int i = 0; i < lines.length; i++)
				{
					String line = lines[i];
					// Skip comments: these names appear in the very comments
					// explaining why we must not use them.
					String trimmed = line.trim();
					if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*"))
					{
						continue;
					}
					for (String needle : banned)
					{
						if (line.contains(needle))
						{
							offenders.add(file + ":" + (i + 1) + "  " + trimmed);
						}
					}
				}
			}
		}
		return offenders;
	}
}

package com.ironscape;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Bundled data is read from the jar, through one door, and from nowhere
 * else on disk.
 *
 * <p>Plugin Hub review, 2026-09-02: "all file i/o must occur within a
 * plugin-specific subdir within .runelite", and specifically that the
 * configurable data folder this class used to support "is not going to be
 * allowed". That folder let a data-only fix be picked up with
 * {@code ::ironreload} instead of a rebuild, and it is gone. These tests
 * exist so it cannot come back by accident, since the cost of finding out
 * is a rejected submission days later.
 *
 * <p>Files the plugin WRITES are a different question and are fine: they
 * live in {@code ~/.runelite/ironscape/}, which is exactly what the rule
 * asks for.
 */
public class DataFilesRoutingTest
{
	/**
	 * travel_distances.bin.gz is a compiled lookup table built by
	 * tools/build-travel-distances.mjs, never hand-edited, and it reads
	 * itself off the classpath.
	 */
	private static final String BUILD_ARTIFACT = "TravelDistances.java";

	@Test
	public void bundledDataIsReadThroughOneDoor() throws IOException
	{
		List<String> offenders = scan("getResourceAsStream(",
			f -> f.equals("DataFiles.java") || f.equals(BUILD_ARTIFACT));
		assertTrue("Read bundled data with DataFiles.open(...), so there is one"
			+ " place that decides where data comes from. Found in:\n  "
			+ String.join("\n  ", offenders), offenders.isEmpty());
	}

	/**
	 * DataFiles must not touch the filesystem at all. It is the class the
	 * reviewer pointed at, so the rule is worth asserting on the class
	 * itself rather than on a behaviour that could be reintroduced
	 * somewhere adjacent.
	 */
	@Test
	public void dataFilesDoesNotTouchTheFilesystem() throws IOException
	{
		Path file = Paths.get("src/main/java/com/ironscape/DataFiles.java");
		if (!Files.isRegularFile(file))
		{
			throw new IOException("cannot find DataFiles.java from "
				+ Paths.get("").toAbsolutePath());
		}
		List<String> offenders = new ArrayList<>();
		String[] lines = new String(Files.readAllBytes(file), StandardCharsets.UTF_8)
			.split("\r?\n");
		for (int i = 0; i < lines.length; i++)
		{
			String trimmed = lines[i].trim();
			if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*"))
			{
				continue;   // the comment explaining the ban names the classes
			}
			for (String banned : new String[]{"java.io.File", "java.nio.file",
				"new File(", "Files.", "Paths.", "FileInputStream"})
			{
				if (lines[i].contains(banned))
				{
					offenders.add((i + 1) + ": " + trimmed);
				}
			}
		}
		assertTrue("DataFiles must resolve bundled data from the classpath only —"
			+ " reading a folder the user names is what the Plugin Hub rejected."
			+ " Found in:\n  " + String.join("\n  ", offenders), offenders.isEmpty());
	}

	private static List<String> scan(String needle,
		java.util.function.Predicate<String> exempt) throws IOException
	{
		Path root = Paths.get("src/main/java");
		if (!Files.isDirectory(root))
		{
			throw new IOException("cannot find src/main/java from "
				+ Paths.get("").toAbsolutePath());
		}
		List<String> offenders = new ArrayList<>();
		try (Stream<Path> tree = Files.walk(root))
		{
			for (Path file : (Iterable<Path>) tree.filter(p -> p.toString().endsWith(".java"))::iterator)
			{
				if (exempt.test(file.getFileName().toString()))
				{
					continue;
				}
				String[] lines = new String(Files.readAllBytes(file), StandardCharsets.UTF_8)
					.split("\r?\n");
				for (int i = 0; i < lines.length; i++)
				{
					String trimmed = lines[i].trim();
					if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*"))
					{
						continue;
					}
					if (lines[i].contains(needle))
					{
						offenders.add(file + ":" + (i + 1) + "  " + trimmed);
					}
				}
			}
		}
		return offenders;
	}
}

