package com.ironscape;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Three places in the plugin walk a step's annotation items and decide
 * whether each one has a vote. They must agree about which flags mean
 * "this is not an objective, so it gets no vote".
 *
 * <p>They drifted, and the drift was invisible for months because it
 * failed in the SILENT direction. {@code annotationItemsCarried} — the
 * arrival gate — skipped only {@code consumed} and money, while
 * {@code possessionObjectiveMet} and {@code purchaseListAcquired} also
 * skipped {@code optional} and {@code granted}. The consequence was that
 * the documented remedy for "this step will not tick" did nothing at all:
 * marking an item {@code optional} was applied three times across waves
 * 19, 26 and 27 (the ghost's skull, the Camelot lit candle, step 280's
 * dyes) and never unwedged anything, because the gate doing the blocking
 * never read the flag. Nine steps were blocked guide-wide when it was
 * finally measured.
 *
 * <p>Nothing in the compiler connects these three, and nothing in play
 * distinguishes "blocked by a wrongly-listed item" from "detection is
 * broken" — the owner sees only a step that will not tick. So the rule is
 * asserted on the source itself, the same way {@link HubComplianceTest}
 * asserts the hub's rules.
 *
 * <p>Deliberately NOT required of these gates: {@code ingredient} (a
 * material for something you make at the destination really is meant to
 * be in your bag) and unnumbered carry-list items (a bare "Lumby" ticks
 * on arriving PREPARED, never on jogging past — 51 steps depend on it).
 */
public class ItemGateConsistencyTest
{
	/**
	 * Methods that decide whether an annotation item gets a vote.
	 *
	 * <p>{@code gateableItems} rather than its caller {@code
	 * purchaseListAcquired}: the caller delegates the whole "which items
	 * count" question to it, so that is where the rule lives.
	 */
	private static final List<String> GATES = Arrays.asList(
		"annotationItemsCarried",
		"possessionObjectiveMet",
		"gateableItems");

	/** Flags that always mean "not an objective, so no vote". */
	private static final List<String> EXEMPTIONS = Arrays.asList("optional", "granted");

	@Test
	public void everyItemGateHonoursTheNotAnObjectiveFlags() throws IOException
	{
		String source = readPlugin();
		List<String> failures = new ArrayList<>();
		for (String gate : GATES)
		{
			String body = methodBody(source, gate);
			for (String flag : EXEMPTIONS)
			{
				if (!body.contains("need." + flag))
				{
					failures.add(gate + "() never reads need." + flag);
				}
			}
		}
		assertTrue("An item flagged as not-an-objective must not get a vote in ANY"
				+ " of the gates — otherwise marking an item optional silently"
				+ " changes nothing and a step stays blocked with no way to tell"
				+ " why. Missing:\n  " + String.join("\n  ", failures),
			failures.isEmpty());
	}

	private static String readPlugin() throws IOException
	{
		Path file = Paths.get("src/main/java/com/ironscape/IronscapePlugin.java");
		if (!Files.isRegularFile(file))
		{
			// Say so rather than pass silently, which is how a check stops
			// meaning anything (wave 25).
			throw new IOException("cannot find " + file + " from " + Paths.get("").toAbsolutePath());
		}
		return new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
	}

	/**
	 * The text of one method, from its DECLARATION to its closing brace, by
	 * counting braces. Crude, and enough: these are ordinary methods in one
	 * file, and a rename fails the test loudly rather than quietly passing —
	 * which is the failure mode that matters here.
	 *
	 * <p>The declaration is matched on its access modifier, NOT on the bare
	 * name. A plain name search finds the first CALL SITE instead — every
	 * one of these is called before it is declared — and then brace-matching
	 * from there reads some unrelated block. The first version of this test
	 * did exactly that and reported all three gates broken, including the
	 * two that were already correct.
	 */
	private static String methodBody(String source, String method)
	{
		java.util.regex.Matcher declaration = java.util.regex.Pattern
			// The dot matters: a return type can be qualified, as in
			// "private List<StepAnnotation.ItemNeed> gateableItems(...)".
			.compile("(private|protected|public)[\\w\\s.<>,\\[\\]]*\\b" + method + "\\s*\\(")
			.matcher(source);
		if (!declaration.find())
		{
			fail("no method DECLARATION named " + method + " in IronscapePlugin —"
				+ " if it was renamed, update GATES; if it was removed, say why here.");
		}
		int at = declaration.start();
		int open = source.indexOf('{', at);
		int depth = 0;
		for (int i = open; i < source.length(); i++)
		{
			char c = source.charAt(i);
			if (c == '{')
			{
				depth++;
			}
			else if (c == '}' && --depth == 0)
			{
				return source.substring(open, i + 1);
			}
		}
		fail("unbalanced braces reading " + method);
		return "";
	}
}

package com.ironscape.guide;

import com.google.gson.Gson;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * A real unit test (unlike IronscapePluginTest, which is the dev
 * launcher). Runs on every `gradlew build`.
 *
 * Deliberately asserts structural invariants rather than exact step counts,
 * so refreshing the bundled guide data doesn't break the build.
 */
public class GuideLoaderTest
{
	private final GuideLoader loader = new GuideLoader(new Gson());

	@Test
	public void loadsBothVariants() throws Exception
	{
		for (GuideVariant variant : GuideVariant.values())
		{
			Guide guide = loader.load(variant);

			assertEquals(variant, guide.getVariant());
			assertNotNull(guide.getUpdatedOn());
			assertTrue(variant + ": expected chapters", !guide.getChapters().isEmpty());
			assertTrue(variant + ": expected a substantial guide, got "
				+ guide.getAllSteps().size() + " steps", guide.getAllSteps().size() > 100);
		}
	}

	@Test
	public void atomicGuideStepsAreOneTickboxEach() throws Exception
	{
		// The Oziris guide writes one action per step — the panel must
		// mirror its step list exactly, never split it into clauses.
		Guide guide = loader.load(GuideVariant.OZIRIS);
		for (GuideStep step : guide.getAllSteps())
		{
			assertEquals("step " + step.getId() + " should be a single tickbox",
				1, step.getSubSteps().size());
		}
	}

	@Test
	public void stepIdsAreUniqueAndStable() throws Exception
	{
		Guide guide = loader.load(GuideVariant.OZIRIS);

		Set<String> ids = new HashSet<>();
		for (GuideStep step : guide.getAllSteps())
		{
			assertFalse("empty step text at global index " + step.getGlobalIndex(),
				step.getPlainText().trim().isEmpty());
			assertTrue("duplicate id " + step.getId(), ids.add(step.getId()));
			// the byId map must point back at the same step
			assertEquals(step, guide.getStepsById().get(step.getId()));

			assertFalse("step " + step.getId() + " has no sub-steps",
				step.getSubSteps().isEmpty());
			for (SubStep sub : step.getSubSteps())
			{
				assertTrue("sub id " + sub.getId() + " not under its parent",
					sub.getId().startsWith(step.getId() + ":"));
				assertTrue("duplicate sub id " + sub.getId(), ids.add(sub.getId()));
				assertFalse("empty sub-step text in " + step.getId(),
					sub.getPlainText().trim().isEmpty());
			}
		}

		// Hashing is deterministic: same text in, same id out — this is what
		// keeps progress and annotations valid across guide refreshes.
		assertEquals(GuideLoader.stepId("Some step text"), GuideLoader.stepId("some  STEP\ntext "));

		// Known value, shared with tools/extract-annotations.mjs — if this
		// ever fails, the Node script and the Java loader disagree on ids
		// and annotations would silently stop matching their steps.
		assertEquals("246d67e43e", GuideLoader.stepId("Some step text"));
	}

	@Test
	public void keepsMeaningfulFormatting() throws Exception
	{
		// Oziris step bodies are plain text; the formatting that matters
		// lives in additionalContent — green "Modern alternative" callouts
		// (color) and clickable map/safespot links (url).
		Guide guide = loader.load(GuideVariant.OZIRIS);

		boolean sawColor = false, sawLink = false;
		for (GuideStep step : guide.getAllSteps())
		{
			for (java.util.List<TextRun> paragraph : step.getAdditionalContent())
			{
				for (TextRun run : paragraph)
				{
					sawColor |= run.getColorHex() != null;
					sawLink |= run.getUrl() != null;
				}
			}
		}
		assertTrue("notes use colored callouts somewhere", sawColor);
		assertTrue("notes carry clickable links somewhere", sawLink);
	}
}

package com.ironscape.guide;

import com.ironscape.goals.GoalDetector;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.TreeSet;

/**
 * Tooling aid: prints every distinct item name the plugin tracks — text-
 * detected goals (via the REAL GoalDetector) plus bundled annotation item
 * lists — one per line. tools/seed-item-ids.mjs feeds this list to the
 * OSRS Wiki to build the bundled name -> item id map (sprites for
 * untradeables the price-list search can't resolve).
 */
public final class PrintItemNamesProbe
{
	public static void main(String[] args) throws Exception
	{
		TreeSet<String> names = new TreeSet<>();

		Guide guide = new GuideLoader(new Gson()).load(GuideVariant.OZIRIS);
		for (GoalDetector.ItemGoal goal : GoalDetector.detect(guide).getItemGoals())
		{
			names.add(goal.getItemName());
		}

		try (Reader reader = new InputStreamReader(
			PrintItemNamesProbe.class.getResourceAsStream(
				"/com/ironscape/annotations/annotations_oziris.json"), StandardCharsets.UTF_8))
		{
			JsonObject file = new Gson().fromJson(reader, JsonObject.class);
			for (Map.Entry<String, JsonElement> entry : file.getAsJsonObject("annotations").entrySet())
			{
				JsonElement items = entry.getValue().getAsJsonObject().get("items");
				if (items == null)
				{
					continue;
				}
				for (JsonElement item : items.getAsJsonArray())
				{
					names.add(item.getAsJsonObject().get("name").getAsString().toLowerCase());
				}
			}
		}

		names.forEach(System.out::println);
	}
}

package com.ironscape.guide;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class GuideManifestTest
{
	/** A guide whose single chapter has one section per id-list. */
	private static Guide guideOf(List<List<String>> sectionIds)
	{
		List<GuideSection> sections = new ArrayList<>();
		List<GuideStep> allSteps = new ArrayList<>();
		Map<String, GuideStep> byId = new LinkedHashMap<>();
		for (int si = 0; si < sectionIds.size(); si++)
		{
			List<GuideStep> steps = new ArrayList<>();
			for (int ti = 0; ti < sectionIds.get(si).size(); ti++)
			{
				String id = sectionIds.get(si).get(ti);
				GuideStep step = new GuideStep(id, 0, si, ti, allSteps.size(),
					"text of " + id, Collections.emptyList(), Collections.emptyList(),
					Collections.emptyList(), Collections.emptyList(), Collections.emptyMap());
				steps.add(step);
				allSteps.add(step);
				byId.put(id, step);
			}
			sections.add(new GuideSection("1." + (si + 1) + ": test", steps));
		}
		GuideChapter chapter = new GuideChapter("c1", sections, Collections.emptyList());
		return new Guide(GuideVariant.OZIRIS, "today", "test",
			Collections.singletonList(chapter), allSteps, byId);
	}

	private static List<GuideManifest.ManifestStep> manifestOf(List<List<String>> sectionIds)
	{
		List<GuideManifest.ManifestStep> steps = new ArrayList<>();
		for (int si = 0; si < sectionIds.size(); si++)
		{
			for (int ti = 0; ti < sectionIds.get(si).size(); ti++)
			{
				GuideManifest.ManifestStep step = new GuideManifest.ManifestStep();
				step.id = sectionIds.get(si).get(ti);
				step.chapter = 0;
				step.section = si;
				step.step = ti;
				steps.add(step);
			}
		}
		return steps;
	}

	@Test
	public void editedStepInPlaceIsRemapped()
	{
		List<GuideManifest.ManifestStep> previous =
			manifestOf(Arrays.asList(Arrays.asList("aaa", "bbb", "ccc")));
		Guide current = guideOf(Arrays.asList(Arrays.asList("aaa", "EDITED", "ccc")));

		Map<String, String> remap = GuideManifest.pairEditedSteps(previous, current);

		assertEquals(1, remap.size());
		assertEquals("EDITED", remap.get("bbb"));
	}

	@Test
	public void insertionSkipsTheWholeSection()
	{
		// A new step shifts every later index; positional pairing would
		// remap wrongly, so the section must be left alone.
		List<GuideManifest.ManifestStep> previous =
			manifestOf(Arrays.asList(Arrays.asList("aaa", "bbb")));
		Guide current = guideOf(Arrays.asList(Arrays.asList("aaa", "NEW", "bbb")));

		assertTrue(GuideManifest.pairEditedSteps(previous, current).isEmpty());
	}

	@Test
	public void reorderIsNotTreatedAsAnEdit()
	{
		// Both ids still exist — swapping positions must not remap.
		List<GuideManifest.ManifestStep> previous =
			manifestOf(Arrays.asList(Arrays.asList("aaa", "bbb")));
		Guide current = guideOf(Arrays.asList(Arrays.asList("bbb", "aaa")));

		assertTrue(GuideManifest.pairEditedSteps(previous, current).isEmpty());
	}

	@Test
	public void editsInOneSectionDoNotBlockAnother()
	{
		List<GuideManifest.ManifestStep> previous = manifestOf(Arrays.asList(
			Arrays.asList("aaa", "bbb"),
			Arrays.asList("ccc", "ddd")));
		Guide current = guideOf(Arrays.asList(
			Arrays.asList("aaa", "bbb", "INSERTED"), // count changed: skip
			Arrays.asList("ccc", "EDITED")));        // clean in-place edit

		Map<String, String> remap = GuideManifest.pairEditedSteps(previous, current);

		assertEquals(1, remap.size());
		assertEquals("EDITED", remap.get("ddd"));
	}

	@Test
	public void remapIdRewritesStepAndSubIds()
	{
		Map<String, String> remap = Collections.singletonMap("old123", "new456");

		assertEquals("new456", GuideManifest.remapId("old123", remap));
		assertEquals("new456:3", GuideManifest.remapId("old123:3", remap));
		assertEquals("other:1", GuideManifest.remapId("other:1", remap));
		assertEquals("untouched", GuideManifest.remapId("untouched", remap));
	}

	// --- sub-clause fingerprint matching ---

	/** A one-step guide whose step has the given clause texts as sub-steps. */
	private static Guide guideWithSubs(String id, String... clauses)
	{
		List<SubStep> subs = new ArrayList<>();
		for (int i = 0; i < clauses.length; i++)
		{
			subs.add(new SubStep(id + ":" + i, i, 0, clauses[i], Collections.emptyList()));
		}
		GuideStep step = new GuideStep(id, 0, 0, 0, 0,
			"text of " + id, Collections.emptyList(), subs,
			Collections.emptyList(), Collections.emptyList(), Collections.emptyMap());
		GuideChapter chapter = new GuideChapter("c1",
			Collections.singletonList(new GuideSection("1.1: test", Collections.singletonList(step))),
			Collections.emptyList());
		return new Guide(GuideVariant.OZIRIS, "today", "test",
			Collections.singletonList(chapter), Collections.singletonList(step),
			Collections.singletonMap(id, step));
	}

	/** A stored manifest for that same one-step guide, fingerprints included. */
	private static List<GuideManifest.ManifestStep> manifestWithSubs(String id, String... clauses)
	{
		GuideManifest.ManifestStep step = new GuideManifest.ManifestStep();
		step.id = id;
		step.chapter = 0;
		step.section = 0;
		step.step = 0;
		step.subs = new ArrayList<>();
		for (String clause : clauses)
		{
			step.subs.add(GuideLoader.stepId(clause));
		}
		return Collections.singletonList(step);
	}

	@Test
	public void subTicksFollowTheirTextWhenAClauseIsInserted()
	{
		// Upstream added a clause in the middle: positional carry would put
		// the old "bank the logs" tick on the NEW clause. Text matching
		// must follow the clause to its shifted position instead.
		List<GuideManifest.ManifestStep> previous =
			manifestWithSubs("old", "grab an axe", "bank the logs");
		Guide current = guideWithSubs("new", "grab an axe", "chop a tree", "bank the logs");

		Map<String, String> remap = GuideManifest.pairEditedSteps(previous, current);

		assertEquals("new", GuideManifest.remapId("old", remap));
		assertEquals("new:0", GuideManifest.remapId("old:0", remap));
		assertEquals("new:2", GuideManifest.remapId("old:1", remap));
	}

	@Test
	public void editedClauseOrphansItsTickInsteadOfMisattaching()
	{
		List<GuideManifest.ManifestStep> previous =
			manifestWithSubs("old", "grab an axe", "chop a tree", "bank the logs");
		Guide current = guideWithSubs("new", "grab an axe", "chop two trees", "bank the logs");

		Map<String, String> remap = GuideManifest.pairEditedSteps(previous, current);

		assertEquals("new:0", GuideManifest.remapId("old:0", remap));
		assertNull("the reworded clause's tick must be dropped, not carried",
			GuideManifest.remapId("old:1", remap));
		assertEquals("new:2", GuideManifest.remapId("old:2", remap));
	}

	@Test
	public void duplicateClausesPairUpInOrder()
	{
		List<GuideManifest.ManifestStep> previous =
			manifestWithSubs("old", "drink the potion", "drink the potion", "changed bit");
		Guide current = guideWithSubs("new", "drink the potion", "drink the potion", "CHANGED bit differently");

		Map<String, String> remap = GuideManifest.pairEditedSteps(previous, current);

		assertEquals("new:0", GuideManifest.remapId("old:0", remap));
		assertEquals("new:1", GuideManifest.remapId("old:1", remap));
		assertNull(GuideManifest.remapId("old:2", remap));
	}

	@Test
	public void splitterChangeOnUneditedStepRelinksSubTicksById()
	{
		// The step's text (and so its id) is unchanged, but OUR clause
		// splitter now cuts it differently: a clause merged away. Ticks
		// must follow their text; the vanished clause's tick is dropped.
		List<GuideManifest.ManifestStep> previous =
			manifestWithSubs("same", "while visiting jennifer", "buy shears", "then visit styles");
		Guide current = guideWithSubs("same", "while visiting jennifer, buy shears", "then visit styles");

		Map<String, String> remap = GuideManifest.pairEditedSteps(previous, current);

		assertNull(GuideManifest.remapId("same:0", remap));
		assertNull(GuideManifest.remapId("same:1", remap));
		assertEquals("same:1", GuideManifest.remapId("same:2", remap));
		// untouched ids (identity) aren't in the map and pass through
		assertEquals("other:0", GuideManifest.remapId("other:0", remap));
	}

	@Test
	public void manifestFromBeforeFingerprintsCarriesSubIndexPositionally()
	{
		// A version-1 manifest has no sub fingerprints — the old (index
		// carried as-is) behaviour must still apply rather than orphaning.
		List<GuideManifest.ManifestStep> previous =
			manifestOf(Arrays.asList(Arrays.asList("old")));
		Guide current = guideWithSubs("new", "grab an axe", "bank the logs");

		Map<String, String> remap = GuideManifest.pairEditedSteps(previous, current);

		assertEquals("new:1", GuideManifest.remapId("old:1", remap));
	}
}

package com.ironscape.guide;

import com.google.gson.Gson;

/**
 * Annotation authoring aid: prints the step id and every sub id (with its
 * clause text) for steps whose text contains the given search string —
 * the ids you need when hand-writing an annotation entry (e.g. a varbit
 * checkpoint keyed to "stepId:N").
 *
 * Run from the repo root, classpath = compiled classes + gson +
 * runelite-api + src/main/resources:
 *
 *   java -cp ... com.ironscape.guide.PrintSubIdProbe "Client of Kourend"
 */
public final class PrintSubIdProbe
{
	public static void main(String[] args) throws Exception
	{
		String needle = args.length > 0 ? args[0] : "Client of Kourend quest up to";
		Guide guide = new GuideLoader(new Gson()).load(GuideVariant.OZIRIS);
		for (GuideStep step : guide.getAllSteps())
		{
			if (!step.getPlainText().contains(needle))
			{
				continue;
			}
			System.out.println("step " + step.getId());
			for (SubStep sub : step.getSubSteps())
			{
				System.out.println("  " + sub.getId() + " | " + sub.getPlainText().trim());
			}
		}
	}
}

package com.ironscape.guide;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class SentenceSplitterTest
{
	private static TextRun plain(String text)
	{
		return new TextRun(text, false, false, false, false, null, null);
	}

	private static String join(List<TextRun> runs)
	{
		StringBuilder sb = new StringBuilder();
		runs.forEach(r -> sb.append(r.getText()));
		return sb.toString();
	}

	@Test
	public void splitsSentencesAndKeepsFormattingAcrossTheCut()
	{
		// One bold run spanning the end of sentence 1 and start of sentence 2.
		List<TextRun> runs = Arrays.asList(
			plain("Grab a knife. Talk to "),
			new TextRun("Duke Horacio. Burn logs", true, false, false, false, null, null),
			plain(" to 15 firemaking."));

		List<List<TextRun>> sentences = SentenceSplitter.split(runs);

		assertEquals(3, sentences.size());
		assertEquals("Grab a knife.", join(sentences.get(0)));
		assertEquals("Talk to Duke Horacio.", join(sentences.get(1)));
		assertEquals("Burn logs to 15 firemaking.", join(sentences.get(2)));
		// the bold style survived the slicing
		assertEquals(true, sentences.get(1).get(1).isBold());
		assertEquals("Duke Horacio.", sentences.get(1).get(1).getText());
	}

	@Test
	public void splitsAtNewlines()
	{
		List<List<TextRun>> sentences = SentenceSplitter.split(Arrays.asList(
			plain("do the thing\nthen the other thing\n")));

		assertEquals(2, sentences.size());
		assertEquals("do the thing", join(sentences.get(0)));
		assertEquals("then the other thing", join(sentences.get(1)));
	}

	@Test
	public void mergesTrivialFragmentsIntoThePreviousSentence()
	{
		// ")." alone is not a sentence; it belongs to the previous one.
		List<List<TextRun>> sentences = SentenceSplitter.split(Arrays.asList(
			plain("Choose a look (this is fine. ). Bank everything.")));

		assertEquals(2, sentences.size());
	}

	@Test
	public void splitsClausesAtCommasButNotInsideParentheses()
	{
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("Grab a knife, 2 buckets (hop once, if busy), cabbage, leather boots.")));

		assertEquals(4, clauses.size());
		assertEquals("Grab a knife", join(clauses.get(0)));
		assertEquals("2 buckets (hop once, if busy)", join(clauses.get(1)));
		assertEquals("cabbage", join(clauses.get(2)));
		assertEquals("leather boots.", join(clauses.get(3)));
	}

	@Test
	public void shortItemsLikeSawAndGpGetTheirOwnFragment()
	{
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("grab your hammer, saw, steel nails, one POH tab, GP, burnt meat")));

		assertEquals(6, clauses.size());
		assertEquals("saw", join(clauses.get(1)));
		assertEquals("GP", join(clauses.get(4)));
	}

	@Test
	public void doesNotSplitNumbersWithThousandsSeparators()
	{
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("Buy 1,500 arrow shafts")));

		assertEquals(1, clauses.size());
		assertEquals("Buy 1,500 arrow shafts", join(clauses.get(0)));
	}

	@Test
	public void leadingSubordinateFragmentStaysWithItsMainClause()
	{
		// "While visiting Jennifer" is not an action — it modifies "buy
		// shears". The comma after "shop" still cuts normally.
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("While visiting Jennifer, buy shears from her shop, then visit the Shayzien Styles.")));

		assertEquals(2, clauses.size());
		assertEquals("While visiting Jennifer, buy shears from her shop", join(clauses.get(0)));
		assertEquals("then visit the Shayzien Styles.", join(clauses.get(1)));
	}

	@Test
	public void midSentenceSubordinateGluesToTheClauseItIntroduces()
	{
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("Bank everything, once you are done, grab your hammer, saw")));

		assertEquals(3, clauses.size());
		assertEquals("Bank everything", join(clauses.get(0)));
		assertEquals("once you are done, grab your hammer", join(clauses.get(1)));
		assertEquals("saw", join(clauses.get(2)));
	}

	@Test
	public void sentenceFinalSubordinateGluesBackward()
	{
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("Buy shears from her shop, while visiting Jennifer")));

		assertEquals(1, clauses.size());
	}

	@Test
	public void chainedSubordinateFragmentsKeepAccumulating()
	{
		// Each comma is judged by the SEGMENT before it, so a subordinate
		// chain glues all the way to the action it belongs to.
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("After the quest, if you have spare gp, buy a chronicle, teleport away")));

		assertEquals(2, clauses.size());
		assertEquals("After the quest, if you have spare gp, buy a chronicle", join(clauses.get(0)));
	}

	@Test
	public void connectiveBeforeTheSubordinatorStillMerges()
	{
		List<List<TextRun>> clauses = SentenceSplitter.split(Arrays.asList(
			plain("Talk to the banker, and while you are there, deposit everything")));

		assertEquals(2, clauses.size());
		assertEquals("and while you are there, deposit everything", join(clauses.get(1)));
	}
}

package com.ironscape.goals;

import com.ironscape.guide.Guide;
import com.ironscape.guide.GuideChapter;
import com.ironscape.guide.GuideSection;
import com.ironscape.guide.GuideStep;
import com.ironscape.guide.GuideVariant;
import com.ironscape.guide.SubStep;
import com.ironscape.guide.TextRun;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.Quest;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GoalDetectorTest
{
	private static Guide guideWithSubTexts(String... texts)
	{
		List<SubStep> subs = Arrays.stream(texts)
			.map(t -> new SubStep("parent:" + t.hashCode(), 0, 0, t,
				Collections.singletonList(new TextRun(t, false, false, false, false, null, null))))
			.collect(Collectors.toList());
		GuideStep step = new GuideStep("parent", 0, 0, 0, 0, String.join(" ", texts),
			Collections.emptyList(), subs, Collections.emptyList(),
			Collections.emptyList(), Collections.emptyMap());
		GuideSection section = new GuideSection("1.1: test", Collections.singletonList(step));
		GuideChapter chapter = new GuideChapter("c1", Collections.singletonList(section), Collections.emptyList());
		return new Guide(GuideVariant.OZIRIS, "today", "test",
			Collections.singletonList(chapter),
			Collections.singletonList(step),
			Map.of(step.getId(), step));
	}

	@Test
	public void detectsItemGoalsWithQuantities()
	{
		Guide guide = guideWithSubTexts(
			"Grab 110 logs and bank them",
			"buy 20 balls of wool from the shop",
			"grab a knife"); // no number -> quantity 1

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(3, goals.getItemGoals().size());
		assertEquals("logs", goals.getItemGoals().get(0).getItemName());
		assertEquals(110, goals.getItemGoals().get(0).getQuantity());
		assertEquals("balls of wool", goals.getItemGoals().get(1).getItemName());
		assertEquals(20, goals.getItemGoals().get(1).getQuantity());
		assertEquals("knife", goals.getItemGoals().get(2).getItemName());
		assertEquals(1, goals.getItemGoals().get(2).getQuantity());
	}

	private static Guide guideWithMetadataStep(String text, Map<String, String> metadata)
	{
		SubStep sub = new SubStep("parent:0", 0, 0, text,
			Collections.singletonList(new TextRun(text, false, false, false, false, null, null)));
		GuideStep step = new GuideStep("parent", 0, 0, 0, 0, text,
			Collections.emptyList(), Collections.singletonList(sub), Collections.emptyList(),
			Collections.emptyList(), metadata);
		GuideSection section = new GuideSection("1.1: test", Collections.singletonList(step));
		GuideChapter chapter = new GuideChapter("c1", Collections.singletonList(section), Collections.emptyList());
		return new Guide(GuideVariant.OZIRIS, "today", "test",
			Collections.singletonList(chapter),
			Collections.singletonList(step),
			Map.of(step.getId(), step));
	}

	@Test
	public void metadataQuestTagBeatsAbbreviatedText()
	{
		// The text says "Barcrawl miniquest"; only the authored metadata
		// carries the real quest name.
		Guide guide = guideWithMetadataStep("Start Barcrawl miniquest",
			Map.of("quest", "Alfred Grimhand's Barcrawl", "questStatus", "start"));

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(1, goals.getQuestGoals().size());
		assertEquals(Quest.ALFRED_GRIMHANDS_BARCRAWL, goals.getQuestGoals().get(0).getQuest());
		assertFalse(goals.getQuestGoals().get(0).isRequiresFinished());
	}

	@Test
	public void bareQuestNameStepsStillGetTheirQuestGoal()
	{
		// No verb anywhere: "Cabin fever" is the whole step. These had NO
		// completion path at all — arrival was the only one left, and it is
		// gated on a kit the quest consumes, so they could never tick.
		Guide guide = guideWithMetadataStep("Cabin fever",
			Map.of("quest", "Cabin Fever", "questStatus", "complete"));

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(1, goals.getQuestGoals().size());
		assertTrue(goals.getQuestGoals().get(0).isRequiresFinished());
	}

	@Test
	public void aParentheticalAsideDoesNotHideTheQuestName()
	{
		Guide guide = guideWithMetadataStep(
			"Rum deal (Req 42 slayer, you should be close to it)",
			Map.of("quest", "Rum Deal", "questStatus", "complete"));

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(1, goals.getQuestGoals().size());
	}

	@Test
	public void questTagsTheGameSpellsDifferentlyStillResolve()
	{
		// The guide predates the sequel numbering; the game says
		// "Desert Treasure I". Exact-match alone found nothing.
		Guide guide = guideWithMetadataStep("Do Desert Treasure",
			Map.of("quest", "Desert Treasure", "questStatus", "complete"));

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(1, goals.getQuestGoals().size());
		assertEquals(Quest.DESERT_TREASURE_I, goals.getQuestGoals().get(0).getQuest());
	}

	@Test
	public void makeStepsProduceProductItemGoalsNotQuestGoals()
	{
		// "Make the hangover cure for plague city quest" is a PREP step:
		// completion = holding the cure, never Plague City's quest state
		// (the site tags it with the quest anyway).
		Guide guide = guideWithMetadataStep(
			"Make the hangover cure for plague city quest",
			Map.of("quest", "Plague City", "questStatus", "start"));

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getQuestGoals().isEmpty());
		assertEquals(1, goals.getItemGoals().size());
		assertEquals("hangover cure", goals.getItemGoals().get(0).getItemName());
	}

	@Test
	public void trainingStepsWithoutNumbersGetNoGoalsAtAll()
	{
		// "train construction with your planks" has no target number — a
		// counted goal of 1 ticked on the FIRST xp drop. The "until out of
		// planks" clause instead becomes a DEPLETION goal: done when the
		// planks are gone.
		Guide guide = guideWithSubTexts(
			"Use the housetab and train construction with your planks, make bookcases until out of planks");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getItemGoals().isEmpty());
		assertTrue(goals.getCountedSkillGoals().isEmpty());
		assertEquals(1, goals.getDepletionGoals().size());
		assertEquals("planks", goals.getDepletionGoals().get(0).getItemName());
	}

	@Test
	public void inTheseSkillsIsNotAnItem()
	{
		Guide guide = guideWithSubTexts(
			"Should now have 15 fletching and 20 construction as well, "
				+ "this will increase the xp you get in these skills from wintertodt");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getItemGoals().isEmpty());
		assertEquals(2, goals.getSkillLevelGoals().size());
	}

	@Test
	public void skillPhrasesWithTrailersAreLevelsNotItems()
	{
		// "20 construction AS WELL" became an item called "construction as
		// well", shadowing the level goals in evaluation.
		Guide guide = guideWithSubTexts(
			"Should now have 15 fletching and 20 construction as well, this will increase the xp");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getItemGoals().isEmpty());
		assertEquals(2, goals.getSkillLevelGoals().size());
	}

	@Test
	public void kSuffixGoldAndAtLeastLevels()
	{
		Guide guide = guideWithSubTexts(
			"Do Wintertodt until 200k cash, get at least 22 fletching at wintertodt as well");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		// "200k cash" -> 200,000 coins; "at least" must NOT be an item.
		assertEquals(1, goals.getItemGoals().size());
		assertEquals("cash", goals.getItemGoals().get(0).getItemName());
		assertEquals(200_000, goals.getItemGoals().get(0).getQuantity());
		boolean fletching22 = goals.getSkillLevelGoals().stream().anyMatch(
			g -> g.getSkill() == net.runelite.api.Skill.FLETCHING && g.getLevel() == 22);
		assertTrue(fletching22);
	}

	@Test
	public void homeTeleWithDestinationIsATravelGoal()
	{
		// One sub, two legs: the teleport ticks it, or arriving at the
		// destination (the LAST place mentioned) does.
		Guide guide = guideWithSubTexts(
			"Home tele to lumby and run north to Varrock east bank");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getItemGoals().isEmpty());
		assertEquals(1, goals.getTravelGoals().size());
	}

	@Test
	public void openEndedMakeLoopsAreNotProductGoals()
	{
		// The splitter puts this clause in its OWN sub, away from the
		// "train construction" clause — "until" alone must veto the
		// product goal (bookcases never enter the inventory).
		Guide guide = guideWithSubTexts("make bookcases until out of planks");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getItemGoals().isEmpty());
	}

	@Test
	public void plentyOfIsStrippedFromProductNames()
	{
		Guide guide = guideWithSubTexts(
			"Go Edgeville furnace and make plenty of digsite pendants");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(1, goals.getItemGoals().size());
		assertEquals("digsite pendants", goals.getItemGoals().get(0).getItemName());
	}

	@Test
	public void spellNamesContainingMakeAreNotItems()
	{
		// "Superglass Make lunar spell" — the spell's NAME contains
		// "make"; a spell is never an inventory item.
		Guide guide = guideWithSubTexts(
			"Train crafting using the superglass make lunar spell");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getItemGoals().isEmpty());
	}

	@Test
	public void metadataQuestTagIsIgnoredOnCheckpointSteps()
	{
		// "until <part>" steps complete via their varbit/varp annotation; a
		// started-state quest goal would tick them the moment the quest began.
		Guide guide = guideWithMetadataStep(
			"Do Waterfall quest until the part where you have to go to the gnome maze",
			Map.of("quest", "Waterfall Quest", "questStatus", "start"));

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		for (GoalDetector.QuestGoal goal : goals.getQuestGoals())
		{
			assertTrue("only a text-derived FINISHED goal is acceptable here",
				goal.isRequiresFinished());
		}
	}

	@Test
	public void minigameTeleShorthandIsDetected()
	{
		Guide guide = guideWithSubTexts("Minigame tele to Clan wars");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(1, goals.getMinigameTeleportGoals().size());
		assertEquals("Clan wars", goals.getMinigameTeleportGoals().get(0).getMinigame());
	}

	@Test
	public void prosePseudoQuantitiesAreNotItems()
	{
		Guide guide = guideWithSubTexts(
			"Hug the fence and run west, make sure you always have at least 15 energy",
			"Take out GP, Clue, air talisman and spade from the bank");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		// no "energy 0/15", no "out gp 0/1"
		for (GoalDetector.ItemGoal goal : goals.getItemGoals())
		{
			assertFalse(goal.getItemName(), goal.getItemName().contains("energy"));
			assertFalse(goal.getItemName(), goal.getItemName().startsWith("out"));
		}
	}

	@Test
	public void vagueQuantityWordsAreStrippedFromItemNames()
	{
		Guide guide = guideWithSubTexts("grab a few cakes from the bank");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(1, goals.getItemGoals().size());
		assertEquals("cakes", goals.getItemGoals().get(0).getItemName());
	}

	@Test
	public void locationPhrasesEndItemNames()
	{
		Guide guide = guideWithSubTexts(
			"Pick up 5 swamp tar around the swamp cave entrance",
			"Pick up 130 planks north of the Barb agility course");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(2, goals.getItemGoals().size());
		assertEquals("swamp tar", goals.getItemGoals().get(0).getItemName());
		assertEquals(5, goals.getItemGoals().get(0).getQuantity());
		assertEquals("planks", goals.getItemGoals().get(1).getItemName());
		assertEquals(130, goals.getItemGoals().get(1).getQuantity());
	}

	@Test
	public void herbCountsAsHerbloreNotAnItem()
	{
		// Oziris writes "UNTIL 77 herb" — a level target, not 77 herbs.
		Guide guide = guideWithSubTexts(
			"Use every book and lamp on Herblore UNTIL 77 herb, after that use them on agility");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertTrue(goals.getItemGoals().isEmpty());
		assertEquals(1, goals.getSkillLevelGoals().size());
		assertEquals(net.runelite.api.Skill.HERBLORE, goals.getSkillLevelGoals().get(0).getSkill());
		assertEquals(77, goals.getSkillLevelGoals().get(0).getLevel());
	}

	@Test
	public void agilityLapAndLeadingConnectiveProduceActionGoals()
	{
		Guide guide = guideWithSubTexts(
			"and do a lap of the Shayzien agility course for the diary.",
			"then chop a regular tree");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

