	/**
	 * "2.4m GP" read as "4m GP". The digit group could not cross a decimal
	 * point, so the match restarted after it and the FRACTION became the
	 * whole number - which is worse than dropping it, because the answer
	 * still looks like a plausible round figure. The owner saw the step ask
	 * for 4,000,000 where the guide says 2.4m (2026-08-28).
	 *
	 * <p>All 8 decimal quantities in the guide were wrong the same way, and
	 * "6.2k maples" -> 2,000 shows it is not only money.
	 */
	@Test
	public void decimalQuantitiesKeepTheirFraction()
	{
		Guide guide = guideWithSubTexts(
			"blackjack until you have 2.4m gp",
			"mine sandstone for 1.2k buckets of sand",
			"buy 200k gp worth of feathers");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		assertEquals(2_400_000, quantityOf(goals, "gp"));
		assertEquals(1_200, quantityOf(goals, "buckets of sand"));
		// the plain suffix form still works
		assertEquals(200_000, quantityOf(goals, "gp worth of feathers"));
	}

	/**
	 * A fraction with no k/m after it is not a count of anything, so it must
	 * not become one. Before the fix "step 1.1 of the guide" could hand the
	 * detector a "1" it had no business having.
	 */
	@Test
	public void aBareFractionIsNotAQuantity()
	{
		Guide guide = guideWithSubTexts("grab 2.5 logs from the pile");

		GoalDetector.Goals goals = GoalDetector.detect(guide);

		for (GoalDetector.ItemGoal goal : goals.getItemGoals())
		{
			assertNotEquals("2.5 must not become a count of logs",
				"logs", goal.getItemName());
		}
	}

	private static long quantityOf(GoalDetector.Goals goals, String name)
	{
		for (GoalDetector.ItemGoal goal : goals.getItemGoals())
		{
			if (name.equals(goal.getItemName()))
			{
				return goal.getQuantity();
			}
		}
		throw new AssertionError("no goal named \"" + name + "\" in " + goals.getItemGoals());
	}
}

package com.ironscape.goals;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.ironscape.guide.Guide;
import com.ironscape.guide.GuideLoader;
import com.ironscape.guide.GuideStep;
import com.ironscape.guide.GuideVariant;
import com.ironscape.guide.SubStep;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Guards the two conditions that make POSSESSION a safe completion path.
 *
 * Steps whose objective is having the things ("decant them until you have
 * like 6 full pots") carry their count in an annotation, because the
 * detector cannot name "6 full pots". Annotation items are display-only,
 * so those steps had NO completion path at all — a green 6/6 badge over a
 * checkbox nothing could tick.
 *
 * The wide rule ("no path + all numbered annotation items held") was
 * measured at 25 steps of which ~2 were right, because annotation items
 * are overwhelmingly what you BRING: a spade would tick all six "dig up
 * the clue" steps and the barcrawl card all ten bars. So the rule reads
 * the SENTENCE instead, and this test pins the blast radius at the two
 * steps that measurement approved.
 *
 * Both guards were checked by disabling them and re-running, and they are
 * NOT equally load-bearing today — worth knowing before anyone trims one:
 *
 *   parenthetical  PROVEN. Disable it and aReminderInsideBrackets fails;
 *                  the Brimstail reminder qualifies on text alone.
 *   checkpoint     PRECAUTIONARY. Disable it and everything still passes,
 *                  because the bracket guard already excludes the only
 *                  step where the two overlap. It is kept because wave 6
 *                  settled that an authored requires clause owns its sub —
 *                  the annotation exists precisely because a heuristic
 *                  fired early — and the next such step may not happen to
 *                  be bracketed.
 */
public class PossessionObjectiveTest
{
	/** Mirrors IronscapePlugin.PARENTHETICAL / POSSESSION_OBJECTIVE. */
	private static final Pattern PARENTHETICAL = Pattern.compile("\\([^)]*\\)");
	private static final Pattern POSSESSION_OBJECTIVE = Pattern.compile(
		"\\b(?:until you have|make sure you have|until you own|so you have)\\b",
		Pattern.CASE_INSENSITIVE);

	private JsonObject annotations() throws Exception
	{
		try (InputStream in = getClass().getResourceAsStream(
			"/com/ironscape/annotations/annotations_oziris.json"))
		{
			return new Gson()
				.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), JsonObject.class)
				.getAsJsonObject("annotations");
		}
	}

	/**
	 * Exactly the two measured steps qualify. If a third appears, it has
	 * not been reviewed — look at it before widening this number, because
	 * the failure mode is a step ticking itself off on the tools you
	 * happen to be carrying.
	 */
	@Test
	public void onlyTheReviewedStepsCompleteOnPossession() throws Exception
	{
		JsonObject annotations = annotations();
		Guide guide = new GuideLoader(new Gson()).load(GuideVariant.OZIRIS);
		List<String> qualifying = new ArrayList<>();

		for (GuideStep step : guide.getAllSteps())
		{
			for (SubStep sub : step.getSubSteps())
			{
				if (!isPossessionObjective(annotations, step, sub))
				{
					continue;
				}
				qualifying.add(sub.getPlainText().trim());
			}
		}

		assertEquals("possession-completable steps changed: " + qualifying,
			2, qualifying.size());
		assertTrue(qualifying.toString(), qualifying.stream()
			.anyMatch((t) -> t.startsWith("Hop worlds for super antipoison")));
		assertTrue(qualifying.toString(), qualifying.stream()
			.anyMatch((t) -> t.equals("Make sure you have all ghosts ahoy items")));
	}

	/**
	 * "Use Brimstails to go to ess mines (scrying orb 2/3, make sure you
	 * have it with you)" is a TRAVEL instruction with a reminder attached.
	 * Holding the orb must not tick it — it is the step wave 9 already had
	 * to stop completing early once.
	 *
	 * It fails the rule twice over, and both are asserted: the phrase is
	 * inside a parenthetical, and the sub carries a region checkpoint that
	 * owns its completion.
	 */
	@Test
	public void aReminderInsideBracketsIsNotAnObjective() throws Exception
	{
		JsonObject annotations = annotations();
		Guide guide = new GuideLoader(new Gson()).load(GuideVariant.OZIRIS);

		SubStep brimstail = null;
		GuideStep brimstailStep = null;
		for (GuideStep step : guide.getAllSteps())
		{
			for (SubStep sub : step.getSubSteps())
			{
				if (sub.getPlainText().contains("Use Brimstails to go to ess mines"))
				{
					brimstail = sub;
					brimstailStep = step;
				}
			}
		}
		assertTrue("the Brimstail step is gone from the guide", brimstail != null);

		assertTrue("the reminder is no longer bracketed — the guard is now load-bearing "
				+ "on the checkpoint alone",
			!POSSESSION_OBJECTIVE.matcher(
				PARENTHETICAL.matcher(brimstail.getPlainText()).replaceAll(" ")).find());
		assertTrue("the region checkpoint that actually completes this step is gone",
			hasRequirement(annotations, brimstailStep, brimstail));
		assertTrue(!isPossessionObjective(annotations, brimstailStep, brimstail));
	}

	private boolean hasRequirement(JsonObject annotations, GuideStep step, SubStep sub)
	{
		JsonObject entry = annotations.getAsJsonObject(annotationId(step, sub));
		JsonObject subEntry = annotations.getAsJsonObject(sub.getId());
		return (entry != null && entry.has("requires"))
			|| (subEntry != null && subEntry.has("requires"));
	}

	private String annotationId(GuideStep step, SubStep sub)
	{
		return step.getSubSteps().size() == 1 ? step.getId() : sub.getId();
	}

	private boolean isPossessionObjective(JsonObject annotations, GuideStep step, SubStep sub)
	{
		String text = PARENTHETICAL.matcher(sub.getPlainText()).replaceAll(" ");
		if (!POSSESSION_OBJECTIVE.matcher(text).find())
		{
			return false;
		}
		if (hasRequirement(annotations, step, sub))
		{
			return false;
		}
		JsonObject entry = annotations.getAsJsonObject(annotationId(step, sub));
		if (entry == null || !entry.has("items"))
		{
			return false;
		}
		for (JsonElement item : entry.getAsJsonArray("items"))
		{
			JsonObject need = item.getAsJsonObject();
			if (need.has("quantity") && !need.get("quantity").isJsonNull()
				&& need.get("quantity").getAsInt() > 0
				&& !isTrue(need, "granted") && !isTrue(need, "consumed")
				&& !isTrue(need, "optional") && !isTrue(need, "ingredient"))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isTrue(JsonObject need, String flag)
	{
		return need.has(flag) && !need.get(flag).isJsonNull() && need.get(flag).getAsBoolean();
	}
}

package com.ironscape.goals;

import com.google.gson.Gson;
import com.ironscape.guide.Guide;
import com.ironscape.guide.GuideLoader;
import com.ironscape.guide.GuideVariant;
import com.ironscape.items.ItemTracker;
import java.io.File;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

/**
 * Not a test of behaviour — a DUMP for tools/audit-goals.mjs: every
 * text-detected item goal with its full alias chain, written to
 * build/goal-audit.tsv on each test run. The Node checker matches the
 * aliases against the real OSRS item list and reports goals that can
 * never resolve (the "cow calf 0/1" class) all at once, instead of one
 * in-game surprise at a time.
 */
public class GoalAuditDumpTest
{
	/**
	 * id -> gameval ItemID constant name, for the item_ids.json key check:
	 * a key whose id is right but whose NAME isn't the real item ("notes
	 * for dwarf cannon" -> NULODIONS_NOTES) shows a correct sprite, passes
	 * the resolvability audit, and never counts a thing in play.
	 */
	@Test
	public void dumpItemIdConstants() throws Exception
	{
		File out = new File("build/item-id-constants.tsv");
		out.getParentFile().mkdirs();
		try (PrintWriter writer = new PrintWriter(out, StandardCharsets.UTF_8))
		{
			for (java.lang.reflect.Field field : net.runelite.api.gameval.ItemID.class.getFields())
			{
				if (field.getType() == int.class)
				{
					writer.println(field.getInt(null) + "\t" + field.getName());
				}
			}
		}
	}

	/**
	 * Every alias the REAL chain produces for each item_ids key, so the
	 * Node audit can ask "will this name ever match what you carry?"
	 * without reimplementing ItemTracker.
	 *
	 * That reimplementation was tried first and it does not work. A loose
	 * copy invented thirteen findings; a faithful copy of canonical()
	 * still cried wolf on "fally teletab" and "house teletabs", because
	 * the chain rewrites teletab->tab BEFORE the colloquial lookup, and
	 * on the normal/regular prefixes. Every one of those is a rule living
	 * in the chain, and a second copy of the chain is a second thing to
	 * keep in step — which is the audit-versus-plugin drift that let the
	 * black wizard hat through in the first place. Dump the truth instead.
	 */
	@Test
	public void dumpItemAliases() throws Exception
	{
		com.google.gson.JsonObject ids = new com.google.gson.Gson().fromJson(
			new java.io.InputStreamReader(
				com.ironscape.items.ItemTracker.class.getResourceAsStream("item_ids.json"),
				StandardCharsets.UTF_8),
			com.google.gson.JsonObject.class);
		com.google.gson.JsonObject map = ids.has("ids")
			? ids.getAsJsonObject("ids") : ids;
		File out = new File("build/item-aliases.tsv");
		out.getParentFile().mkdirs();
		try (PrintWriter writer = new PrintWriter(out, StandardCharsets.UTF_8))
		{
			for (String key : map.keySet())
			{
				String[] aliases = com.ironscape.items.ItemTracker.aliases(key);
				java.util.List<String> canonical = new java.util.ArrayList<>();
				for (String alias : aliases)
				{
					canonical.add(com.ironscape.items.ItemTracker.canonical(alias));
				}
				writer.println(key + "\t" + map.get(key).getAsInt()
					+ "\t" + String.join("|", aliases)
					+ "\t" + String.join("|", canonical));
			}
		}
	}

	/**
	 * How would each MOVEMENT-shaped sub prove arrival? TEXT = a place
	 * name in the sub's own text resolves; PIN = only the step's 📍 tag
	 * resolves (the fallback that anchored 'go to ess mines' on Gnome
	 * Stronghold — the ORIGIN — and false-ticked); NONE = nothing
	 * resolves, the sub can only be ticked manually. tools/audit-arrivals.mjs
	 * turns the PIN rows into the review list.
	 */
	@Test
	public void dumpArrivalResolution() throws Exception
	{
		Guide guide = new GuideLoader(new Gson()).load(GuideVariant.OZIRIS);
		com.ironscape.places.PlaceManager places =
			new com.ironscape.places.PlaceManager(new Gson(), new File("no-local-places.json"));
		places.load();
		GoalDetector.Goals goals = GoalDetector.detect(guide);
		java.util.Set<String> subsWithItems = new java.util.HashSet<>();
		for (GoalDetector.ItemGoal goal : goals.getItemGoals())
		{
			subsWithItems.add(goal.getSub().getId());
		}
		// Annotation keys whose completion is owned elsewhere: a ⌖ target
		// (precise arrival), an errand chain, or a varbit/varp/region
		// checkpoint. Raw-parse the bundled file — this dump runs without
		// a client.
		java.util.Set<String> owned = new java.util.HashSet<>();
		try (java.io.InputStream in = GoalAuditDumpTest.class.getResourceAsStream(
			"/com/ironscape/annotations/annotations_oziris.json"))
		{
			com.google.gson.JsonObject file = new Gson().fromJson(
				new java.io.InputStreamReader(in, StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			for (java.util.Map.Entry<String, com.google.gson.JsonElement> entry
				: file.getAsJsonObject("annotations").entrySet())
			{
				com.google.gson.JsonObject ann = entry.getValue().getAsJsonObject();
				boolean checkpoint = ann.has("requires")
					&& (ann.getAsJsonObject("requires").has("varbit")
						|| ann.getAsJsonObject("requires").has("varp")
						|| ann.getAsJsonObject("requires").has("region"));
				if (ann.has("target") || ann.has("errands") || checkpoint)
				{
					owned.add(entry.getKey());
				}
			}
		}
		// Keep in sync with IronscapePlugin.MOVEMENT_WORD + the
		// CHARTER/SPIRIT_TREE network-travel phrasing.
		java.util.regex.Pattern movement = java.util.regex.Pattern.compile(
			"\\b(?:go|walk|run|head|return|travel|enter|exit|climb|cross|move|proceed|sail|ride|fly|swim|tele|teleport|tabs?|charter)\\b|spirit tree",
			java.util.regex.Pattern.CASE_INSENSITIVE);
		File out = new File("build/arrival-audit.tsv");
		out.getParentFile().mkdirs();
		try (PrintWriter writer = new PrintWriter(out, StandardCharsets.UTF_8))
		{
			for (com.ironscape.guide.GuideStep step : guide.getAllSteps())
			{
				String location = step.getMetadata().get("location");
				for (com.ironscape.guide.SubStep sub : step.getSubSteps())
				{
					String text = sub.getPlainText();
					if (!movement.matcher(text).find()
						|| subsWithItems.contains(sub.getId())
						|| owned.contains(sub.getId()) || owned.contains(step.getId()))
					{
						continue;
					}
					net.runelite.api.coords.WorldPoint fromText = places.lastPlaceIn(text);
					if (fromText == null)
					{
						fromText = places.firstPlaceIn(text);
					}
					net.runelite.api.coords.WorldPoint fromPin =
						location == null ? null : places.getLoose(location);
					String source = fromText != null ? "TEXT" : fromPin != null ? "PIN" : "NONE";
					writer.println("ARRIVAL\t" + sub.getId()
						+ "\t" + source
						+ "\t" + (location == null ? "" : location)
						+ "\t" + text.trim().replaceAll("[\\t\\r\\n]+", " "));
				}
			}
		}
	}

	/**
	 * Every RuneLite Quest enum name. The guide's `quest` metadata has to
	 * match one of these EXACTLY today, and several do not — the wiki and
	 * the game disagree about articles ("The Hand in the Sand"), spelling
	 * ("Tranquillity"), and sequel numbering ("Desert Treasure I"). Dumped
	 * so the mismatches can be found by diff rather than by memory.
	 */
	@Test
	public void dumpQuestNames() throws Exception
	{
		File out = new File("build/quest-names.tsv");
		out.getParentFile().mkdirs();
		try (PrintWriter writer = new PrintWriter(out, StandardCharsets.UTF_8))
		{
			for (net.runelite.api.Quest quest : net.runelite.api.Quest.values())
			{
				writer.println("QUEST\t" + quest.name() + "\t" + quest.getName());
			}
		}
	}

	/**
	 * The plugin's MOVEMENT_WORD pattern, verbatim.
	 *
	 * tools/preflight.mjs has to know which subs read as travel
	 * instructions, because that is what decides whether a step with no
	 * detector can still tick by walking there. It used to keep its own
	 * hand-copied regex, which is the same shape of fault as the percent
	 * codec that drifted the moment encode and decode lived in two
	 * classes: the copy is right until someone edits one side, and then
	 * the check confidently reports a step as tickable that the plugin
	 * cannot tick. Dumping the real pattern means there is only one.
	 */
	@Test
	public void dumpMovementWord() throws Exception
	{
		java.lang.reflect.Field field =
			com.ironscape.IronscapePlugin.class.getDeclaredField("MOVEMENT_WORD");
		field.setAccessible(true);
		java.util.regex.Pattern pattern = (java.util.regex.Pattern) field.get(null);

		File out = new File("build/movement-word.txt");
		out.getParentFile().mkdirs();
		try (PrintWriter writer = new PrintWriter(out, StandardCharsets.UTF_8))
		{
			writer.println(pattern.pattern());
		}
	}

	/**
	 * Which detector path can complete each sub, and what the annotation
	 * file says about it. Written for tools/audit-item-gating.mjs: whether
	 * making annotation items gate completion CHANGES a step depends
	 * entirely on how that step completes today — a travel/arrival sub is
	 * already gated by annotationItemsCarried, an item-goal sub is not.
	 * Inferring that from step text (as the first cut of the audit did)
	 * over-counts; this dumps the detector's own answer.
	 */
	@Test
	public void dumpCompletionPaths() throws Exception
	{
		Guide guide = new GuideLoader(new Gson()).load(GuideVariant.OZIRIS);
		GoalDetector.Goals goals = GoalDetector.detect(guide);

		java.util.Map<String, java.util.Set<String>> paths = new java.util.HashMap<>();
		java.util.function.BiConsumer<String, String> mark = (subId, kind) ->
			paths.computeIfAbsent(subId, k -> new java.util.TreeSet<>()).add(kind);

		for (GoalDetector.ItemGoal g : goals.getItemGoals())
		{
			mark.accept(g.getSub().getId(), g.isAcquisition() ? "item-buy" : "item");
		}
		for (GoalDetector.QuestGoal g : goals.getQuestGoals())
		{
			mark.accept(g.getSub().getId(), g.isRequiresFinished() ? "quest-finish" : "quest-start");
		}
		for (GoalDetector.SkillActionGoal g : goals.getSkillActionGoals())
		{
			mark.accept(g.getSub().getId(), "xp-drop");
		}
		for (GoalDetector.TravelGoal g : goals.getTravelGoals())
		{
			mark.accept(g.getSub().getId(), "travel");
		}
		for (GoalDetector.InteractionGoal g : goals.getInteractionGoals())
		{
			mark.accept(g.getSub().getId(), "interaction");
		}
		for (GoalDetector.CountedSkillGoal g : goals.getCountedSkillGoals())
		{
			mark.accept(g.getSub().getId(), "counted");
		}
		for (GoalDetector.SkillLevelGoal g : goals.getSkillLevelGoals())
		{
			mark.accept(g.getSub().getId(), "level");
		}

		// WHICH skills, not just that there were some. A level the step only
		// MENTIONS ("After 50 agility, minigame tele to Burthrope") is not a
		// completion path, and reporting it as one made preflight promise an
		// auto-tick that IronscapePlugin will not perform.
		java.util.Map<String, java.util.List<String>> levelSkills = new java.util.HashMap<>();
		for (GoalDetector.SkillLevelGoal g : goals.getSkillLevelGoals())
		{
			levelSkills.computeIfAbsent(g.getSub().getId(), k -> new java.util.ArrayList<>())
				.add(g.getSkill().name());
		}
		for (GoalDetector.DepletionGoal g : goals.getDepletionGoals())
		{
			mark.accept(g.getSub().getId(), "depletion");
		}

		// Detector goals are not the only way a sub completes, and pretending
		// otherwise made this dump LIE in the safe-looking direction: it
		// reported 164 subs as having no completion path, and the first one
		// examined ("Use Brimstails to go to ess mines") completes perfectly
		// well off an annotated region checkpoint. Every consumer treats
		// "none" as "only a human can tick this" — preflight's hand-tick
		// count, audit-item-gating's blast radius — so an under-count here
		// becomes an over-count of work everywhere downstream.
		//
		// Annotations carry two completion paths of their own: an authored
		// requires clause (varbit/varp/region/equipped), which OWNS its sub
		// and outranks every heuristic; and possession, for steps whose
		// sentence makes having the items the objective.
		com.google.gson.JsonObject annotations;
		try (java.io.InputStream in = GoalAuditDumpTest.class.getResourceAsStream(
			"/com/ironscape/annotations/annotations_oziris.json"))
		{
			annotations = new Gson()
				.fromJson(new java.io.InputStreamReader(in, StandardCharsets.UTF_8),
					com.google.gson.JsonObject.class)
				.getAsJsonObject("annotations");
		}
		// Mirrors IronscapePlugin.possessionObjectiveMet — see the guards
		// there. Kept in step with it by dumping the same two conditions,
		// not by re-deriving them from step text.
		java.util.regex.Pattern parenthetical = java.util.regex.Pattern.compile("\\([^)]*\\)");
		java.util.regex.Pattern possession = java.util.regex.Pattern.compile(
			"\\b(?:until you have|make sure you have|until you own|so you have)\\b",
			java.util.regex.Pattern.CASE_INSENSITIVE);

		File out = new File("build/completion-paths.tsv");
		out.getParentFile().mkdirs();
		try (PrintWriter writer = new PrintWriter(out, StandardCharsets.UTF_8))
		{
			for (com.ironscape.guide.GuideStep step : guide.getAllSteps())
			{
				for (com.ironscape.guide.SubStep sub : step.getSubSteps())
				{
					String annotationId = step.getSubSteps().size() == 1
						? step.getId() : sub.getId();
					com.google.gson.JsonObject entry = annotations.getAsJsonObject(annotationId);
					com.google.gson.JsonObject subEntry = annotations.getAsJsonObject(sub.getId());
					boolean checkpoint = (entry != null && entry.has("requires"))
						|| (subEntry != null && subEntry.has("requires"));
					if (checkpoint)
					{
						mark.accept(sub.getId(), "checkpoint");
					}
					else if (possession.matcher(
						parenthetical.matcher(sub.getPlainText()).replaceAll(" ")).find()
						&& entry != null && entry.has("items"))
					{
						for (com.google.gson.JsonElement item : entry.getAsJsonArray("items"))
						{
							com.google.gson.JsonObject need = item.getAsJsonObject();
							if (need.has("quantity") && !need.get("quantity").isJsonNull()
								&& need.get("quantity").getAsInt() > 0)
							{
								mark.accept(sub.getId(), "possession");
								break;
							}
						}
					}
					java.util.Set<String> kinds = paths.get(sub.getId());
					// Mirrors IronscapePlugin.informationalLevel: sub id first, then
					// the step. If EVERY level the sub names is one it merely
					// mentions, there is no level path here at all.
					java.util.Set<String> mentioned = new java.util.HashSet<>();
					for (com.google.gson.JsonObject source : new com.google.gson.JsonObject[]{subEntry, entry})
					{
						if (source == null || !source.has("informationalLevels"))
						{
							continue;
						}
						for (com.google.gson.JsonElement named : source.getAsJsonArray("informationalLevels"))
						{
							mentioned.add(named.getAsString().toUpperCase(java.util.Locale.ROOT));
						}
					}
					if (kinds != null && kinds.contains("level") && !mentioned.isEmpty())
					{
						boolean anyRealLevel = false;
						for (String skill : levelSkills.getOrDefault(sub.getId(),
							java.util.Collections.emptyList()))
						{
							anyRealLevel |= !mentioned.contains(skill);
						}
						if (!anyRealLevel)
						{
							kinds = new java.util.TreeSet<>(kinds);
							kinds.remove("level");
							if (kinds.isEmpty())
							{
								kinds = null;
							}
						}
					}
					// A step that declares its items ARE the finish line is finished by
					// those and nothing else, so the detector paths do not apply to it.
					if (declaresItemFinish(entry) || declaresItemFinish(subEntry))
					{
						kinds = java.util.Collections.singleton("possession");
					}
					writer.println("PATH\t" + sub.getId()
						+ "\t" + (kinds == null ? "none" : String.join(",", kinds))
						+ "\t" + sub.getPlainText().trim().replaceAll("[\\t\\r\\n]+", " "));
				}
			}
		}
	}

	/** Does this annotation say holding its items is what finishes the step? */
	private static boolean declaresItemFinish(com.google.gson.JsonObject entry)
	{
		return entry != null && entry.has("completeOnItems")
			&& !entry.get("completeOnItems").isJsonNull()
			&& entry.get("completeOnItems").getAsBoolean();
	}

	@Test
	public void dumpGoals() throws Exception
	{
		Guide guide = new GuideLoader(new Gson()).load(GuideVariant.OZIRIS);
		GoalDetector.Goals goals = GoalDetector.detect(guide);
		File out = new File("build/goal-audit.tsv");
		out.getParentFile().mkdirs();
		java.util.Set<String> subsWithItems = new java.util.HashSet<>();
		for (GoalDetector.ItemGoal goal : goals.getItemGoals())
		{
			subsWithItems.add(goal.getSub().getId());
		}
		try (PrintWriter writer = new PrintWriter(out, StandardCharsets.UTF_8))
		{
			for (GoalDetector.ItemGoal goal : goals.getItemGoals())
			{
				writer.println("ITEM\t" + goal.getSub().getId()
					+ "\t" + goal.getQuantity()
					+ "\t" + goal.getItemName()
					+ "\t" + String.join("|", ItemTracker.aliases(goal.getItemName()))
					+ "\t" + goal.getSub().getPlainText().trim()
						.replaceAll("[\\t\\r\\n]+", " "));
			}
			// The audit's other blind spot: a BUY sub where detection
			// produced NO goal at all (the "1 PACK of eyes of newt and
			// pestle and mortar" class — nothing to resolve, nothing red,
			// just silently untracked).
			for (com.ironscape.guide.GuideStep step : guide.getAllSteps())
			{
				for (com.ironscape.guide.SubStep sub : step.getSubSteps())
				{
					String text = sub.getPlainText();
					if (!subsWithItems.contains(sub.getId())
						&& text.toLowerCase().matches(".*\\b(?:buy|purchase|grab)\\b.*"))
					{
						writer.println("NOGOAL\t" + sub.getId() + "\t"
							+ text.trim().replaceAll("[\\t\\r\\n]+", " "));
					}
				}
			}
		}
	}
}

package com.ironscape.travel;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The rules that decide whether a teleport item is offered.
 *
 * Worth testing rather than eyeballing because every one of these
 * failures is silent in play: a teleport wrongly offered just looks like
 * a hint, and a teleport wrongly withheld looks like nothing at all.
 */
public class TeleportItemsTest
{
	/** Answers whatever the test sets, and NOTHING by default. */
	private static final class FakeState implements TeleportItems.Availability
	{
		final Set<Integer> carried = new HashSet<>();
		final Map<Integer, Integer> varbits = new HashMap<>();
		final Map<Integer, Integer> varplayers = new HashMap<>();
		final Map<String, Integer> skills = new HashMap<>();
		final Set<String> finishedQuests = new HashSet<>();
		int total = 0;
		int questPoints = 0;

		@Override
		public boolean carries(int itemId)
		{
			return carried.contains(itemId);
		}

		@Override
		public int varbit(int id)
		{
			return varbits.getOrDefault(id, 0);
		}

		@Override
		public int varplayer(int id)
		{
			return varplayers.getOrDefault(id, 0);
		}

		@Override
		public int skillLevel(String skill)
		{
			return skills.getOrDefault(skill, -1);
		}

		@Override
		public int totalLevel()
		{
			return total;
		}

		@Override
		public int questPoints()
		{
			return questPoints;
		}

		@Override
		public boolean questFinished(String questName)
		{
			return finishedQuests.contains(questName);
		}
	}

	private static TeleportItems.Entry parse(String json)
	{
		TeleportItems.Entry[] entries = new Gson().fromJson("[" + json + "]", TeleportItems.Entry[].class);
		return entries[0];
	}

	private final TeleportItems index = TeleportItems.load(new Gson());

	@Test
	public void bundledIndexLoads()
	{
		// The whole feature is data. If the resource stops loading, every
		// test below still passes against hand-built entries while the
		// plugin silently suggests nothing.
		assertTrue("bundled teleport index should not be empty", index.size() > 100);
	}

	@Test
	public void everyBundledEntryHasADestinationAndItems()
	{
		for (TeleportItems.Entry entry : index.all())
		{
			assertNotNull("entry with no label", entry.getDisplay());
			assertTrue("no item provides " + entry.getDisplay(), entry.getItemIds().length > 0);
			assertNotNull("no destination for " + entry.getDisplay(), entry.getDestination());
		}
	}

	@Test
	public void anyOneOfTheItemsIsEnough()
	{
		// The tiers of a diary cloak are alternatives, not a set to collect.
		TeleportItems.Entry cloak = parse(
			"{\"display\":\"Ardougne cloak: Kandarin Monastery\",\"itemIds\":[13121,13122,13123],"
				+ "\"x\":2607,\"y\":3221,\"plane\":0}");
		FakeState state = new FakeState();
		assertFalse(index.isAvailable(cloak, state));
		state.carried.add(13123);
		assertTrue(index.isAvailable(cloak, state));
	}

	@Test
	public void unlockVarbitGatesTheTeleport()
	{
		// Holding the cloak is not the same as having earned the tier that
		// unlocks this particular destination.
		TeleportItems.Entry farm = parse(
			"{\"display\":\"Ardougne cloak: Ardougne Farm\",\"itemIds\":[13123],"
				+ "\"x\":2665,\"y\":3374,\"plane\":0,"
				+ "\"varbits\":[{\"id\":4460,\"op\":\"=\",\"value\":1}]}");
		FakeState state = new FakeState();
		state.carried.add(13123);
		assertFalse("diary not done — must not be offered", index.isAvailable(farm, state));
		state.varbits.put(4460, 1);
		assertTrue(index.isAvailable(farm, state));
	}

	@Test
	public void chargesRunOut()
	{
		// "fewer than 5 used" — a less-than condition, which is how the
		// source data expresses remaining charges.
		TeleportItems.Entry limited = parse(
			"{\"display\":\"Ardougne cloak: Ardougne Farm\",\"itemIds\":[13123],"
				+ "\"x\":2665,\"y\":3374,\"plane\":0,"
				+ "\"varbits\":[{\"id\":6069,\"op\":\"<\",\"value\":5}]}");
		FakeState state = new FakeState();
		state.carried.add(13123);
		state.varbits.put(6069, 4);
		assertTrue(index.isAvailable(limited, state));
		state.varbits.put(6069, 5);
		assertFalse("no charges left — must not be offered", index.isAvailable(limited, state));
	}

	@Test
	public void bitmaskNeedsThatExactBit()
	{
		// The barcrawl trap: a `>=` here would let any other bit in the
		// same var satisfy an unrelated unlock.
		TeleportItems.Entry masked = parse(
			"{\"display\":\"Test\",\"itemIds\":[1],\"x\":1,\"y\":1,\"plane\":0,"
				+ "\"varbits\":[{\"id\":50,\"op\":\"&\",\"value\":4}]}");
		FakeState state = new FakeState();
		state.carried.add(1);
		state.varbits.put(50, 3);
		assertFalse("bits 1 and 2 set, bit 4 is not", index.isAvailable(masked, state));
		state.varbits.put(50, 5);
		assertTrue("bit 4 set alongside bit 1", index.isAvailable(masked, state));
	}

	@Test
	public void questGateFailsClosedOnAnUnknownName()
	{
		TeleportItems.Entry gated = parse(
			"{\"display\":\"Test\",\"itemIds\":[1],\"x\":1,\"y\":1,\"plane\":0,"
				+ "\"quests\":[\"Not A Real Quest\"]}");
		FakeState state = new FakeState();
		state.carried.add(1);
		assertFalse("an unresolved quest name must withhold the hint",
			index.isAvailable(gated, state));
	}

	@Test
	public void totalLevelAndQuestPointsAreNotSkills()
	{
		// The source data puts the max cape's total level and the quest
		// cape's quest points in the SKILLS column. Read as skill names
		// they resolve to nothing and the gate would fail forever.
		TeleportItems.Entry maxCape = parse(
			"{\"display\":\"Max cape\",\"itemIds\":[1],\"x\":1,\"y\":1,\"plane\":0,"
				+ "\"skills\":[{\"level\":2376,\"skill\":\"TOTAL\"}]}");
		FakeState state = new FakeState();
		state.carried.add(1);
		assertFalse(index.isAvailable(maxCape, state));
		state.total = 2376;
		assertTrue(index.isAvailable(maxCape, state));

		TeleportItems.Entry questCape = parse(
			"{\"display\":\"Quest cape\",\"itemIds\":[2],\"x\":1,\"y\":1,\"plane\":0,"
				+ "\"skills\":[{\"level\":327,\"skill\":\"QUEST\"}]}");
		state.carried.add(2);
		assertFalse(index.isAvailable(questCape, state));
		state.questPoints = 327;
		assertTrue(index.isAvailable(questCape, state));
	}

	@Test
	public void unknownSkillNameFailsClosed()
	{
		TeleportItems.Entry odd = parse(
			"{\"display\":\"Test\",\"itemIds\":[1],\"x\":1,\"y\":1,\"plane\":0,"
				+ "\"skills\":[{\"level\":50,\"skill\":\"NOTASKILL\"}]}");
		FakeState state = new FakeState();
		state.carried.add(1);
		assertFalse(index.isAvailable(odd, state));
	}

	@Test
	public void availableListsOnlyWhatCanBeUsedNow()
	{
		FakeState nothing = new FakeState();
		assertEquals("carrying nothing means no teleports",
			0, index.available(nothing).size());
	}

	@Test
	public void itemLabelDropsTheDestination()
	{
		assertEquals("Ardougne cloak", parse(
			"{\"display\":\"Ardougne cloak: Kandarin Monastery\",\"itemIds\":[1],"
				+ "\"x\":1,\"y\":1,\"plane\":0}").itemLabel());
		assertEquals("Digsite teleport", parse(
			"{\"display\":\"Digsite teleport\",\"itemIds\":[1],\"x\":1,\"y\":1,\"plane\":0}")
			.itemLabel());
	}
}

package com.ironscape.travel;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The travel table is generated by tools/build-travel-distances.mjs from a
 * list of landings that lives in TWO other places — minigame_landings.json and
 * the TELEPORT_SPELLS / SPIRIT_TREES constants in IronscapePlugin. Nothing at
 * runtime notices when those drift apart: a renamed landing simply answers
 * UNKNOWN and the hint quietly falls back to the straight lines this table
 * exists to replace. That is the failure the bundled-places test was written
 * for after a duplicate JSON key took every place link down with one swallowed
 * warning, so it gets the same treatment — fail the build, not the play session.
 */
public class TravelDistancesTest
{
	/** Mirrors TELEPORT_SPELLS in IronscapePlugin (name only; coordinates live there). */
	private static final List<String> SPELLS = Arrays.asList(
		"Varrock Teleport", "Lumbridge Teleport", "Falador Teleport",
		"Camelot Teleport", "Ardougne Teleport", "Watchtower Teleport");

	/** Mirrors SPIRIT_TREE_ORIGINS in IronscapePlugin. */
	private static final List<String> TREES = Arrays.asList(
		"Spirit Tree: Tree Gnome Village", "Spirit Tree: Gnome Stronghold",
		"Spirit Tree: Battlefield of Khazard", "Spirit Tree: Grand Exchange",
		"Spirit Tree: Feldip Hills");

	@Test
	public void tableLoads()
	{
		assertTrue("travel_distances.bin.gz failed to load", new TravelDistances().isLoaded());
	}

	@Test
	public void everyLandingHasAField() throws Exception
	{
		TravelDistances travel = new TravelDistances();
		try (InputStream in = TravelDistances.class
			.getResourceAsStream("/com/ironscape/places/minigame_landings.json"))
		{
			assertNotNull("minigame_landings.json missing", in);
			JsonObject landings = new Gson().fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), JsonObject.class)
				.getAsJsonObject("landings");
			for (String name : landings.keySet())
			{
				assertTrue("no travel field for minigame landing '" + name
					+ "' — re-run tools/build-travel-distances.mjs",
					travel.origins().contains(name));
			}
		}
		for (String name : SPELLS)
		{
			assertTrue("no travel field for spell '" + name + "'", travel.origins().contains(name));
		}
		for (String name : TREES)
		{
			assertTrue("no travel field for '" + name + "'", travel.origins().contains(name));
		}
		assertTrue("no travel field for the free home teleport",
			travel.origins().contains("Home Teleport"));
	}

	/**
	 * The case the whole thing was built for. Keep Le Faye is closer to
	 * Burthorpe than to the Fishing Trawler landing in a straight line, and
	 * further once White Wolf Mountain is in the way.
	 */
	@Test
	public void aMountainCostsMoreThanTheStraightLineSays()
	{
		TravelDistances travel = new TravelDistances();
		WorldPoint keepLeFaye = new WorldPoint(2757, 3401, 0);
		int burthorpe = travel.distance("Burthorpe Games Room", keepLeFaye);
		int trawler = travel.distance("Fishing Trawler", keepLeFaye);
		assertTrue("Burthorpe unknown", burthorpe > 0);
		assertTrue("Fishing Trawler unknown", trawler > 0);
		assertTrue("walking from Burthorpe (" + burthorpe + ") should cost more than"
			+ " from the Fishing Trawler (" + trawler + ") despite being nearer in a"
			+ " straight line", burthorpe > trawler);
	}

	/** Distances have to be plausible, not just present. */
	@Test
	public void knownShortWalksReadShort()
	{
		TravelDistances travel = new TravelDistances();
		int seers = travel.distance("Camelot Teleport", new WorldPoint(2725, 3491, 0));
		assertTrue("Camelot teleport to Seers' bank read " + seers + " tiles",
			seers > 0 && seers < 60);
		int falador = travel.distance("Falador Teleport", new WorldPoint(3013, 3355, 0));
		assertTrue("Falador teleport to the east bank read " + falador + " tiles",
			falador > 0 && falador < 150);
	}

	/**
	 * A landing with no ungated route to the mainland must say so rather than
	 * guess. Mos Le'Harmless is behind Cabin Fever; answering UNKNOWN is what
	 * keeps it out of the ranking instead of winning on a straight line drawn
	 * across the sea.
	 */
	@Test
	public void gatedRegionsAnswerUnknown()
	{
		TravelDistances travel = new TravelDistances();
		assertEquals("Trouble Brewing should have no ungated route to Varrock",
			TravelDistances.UNKNOWN,
			travel.distance("Trouble Brewing", new WorldPoint(3213, 3424, 0)));
	}
}

package com.ironscape.progress;

import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ProgressManagerTest
{
	@Test
	public void countsSurviveEncodeDecodeRoundTrip()
	{
		Map<String, Integer> counts = new LinkedHashMap<>();
		counts.put("s1-14:0", 3);
		counts.put("s2-7:2", 12);

		Map<String, Integer> decoded = ProgressManager.decodeCounts(ProgressManager.encodeCounts(counts));

		assertEquals(counts, decoded);
	}

	@Test
	public void emptyAndNullDecodeToNothing()
	{
		assertTrue(ProgressManager.decodeCounts(null).isEmpty());
		assertTrue(ProgressManager.decodeCounts("").isEmpty());
		assertEquals("", ProgressManager.encodeCounts(new LinkedHashMap<>()));
	}

	@Test
	public void corruptedEntriesAreDroppedWithoutLosingTheRest()
	{
		Map<String, Integer> decoded = ProgressManager.decodeCounts(
			"s1-14:0=3,garbage,=5,s2-7:2=notanumber,s3-1:0=7");

		assertEquals(2, decoded.size());
		assertEquals(Integer.valueOf(3), decoded.get("s1-14:0"));
		assertEquals(Integer.valueOf(7), decoded.get("s3-1:0"));
	}
}

package com.ironscape.overlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Collections;
import java.util.Locale;
import java.util.Set;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

/**
 * Highlights the right destination inside the game's generic travel menu
 * ("Spirit Tree Locations", gnome gliders — any Adventure Log-style list,
 * interface group 187). An entry lights up when every word of its name
 * appears in the current sub-step's text or the step's 📍 location tag,
 * so "Use the spirit tree and go to battlefield of khazard" highlights
 * "3: Battlefield of Khazard". Word-SET matching, not phrase matching:
 * the guide says "Khazard Battlefield", the menu "Battlefield of Khazard".
 *
 * The plugin supplies the word set once per tick; render only does widget
 * reads, so an open menu costs nothing while no travel sub is current.
 */
@Singleton
public class TravelMenuOverlay extends Overlay
{
	private static final Color HIGHLIGHT = new Color(0, 255, 128);
	private static final Color FILL = new Color(0, 255, 128, 40);

	/** Words like "of" carry no meaning; they must not block a match. */
	private static final Set<String> STOPWORDS = Set.of("of", "the", "a", "an", "your");

	private final Client client;

	/** Lowercased words of the current sub + location tag; empty = hidden. */
	private Supplier<Set<String>> wordsSupplier = Collections::emptySet;

	@Inject
	public TravelMenuOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void setWordsSupplier(Supplier<Set<String>> wordsSupplier)
	{
		this.wordsSupplier = wordsSupplier;
	}

	/** The widget group that loaded while the travel sub was current. */
	private Supplier<Integer> groupSupplier = () -> -1;

	public void setGroupSupplier(Supplier<Integer> groupSupplier)
	{
		this.groupSupplier = groupSupplier;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Set<String> words = wordsSupplier.get();
		if (words == null || words.isEmpty())
		{
			return null;
		}
		// Scan the group that loaded while the travel sub was current (the
		// menu itself, whatever its id — nothing is hardcoded), plus the
		// classic "Menu" group 187 as a fallback. Which component holds
		// the entries (and whether they're dynamic, static or nested
		// children) shifts across game updates — scan them all; the
		// groups are tiny and only exist while a menu is open.
		int loaded = groupSupplier.get();
		java.util.LinkedHashSet<Integer> groups = new java.util.LinkedHashSet<>();
		if (loaded > 0)
		{
			groups.add(loaded);
		}
		// Confirmed via the load probe: the spirit tree list is MenuNew
		// (group 947). Classic Menu (187) kept for older-style lists.
		groups.add(InterfaceID.MenuNew.INFINITE >>> 16);
		groups.add(InterfaceID.Menu.LJ_LAYER2 >>> 16);
		for (int group : groups)
		{
			for (int component = 0; component < 16; component++)
			{
				Widget container = client.getWidget((group << 16) | component);
				if (container == null || container.isHidden())
				{
					continue;
				}
				highlightMatches(graphics, container.getDynamicChildren(), words);
				highlightMatches(graphics, container.getStaticChildren(), words);
				highlightMatches(graphics, container.getNestedChildren(), words);
			}
		}
		return null;
	}

	private void highlightMatches(Graphics2D graphics, Widget[] children, Set<String> words)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			String text = child.getText();
			if (child.isHidden() || text == null || text.isEmpty())
			{
				continue;
			}
			// "<col=ff9040>3: Battlefield of Khazard</col>" -> the name.
			String clean = cleanEntry(text);
			if (clean.isEmpty() || !entryMatches(clean, words))
			{
				continue;
			}
			Rectangle bounds = child.getBounds();
			if (bounds != null)
			{
				graphics.setColor(FILL);
				graphics.fill(bounds);
				graphics.setColor(HIGHLIGHT);
				graphics.setStroke(new BasicStroke(2));
				graphics.draw(bounds);
			}
		}
	}

	/** Every meaningful word of the entry name appears in the sub's words. */
	/**
	 * Strips the list decoration off a menu entry, leaving the destination.
	 *
	 * <p>Two shapes, both seen in play: the Adventure Log style numbers its
	 * rows ("3: Battlefield of Khazard"), and a chat menu prefixes the
	 * keyboard hint of the option under the cursor ("[2] Pollnivneach").
	 * Either prefix left in place stops the word match dead.
	 */
	public static String cleanEntry(String text)
	{
		return Text.removeTags(text.replace("<br>", " "))
			.replaceFirst("^\\s*\\[\\d+]\\s*", "")
			.replaceFirst("^\\s*[0-9A-Za-z]\\s*:\\s*", "")
			.trim();
	}

	/**
	 * Does this menu entry name where the current step is sending you?
	 *
	 * <p>Public because the CHAT menu asks the same question: a magic
	 * carpet offers "Bedabin camp / Pollnivneach / Cancel" as ordinary
	 * dialogue options rather than as a travel list, and the answer must
	 * not be decided by a second copy of this rule that can drift from
	 * this one.
	 */
	public static boolean destinationMatches(String entry, Set<String> words)
	{
		return entryMatches(entry, words);
	}

	private static boolean entryMatches(String entry, Set<String> words)
	{
		boolean any = false;
		for (String token : entry.toLowerCase(Locale.ROOT).replace('’', '\'')
			.split("[^a-z0-9']+"))
		{
			if (token.isEmpty() || STOPWORDS.contains(token))
			{
				continue;
			}
			if (!words.contains(token))
			{
				return false;
			}
			any = true;
		}
		return any;
	}
}

package com.ironscape.overlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

/**
 * Quest Helper-style click guidance for "Minigame teleport to X" steps.
 *
 * While the CURRENT sub-step is a minigame teleport, this walks the player
 * through the UI one highlighted click at a time:
 *
 *   1. the Chat-channel side tab (whichever layout's widget is visible),
 *   2. the "Grouping" sub-tab inside that panel,
 *   3. the minigame dropdown (and, once open, the right entry in the list),
 *   4. the Teleport button.
 *
 * Each render just inspects which widgets currently exist and highlights
 * the next one — no state machine to get stuck. The overlay disappears by
 * itself when the teleport lands, because the position jump auto-ticks the
 * travel sub and it stops being current.
 */
@Singleton
public class MinigameTeleportOverlay extends Overlay
{
	private static final Color HIGHLIGHT = new Color(0, 255, 128);
	private static final Color FILL = new Color(0, 255, 128, 40);

	/**
	 * The Chat-channel/Grouping side tab in each of the three client
	 * layouts (fixed, resizable classic, resizable modern). Exactly one is
	 * a real visible widget at any time. Stone/icon 7 is the friends-chat
	 * tab in every layout (ComponentID's deprecated names confirm it:
	 * FIXED_VIEWPORT_FRIENDS_CHAT_TAB etc. have these same values).
	 */
	private static final int[] SIDE_TAB_CANDIDATES = {
		InterfaceID.Toplevel.STONE7,
		InterfaceID.ToplevelOsrsStretch.STONE7,
		InterfaceID.ToplevelPreEoc.ICON7,
	};

	/**
	 * The Magic side tab per layout — highlighted alongside the grouping
	 * tab, because the spellbook's Minigame Teleport button is an equally
	 * valid (often faster) route. STONE6 in every layout.
	 */
	private static final int[] MAGIC_TAB_CANDIDATES = {
		InterfaceID.Toplevel.STONE6,
		InterfaceID.ToplevelOsrsStretch.STONE6,
		InterfaceID.ToplevelPreEoc.STONE6,
	};

	/**
	 * Each spellbook's "Minigame Teleport" button (added to the magic book
	 * in a game update) — clicking it opens the same Grouping flow. Only
	 * the active spellbook's widget exists at a time.
	 */
	private static final int[] SPELLBOOK_MINIGAME_TELEPORTS = {
		InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_STANDARD,
		InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ANCIENT,
		InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_ARCEUUS,
		InterfaceID.MagicSpellbook.TELEPORT_MINIGAME_LUNAR,
	};

	/**
	 * The Worn Equipment side tab per layout — the first click toward an
	 * EQUIPPED item's teleport (the Chronicle in the shield slot).
	 */
	private static final int[] EQUIPMENT_TAB_CANDIDATES = {
		InterfaceID.Toplevel.STONE4,
		InterfaceID.ToplevelOsrsStretch.STONE4,
		InterfaceID.ToplevelPreEoc.STONE4,
	};

	/**
	 * Each spellbook's Home Teleport spell — for "Home tele to Lumbridge"
	 * steps: highlight the spell if the book is open, else the Magic tab.
	 */
	private static final int[] SPELLBOOK_HOME_TELEPORTS = {
		InterfaceID.MagicSpellbook.TELEPORT_HOME_STANDARD,
		InterfaceID.MagicSpellbook.TELEPORT_HOME_ZAROS,
		InterfaceID.MagicSpellbook.TELEPORT_HOME_ARCEUUS,
		InterfaceID.MagicSpellbook.TELEPORT_HOME_LUNAR,
	};

	private final Client client;

	/** Set by the plugin: the minigame the current sub-step wants, or null. */
	private Supplier<String> targetSupplier = () -> null;

	/** Set by the plugin: true while the current sub is a home teleport. */
	private Supplier<Boolean> homeTeleportSupplier = () -> false;

	/** Set by the plugin: spellbook teleport component the route wants, or -1. */
	private Supplier<Integer> spellTeleportSupplier = () -> -1;

	/** Worn-slot component of an equipped-item teleport (the Chronicle), or -1. */
	private Supplier<Integer> equippedTeleportSupplier = () -> -1;

	/** Label for the equipped teleport ("Chronicle"); null = generic. */
	private Supplier<String> equippedTeleportLabelSupplier = () -> null;

	public void setEquippedTeleportSupplier(Supplier<Integer> supplier)
	{
		this.equippedTeleportSupplier = supplier;
	}

	public void setEquippedTeleportLabelSupplier(Supplier<String> supplier)
	{
		this.equippedTeleportLabelSupplier = supplier;
	}

	@Inject
	public MinigameTeleportOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void setTargetSupplier(Supplier<String> targetSupplier)
	{
		this.targetSupplier = targetSupplier;
	}

	public void setHomeTeleportSupplier(Supplier<Boolean> homeTeleportSupplier)
	{
		this.homeTeleportSupplier = homeTeleportSupplier;
	}

	public void setSpellTeleportSupplier(Supplier<Integer> spellTeleportSupplier)
	{
		this.spellTeleportSupplier = spellTeleportSupplier;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String minigame = targetSupplier.get();
		if (minigame == null)
		{
			// Route-aware SPELL teleport ("Varrock Teleport" as the first
			// leg): highlight the spell if the book is open, else the
			// Magic side tab — one click at a time, like home teleport.
			Integer spellComponent = spellTeleportSupplier.get();
			if (spellComponent != null && spellComponent != -1)
			{
				Widget spell = client.getWidget(spellComponent);
				if (spell != null && !spell.isHidden())
				{
					highlight(graphics, spell);
				}
				else
				{
					highlightFirstVisible(graphics, MAGIC_TAB_CANDIDATES);
				}
				return null;
			}
			// Equipped-item teleport ("Chronicle tele"): the worn slot when
			// the equipment panel is open, else the Worn Equipment tab.
			Integer wornSlot = equippedTeleportSupplier.get();
			if (wornSlot != null && wornSlot != -1)
			{
				String slotLabel = equippedTeleportLabelSupplier.get();
				String label = slotLabel == null ? "Teleport" : slotLabel;
				Widget slot = client.getWidget(wornSlot);
				if (slot != null && !slot.isHidden())
				{
					highlightLabeled(graphics, slot, label);
				}
				else
				{
					Widget tab = firstVisible(EQUIPMENT_TAB_CANDIDATES);
					if (tab != null)
					{
						highlightLabeled(graphics, tab, label);
					}
				}
				return null;
			}
			if (Boolean.TRUE.equals(homeTeleportSupplier.get()))
			{
				renderHomeTeleport(graphics);
			}
			return null;
		}

		// The center-screen Minigames picker (what the spellbook button
		// opens): highlight the entry with the right name.
		Widget picker = client.getWidget(InterfaceID.Minigames.UNIVERSE);
		if (picker != null && !picker.isHidden())
		{
			Widget content = client.getWidget(InterfaceID.Minigames.CONTENT);
			for (int componentId = InterfaceID.Minigames.MINIGAME_21;
				componentId <= InterfaceID.Minigames.MINIGAME_1; componentId++)
			{
				Widget entry = client.getWidget(componentId);
				if (entry != null && !entry.isHidden() && widgetTextContains(entry, minigame)
					// scrolled-out entries still exist; don't draw outside the frame
					&& (content == null || content.getBounds().intersects(entry.getBounds())))
				{
					highlight(graphics, entry);
					return null;
				}
			}
			return null; // right entry is scrolled out of view; nothing to point at
		}

		// Grouping panel open: guide within it.
		Widget grouping = client.getWidget(InterfaceID.Grouping.UNIVERSE);
		if (grouping != null && !grouping.isHidden())
		{
			renderInsideGrouping(graphics, minigame);
			return null;
		}

		// Spellbook open: its Minigame Teleport button is the shortest path
		// from here — clicking it opens the Grouping flow we then guide.
		// Labeled: the button is generic, the recommendation isn't.
		for (int componentId : SPELLBOOK_MINIGAME_TELEPORTS)
		{
			Widget spell = client.getWidget(componentId);
			if (spell != null && !spell.isHidden())
			{
				highlightLabeled(graphics, spell, minigame);
				return null;
			}
		}

		// Channels side panel open but on another sub-tab (Chat-channel,
		// Your Clan, Guest Clan): point at the Grouping sub-tab.
		Widget channels = client.getWidget(InterfaceID.SideChannels.UNIVERSE);
		if (channels != null && !channels.isHidden())
		{
			highlightLabeled(graphics, client.getWidget(InterfaceID.SideChannels.TAB_3), minigame);
			return null;
		}

		// Neither route's panel is open: light up BOTH ways in — the
		// grouping side tab and the magic side tab both lead to the
		// minigame teleport. The label names the destination minigame.
		Widget sideTab = firstVisible(SIDE_TAB_CANDIDATES);
		if (sideTab != null)
		{
			highlightLabeled(graphics, sideTab, minigame);
		}
		highlightFirstVisible(graphics, MAGIC_TAB_CANDIDATES);
		return null;
	}

	/**
	 * "Home tele to Lumbridge": one highlighted click at a time — the Home
	 * Teleport spell if the spellbook is open, else the Magic side tab.
	 */
	private void renderHomeTeleport(Graphics2D graphics)
	{
		for (int componentId : SPELLBOOK_HOME_TELEPORTS)
		{
			Widget spell = client.getWidget(componentId);
			if (spell != null && !spell.isHidden())
			{
				highlight(graphics, spell);
				return;
			}
		}
		highlightFirstVisible(graphics, MAGIC_TAB_CANDIDATES);
	}

	private void highlightFirstVisible(Graphics2D graphics, int[] componentIds)
	{
		highlight(graphics, firstVisible(componentIds));
	}

	private Widget firstVisible(int[] componentIds)
	{
		for (int componentId : componentIds)
		{
			Widget widget = client.getWidget(componentId);
			if (widget != null && !widget.isHidden())
			{
				return widget;
			}
		}
		return null;
	}

	private void renderInsideGrouping(Graphics2D graphics, String minigame)
	{
		// Dropdown list open: highlight the entry with the right name.
		Widget dropdownList = client.getWidget(InterfaceID.Grouping.DROPDOWN);
		if (dropdownList != null && !dropdownList.isHidden())
		{
			Widget contents = client.getWidget(InterfaceID.Grouping.DROPDOWN_CONTENTS);
			if (contents != null)
			{
				for (Widget entry : contents.getDynamicChildren())
				{
					String text = entry.getText();
					if (text != null && namesMatch(text, minigame))
					{
						highlight(graphics, entry);
						return;
					}
				}
			}
			// Right minigame not on screen yet — outline the list to say
			// "scroll in here".
			highlight(graphics, dropdownList);
			return;
		}

		// Dropdown closed: is the right minigame already selected?
		Widget selected = client.getWidget(InterfaceID.Grouping.CURRENTGAME);
		String selectedName = selected == null || selected.getText() == null
			? "" : selected.getText();
		if (!namesMatch(selectedName, minigame))
		{
			highlight(graphics, client.getWidget(InterfaceID.Grouping.DROPDOWN_TOP));
			return;
		}

		highlight(graphics, client.getWidget(InterfaceID.Grouping.TELEPORT));
	}

	/**
	 * Does this widget (or any direct child) contain the given name?
	 * Picker entries render their name in child text widgets ("Soul Wars"
	 * over "Isle of Souls"), so the entry itself often has no text.
	 */
	private static boolean widgetTextContains(Widget widget, String needle)
	{
		String lowerNeedle = needle.toLowerCase();
		if (textContains(widget.getText(), lowerNeedle))
		{
			return true;
		}
		Widget[][] childArrays = {
			widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren(),
		};
		for (Widget[] children : childArrays)
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child != null && textContains(child.getText(), lowerNeedle))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static boolean textContains(String text, String lowerNeedle)
	{
		return text != null && namesMatch(text, lowerNeedle);
	}

	/**
	 * Guide-slang-tolerant name match: the guide's words must appear in
	 * the widget's words, in order, each as a PREFIX — "fish trawler"
	 * matches "Fishing Trawler<br>Port Khazard" ("<br>" separates words:
	 * removeTags alone would fuse "TrawlerPort").
	 */
	private static boolean namesMatch(String widgetText, String guideName)
	{
		String widget = Text.removeTags(widgetText.replaceAll("(?i)<br\\s*/?>", " "))
			.toLowerCase().replace('’', '\'').trim();
		String guide = guideName.toLowerCase().replace('’', '\'').trim();
		if (widget.contains(guide))
		{
			return true;
		}
		String[] widgetWords = widget.split("\\s+");
		String[] guideWords = guide.split("\\s+");
		if (guideWords.length == 0 || widgetWords.length < guideWords.length)
		{
			return false;
		}
		for (int offset = 0; offset <= widgetWords.length - guideWords.length; offset++)
		{
			boolean all = true;
			for (int i = 0; i < guideWords.length; i++)
			{
				if (guideWords[i].length() < 3
					|| !widgetWords[offset + i].startsWith(guideWords[i]))
				{
					all = false;
					break;
				}
			}
			if (all)
			{
				return true;
			}
		}
		return false;
	}

	private void highlight(Graphics2D graphics, Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}
		Rectangle bounds = widget.getBounds();
		graphics.setColor(FILL);
		graphics.fill(bounds);
		graphics.setColor(HIGHLIGHT);
		graphics.setStroke(new BasicStroke(2));
		graphics.draw(bounds);
	}

	/**
	 * Highlight plus the RECOMMENDATION's name floated beside the box —
	 * a bare green square on the Minigame Teleport button reads as
	 * "minigame, trust me"; the player deserves to know WHICH one before
	 * clicking in (owner report: thought it disagreed with his own plan).
	 */
	private void highlightLabeled(Graphics2D graphics, Widget widget, String label)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}
		highlight(graphics, widget);
		Rectangle bounds = widget.getBounds();
		graphics.setFont(net.runelite.client.ui.FontManager.getRunescapeBoldFont());
		int width = graphics.getFontMetrics().stringWidth(label);
		// Left of the box when it hugs the right edge (side tabs), else above.
		int tx = bounds.x + bounds.width + 6 + width > graphics.getClipBounds().width
			? bounds.x - width - 6 : bounds.x;
		int ty = bounds.y - 4 < 12 ? bounds.y + bounds.height + 14 : bounds.y - 4;
		graphics.setColor(Color.BLACK);
		graphics.drawString(label, tx + 1, ty + 1);
		graphics.setColor(HIGHLIGHT);
		graphics.drawString(label, tx, ty);
	}
}

