/**
 * Everything a StepRow needs, bundled so the constructor stays sane.
 * Built once per panel rebuild.
 */
@Value
class RowContext
{
	GuideVariant variant;
	ProgressManager progress;
	AnnotationManager annotations;
	ItemTracker items;
	PlaceManager places;

	/** Text-detected item goals keyed by sub-step id (never null; may be empty). */
	Map<String, List<GoalDetector.ItemGoal>> itemGoals;

	/** sub-id -> html for counted-action badges ("construction 3/9"); may be null. */
	java.util.function.Function<String, String> actionBadge;

	/** sub-id -> item name whose sprite heads the action badge ("Barcrawl
	 * card" next to "stamp 0/1"); null function or null result = no icon. */
	java.util.function.Function<String, String> badgeIcon;

	/** sub-id -> small skill icon for level/counted badges ("magic 33/42"
	 * gets the Magic star); null function or null result = no icon. */
	java.util.function.Function<String, java.awt.image.BufferedImage> skillIcon;

	/**
	 * sub-id -> the errand chain's stage items in order, each NEEDED / HELD
	 * / SPENT. DISPLAY ONLY: these never become annotation items, because
	 * annotationItemsCarried (the arrival gate) and bankFirstTarget read
	 * those, and changing what gates an arrival is not what showing an
	 * icon should do. Null function or null result = no stage badges.
	 */
	java.util.function.Function<String, java.util.LinkedHashMap<String, String>> errandStages;
	/** Chain stages as an ordered checklist: "index|label" -> DONE | CURRENT | TODO. */
	java.util.function.Function<String, java.util.LinkedHashMap<String, String>> errandChecklist;

	/**
	 * sub-id -> true when NOTHING can ever tick this step automatically: no
	 * detector claims it, it carries no varbit/varp checkpoint, and it has
	 * no errand chain to finish. 139 steps guide-wide are in that state and
	 * most of them are genuinely advice ("bank everything", "use
	 * Authenticator"), but meeting one unwarned reads as a broken plugin
	 * every single time. Saying so is cheaper than being asked.
	 * Null function = don't mark anything.
	 */
	java.util.function.Predicate<String> manualOnly;

	/** Tells the panel to refresh the progress bar after a tick. */
	Runnable onProgressChanged;

	/** Null when capture buttons are disabled/unwired. */
	CaptureHandler captureHandler;

	/** "Capture as safespot" in the ⌖ right-click menu. Null if unwired. */
	CaptureHandler safespotCaptureHandler;

	/** Right-click on ⌖: forget the LOCAL captured target. Null if unwired. */
	Consumer<String> clearTargetHandler;

	/** Routes to an annotation id's target via Shortest Path. Null if unwired. */
	Consumer<String> navigateHandler;

	/** Routes to a named place via Shortest Path (the step gives quest-name
	 * links their context: landmark vs the quest itself). Null if unwired. */
	java.util.function.BiConsumer<String, com.ironscape.guide.GuideStep> placeNavigateHandler;

	/** Hops to a world number ("world 444" links). Null if unwired. */
	Consumer<Integer> worldHopHandler;

	/**
	 * Quest name -> the step whose task IS that quest; null when no step is
	 * tagged with it. Feeds the "go and do this first" button on a step with
	 * a prerequisiteQuest.
	 *
	 * Resolved by NAME rather than by the step numbers in the guide's own
	 * notes: those were written against the original numbering and do not map
	 * onto ours by any constant offset (one note calls our step 281 "278",
	 * another refers to "step 1.1.145a" entirely differently).
	 */
	java.util.function.Function<String, com.ironscape.guide.GuideStep> questStep;

	/**
	 * Scroll the panel to whatever the current step now is, and re-point the
	 * route — what the Resume button does.
	 *
	 * Moving the player's POSITION changes nothing on screen by itself: no
	 * checkbox flips, no card restyles, so a jump looked like a dead click
	 * even though it had worked. Ticking a box is self-evidencing; moving
	 * the position is not, and needs to show its own result.
	 */
	Runnable jumpToCurrentHandler;

	/**
	 * Step id -> the step that is WAITING on it: the inverse of
	 * prerequisiteQuest, for the return trip.
	 *
	 * Derived from the annotation rather than remembered from the click that
	 * brought you here. Session state would be lost on a restart and would
	 * offer nothing to someone who arrived at the prerequisite by simply
	 * playing forwards, whereas the relation is true either way.
	 */
	java.util.function.Function<String, com.ironscape.guide.GuideStep> dependentStep;

	/**
	 * Step id -> an EARLIER unfinished step of that step's own quest, when
	 * there is one: "you are ahead of yourself".
	 *
	 * Finishing a deferred prerequisite advances the frontier to whatever
	 * comes next in guide ORDER, which after a jump is a later leg of the
	 * quest you have not started — the panel pointed at "Continue Lost tribe"
	 * with The Lost Tribe untouched. Computed from quest tags and completion
	 * rather than annotated per step, so it covers every quest the guide
	 * splits across non-adjacent steps, not just the one that exposed it.
	 */
	java.util.function.Function<String, com.ironscape.guide.GuideStep> earlierQuestLeg;

	/**
	 * Step id -> the destination the player CHOSE from one of that step's
	 * notes, or null. Null if unwired.
	 *
	 * A note is very often where the alternative route lives ("ALTERNATIVE:
	 * thieve in Varlamore instead"), and taking it used to mean fighting the
	 * panel for the rest of the step: he was standing in Civitas illa Fortis
	 * and the route kept pulling him back to Pollnivneach, because the step's
	 * own pin is the one the guide prescribes (owner, in play 2026-08-31).
	 */
	java.util.function.Function<String, net.runelite.api.coords.WorldPoint> chosenAlternative;

	/**
	 * Adopt (or, with a null point, drop) a note's destination as this step's
	 * route. Persisted per profile: a choice about how to play a two-hour
	 * grind must not be forgotten by a restart.
	 */
	java.util.function.BiConsumer<String, net.runelite.api.coords.WorldPoint> alternativeHandler;

	/**
	 * Turn the nearest-person outline on or off for a step's captured ⌖.
	 * Null if unwired.
	 */
	java.util.function.BiConsumer<String, Boolean> outlineNpcHandler;
}

package com.ironscape.panel;

import com.ironscape.guide.TextRun;
import java.util.List;
import java.util.function.UnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Converts guide text runs into the small subset of HTML that Swing
 * components can render. All panel text goes through here.
 */
final class RichText
{
	/** Pixel width the HTML body wraps at — forces Swing to compute a sane height. */
	private static final int BODY_WIDTH_PX = 165;

	/** Link prefix for "world 444" hop links; StepRow recognises it on click. */
	static final String WORLD_LINK_PREFIX = "bruh:world:";

	/** "world 444" / "World 330" — always a hoppable world number in this guide. */
	private static final Pattern WORLD_MENTION = Pattern.compile(
		"\\bworld\\s+(\\d{3})\\b", Pattern.CASE_INSENSITIVE);

	private RichText()
	{
	}

	/**
	 * One run of text (a sub-step's sentence or bullet) as HTML. Completed
	 * text renders dimmed so the eye skips it. No width here — StepRow
	 * sizes the component itself.
	 *
	 * @param linkifier optional pass over each escaped fragment that may
	 *                  wrap known place names in links; null = no links
	 */
	static String runsHtml(List<TextRun> runs, boolean completed, UnaryOperator<String> linkifier)
	{
		StringBuilder sb = new StringBuilder("<html><body>");
		if (completed)
		{
			sb.append("<font color='#808080'>");
		}
		appendRuns(sb, runs, completed, linkifier);
		if (completed)
		{
			sb.append("</font>");
		}
		sb.append("</body></html>");
		return sb.toString();
	}

	/** A standalone paragraph (used for chapter footnotes). */
	static String paragraphHtml(List<TextRun> runs)
	{
		StringBuilder sb = new StringBuilder("<html><body style='width:" + BODY_WIDTH_PX + "px'>");
		appendRuns(sb, runs, false, null);
		sb.append("</body></html>");
		return sb.toString();
	}

	private static void appendRuns(StringBuilder sb, List<TextRun> runs, boolean muted,
		UnaryOperator<String> linkifier)
	{
		for (TextRun run : runs)
		{
			String text = escape(run.getText()).replace("\n", "<br>");
			boolean navClaimed = false;

			// Wrap known place names in navigation links — but not inside
			// text that is already a link.
			if (linkifier != null && run.getUrl() == null)
			{
				text = linkifier.apply(text);
			}
			else if (linkifier != null)
			{
				// An author link whose WHOLE text is one known nav name (a
				// place or an item source) becomes OUR link instead —
				// clicking "Glarial's pebble" should route there, not open
				// a wiki tab. Partial matches keep the author's link.
				String linked = linkifier.apply(text);
				int close = linked.indexOf('>');
				if (linked.startsWith("<a href='" + com.ironscape.places.PlaceManager.LINK_PREFIX)
					&& linked.endsWith("</a>") && close > 0
					&& linked.substring(close + 1, linked.length() - 4).equals(text))
				{
					text = linked;
					navClaimed = true;
				}
			}
			// "world 444" becomes a click-to-hop link. After the place
			// linkifier: place names never contain "world <digits>", so
			// the two can't nest.
			if (run.getUrl() == null)
			{
				text = linkifyWorlds(text);
			}

			if (run.isBold())
			{
				text = "<b>" + text + "</b>";
			}
			if (run.isItalic())
			{
				text = "<i>" + text + "</i>";
			}
			if (run.isUnderline())
			{
				text = "<u>" + text + "</u>";
			}
			if (run.isStrikethrough())
			{
				text = "<s>" + text + "</s>";
			}
			// Skip author colors on completed steps — everything stays dim gray.
			if (!muted && run.getColorHex() != null)
			{
				text = "<font color='" + readableOnDark(run.getColorHex()) + "'>" + text + "</font>";
			}
			if (run.getUrl() != null && !navClaimed)
			{
				text = "<a href='" + escape(run.getUrl()) + "'>" + text + "</a>";
			}
			sb.append(text);
		}
	}

	/**
	 * Wraps the given item names (the sub's detected item goals) in OSRS
	 * Wiki links — "make the hangover cure" links straight to the page
	 * that explains HOW. Applied after place linkification, so regions
	 * already inside an anchor are skipped; first occurrence per name.
	 */
	static String linkifyWikiItems(String html, java.util.Collection<String> names)
	{
		if (names == null || names.isEmpty())
		{
			return html;
		}
		// Split into anchor and non-anchor segments; only the latter get links.
		String[] segments = html.split("(?=<a )|(?<=</a>)");
		java.util.Set<String> remaining = new java.util.LinkedHashSet<>(names);
		StringBuilder out = new StringBuilder();
		for (String segment : segments)
		{
			if (!segment.startsWith("<a "))
			{
				for (java.util.Iterator<String> it = remaining.iterator(); it.hasNext(); )
				{
					String name = it.next();
					Matcher m = Pattern.compile("(?i)(?<![\\w>])"
						+ Pattern.quote(name) + "(?![\\w<])").matcher(segment);
					if (m.find())
					{
						segment = segment.substring(0, m.start())
							+ "<a href='" + wikiUrl(name) + "'>"
							+ m.group() + "</a>"
							+ segment.substring(m.end());
						it.remove();
					}
				}
			}
			out.append(segment);
		}
		return out.toString();
	}

	/** The OSRS wiki page for an item name ("glarial's pebble" -> .../Glarial's_pebble). */
	static String wikiUrl(String name)
	{
		return "https://oldschool.runescape.wiki/w/"
			+ (Character.toUpperCase(name.charAt(0)) + name.substring(1)).replace(' ', '_');
	}

	/** Wraps "world NNN" mentions in bruh:world: links (escaped HTML in/out). */
	static String linkifyWorlds(String escapedHtml)
	{
		Matcher matcher = WORLD_MENTION.matcher(escapedHtml);
		StringBuffer sb = new StringBuffer();
		while (matcher.find())
		{
			matcher.appendReplacement(sb, Matcher.quoteReplacement(
				"<a href='" + WORLD_LINK_PREFIX + matcher.group(1) + "'>" + matcher.group() + "</a>"));
		}
		matcher.appendTail(sb);
		return sb.toString();
	}

	/**
	 * The guide was written in a Google Doc on a WHITE page, so some author
	 * colors (black, dark purple) are unreadable on RuneLite's dark panels.
	 * Blend such colors toward white until they have enough contrast.
	 */
	static String readableOnDark(String hex)
	{
		int r = Integer.parseInt(hex.substring(1, 3), 16);
		int g = Integer.parseInt(hex.substring(3, 5), 16);
		int b = Integer.parseInt(hex.substring(5, 7), 16);

		for (int i = 0; i < 3 && luminance(r, g, b) < 110; i++)
		{
			r = (r + 255) / 2;
			g = (g + 255) / 2;
			b = (b + 255) / 2;
		}
		return String.format("#%02x%02x%02x", r, g, b);
	}

	private static double luminance(int r, int g, int b)
	{
		return 0.299 * r + 0.587 * g + 0.114 * b;
	}

	static String escape(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

