	/**
	 * Entry gates for the minigames whose GROUPING TELEPORT is locked
	 * behind account state — a hint must never point at a teleport the
	 * game will refuse (NMZ scored second-best for the Grand Tree while
	 * the picker showed it locked for the owner). Unlisted = usable.
	 */
	private boolean minigameLandingAvailable(String name)
	{
		Player me = client.getLocalPlayer();
		switch (name.toLowerCase(Locale.ROOT))
		{
			case "nightmare zone":
				int bosses = 0;
				for (Quest quest : NMZ_BOSS_QUESTS)
				{
					if (cachedQuestState(quest) == QuestState.FINISHED)
					{
						bosses++;
					}
				}
				return bosses >= 5;
			case "pest control":
			case "soul wars":
				return me != null && me.getCombatLevel() >= 40;
			case "shades of mort'ton":
				return cachedQuestState(Quest.SHADES_OF_MORTTON) == QuestState.FINISHED;
			case "trouble brewing":
				return cachedQuestState(Quest.CABIN_FEVER) == QuestState.FINISHED
					&& client.getRealSkillLevel(Skill.COOKING) >= 40;
			default:
				return true;
		}
	}

	/**
	 * The best first leg toward `target`, minigame landings and CASTABLE
	 * spellbook teleports (magic level, law runes carried, quest unlocks)
	 * competing on EFFECTIVE distance — or null when walking is
	 * comparable: the winner must be under 60% of the player's own
	 * effective distance, and the journey >100 tiles.
	 */
	private FirstLeg firstLegTowards(WorldPoint target, boolean minigameAvailable)
	{
		WorldPoint me = playerPoint();
		if (me == null || target == null)
		{
			return null;
		}
		// Off-surface areas are parked far north on the map — dungeons at
		// y+6400, but the rune essence mine at y≈4830 and the Abyss beside
		// it. A 2D distance between one of those and a surface point is
		// FICTION, and no hint beats a wrong one ("teleport to Lumbridge"
		// while one ladder below it). Testing the BAND rather than a fixed
		// delta is what catches the mine: standing in it, the Gnome
		// Stronghold reads as 1,372 tiles away — under the old 4,000
		// threshold — so the Barbarian Assault landing "won" the first leg
		// while the way out was the exit portal three tiles away.
		if ((me.getY() >= SURFACE_MAX_Y) != (target.getY() >= SURFACE_MAX_Y))
		{
			return null;
		}
		int playerDistance = effectiveDistance(me, target);
		if (playerDistance <= 100)
		{
			return null;
		}
		// ONE metric for the whole decision. Walked tiles when the bundled
		// table can speak about this target, straight lines when it cannot —
		// never a mix, because 400 walked tiles and a 300-tile straight line
		// are different quantities and ranking them together is meaningless.
		boolean walked = travelDistances.reachable(target);
		// Two bars, and a candidate must clear BOTH: 60% of the journey, and
		// an absolute 75 tiles saved. The percentage alone let a teleport win
		// a trip it barely improved — 60% of a 150-tile jog is a 90-tile jog,
		// which is not worth the runes (owner's call, 2026-08-10). The floor
		// binds on short journeys, the percentage on long ones, so a 1,000-
		// tile trip still demands a real shortcut rather than 75 tiles off.
		int bestDistance = Math.min((int) (playerDistance * 0.6),
			playerDistance - MIN_TILES_SAVED);
		// The FREE home teleport competes first (SP suggests it; we never
		// did — the owner stood in Draynor with SP saying "home teleport"
		// and our overlay dark). Free beats paid on ties, so it leads.
		boolean bestHome = false;
		if (!homeTeleportOnCooldown())
		{
			int d = legDistance("Home Teleport", HOME_TELEPORT_LANDING, target, walked);
			if (d < bestDistance)
			{
				bestDistance = d;
				bestHome = true;
			}
		}
		String bestMinigame = null;
		if (minigameAvailable)
		{
			for (Map.Entry<String, WorldPoint> entry : minigameLandings.entrySet())
			{
				if (!minigameLandingAvailable(entry.getKey()))
				{
					continue;
				}
				int d = legDistance(entry.getKey(), entry.getValue(), target, walked);
				if (d < bestDistance)
				{
					bestDistance = d;
					bestMinigame = entry.getKey();
					bestHome = false;
				}
			}
		}
		TeleportSpell bestSpell = null;
		for (TeleportSpell spell : TELEPORT_SPELLS)
		{
			if (!castable(spell))
			{
				continue;
			}
			int d = legDistance(spell.name, spell.destination, target, walked);
			if (d < bestDistance)
			{
				bestDistance = d;
				bestSpell = spell;
				bestMinigame = null;
				bestHome = false;
			}
		}
		// Teleport ITEMS compete last, so on a tie the cheaper options above
		// keep it — a charge off a glory is a real cost, a spell you can
		// already cast is not. They are only ever suggested when already
		// carried, so this never sends anyone shopping.
		com.ironscape.travel.TeleportItems.Entry bestItem = null;
		for (com.ironscape.travel.TeleportItems.Entry entry : teleportItemIndex.available(itemAvailability))
		{
			int d = legDistance(entry.getDisplay(), entry.getDestination(), target, walked);
			if (d < bestDistance)
			{
				bestDistance = d;
				bestItem = entry;
				bestSpell = null;
				bestMinigame = null;
				bestHome = false;
			}
		}
		if (bestMinigame == null && bestSpell == null && !bestHome && bestItem == null)
		{
			return null;
		}
		FirstLeg won = new FirstLeg(bestMinigame, bestSpell, bestHome, bestItem);
		won.legDistance = bestDistance;
		won.mustBeat = Math.min((int) (playerDistance * 0.6), playerDistance - MIN_TILES_SAVED);
		return won;
	}

	/**
	 * Which metric the hint just ranked on, and how far the player is under
	 * it. Both outcomes carry it, including "none": a session log has to be
	 * able to say whether the travel table was consulted at all, and "none"
	 * is the outcome you get while standing next to the target, which is
	 * exactly when you would wonder.
	 */
	private String metricNote(WorldPoint target)
	{
		if (target == null)
		{
			return "";
		}
		WorldPoint me = playerPoint();
		// Bucketed to 50 tiles ON PURPOSE. logHintDecision prints one line per
		// CHANGE and de-duplicates on the whole string, so an exact distance
		// makes every step you take a new log line -- 139 of them in four
		// minutes on the first run, drowning the file mine-session-log reads.
		// 50 keeps the useful reading (which side of the 100-tile floor, and
		// roughly how far) at a handful of lines per journey.
		return (travelDistances.reachable(target) ? " (walked distances" : " (straight lines")
			+ (me == null ? "" : ", player ~" + (effectiveDistance(me, target) / 50 * 50) + " away")
			+ ")";
	}

	/**
	 * Can the player cast this teleport right now? Level, LAW runes in
	 * hand and the quest gate. Elemental runes go unchecked on purpose —
	 * staves make them unanswerable.
	 * Client thread (skill and inventory reads).
	 */
	private boolean castable(TeleportSpell spell)
	{
		return client.getRealSkillLevel(Skill.MAGIC) >= spell.level
			&& itemTracker.carriedCountOf("law runes") >= spell.laws
			&& hasElement("air", spell.air) && hasElement("water", spell.water)
			&& hasElement("earth", spell.earth) && hasElement("fire", spell.fire)
			&& (spell.requiredQuest == null
				|| cachedQuestState(spell.requiredQuest) == QuestState.FINISHED);
	}

	/**
	 * Staves that supply an element without spending a rune. Combination
	 * staves count for BOTH of their elements, which is the whole reason
	 * this table exists rather than a name guess: a mud battlestaff is not
	 * called a water staff and never would be matched by a suffix rule.
	 */
	private static final Map<String, String[]> ELEMENT_STAVES = Map.of(
		"air", new String[]{"staff of air", "air battlestaff", "mystic air staff",
			"smoke battlestaff", "mystic smoke staff", "mist battlestaff",
			"mystic mist staff", "dust battlestaff", "mystic dust staff"},
		"water", new String[]{"staff of water", "water battlestaff", "mystic water staff",
			"mud battlestaff", "mystic mud staff", "steam battlestaff",
			"mystic steam staff", "mist battlestaff", "mystic mist staff", "kodai wand"},
		"earth", new String[]{"staff of earth", "earth battlestaff", "mystic earth staff",
			"mud battlestaff", "mystic mud staff", "lava battlestaff",
			"mystic lava staff", "dust battlestaff", "mystic dust staff"},
		"fire", new String[]{"staff of fire", "fire battlestaff", "mystic fire staff",
			"lava battlestaff", "mystic lava staff", "steam battlestaff",
			"mystic steam staff", "smoke battlestaff", "mystic smoke staff"});

	/**
	 * Can the player pay this spell's cost in one element — either the
	 * runes are in the bag, or a staff supplying it is held or worn?
	 *
	 * The elemental cost used to go unchecked entirely, so a Varrock
	 * teleport was suggested to anyone holding a single law rune, with no
	 * air or fire to their name (owner, in play, 2026-08-10). It was left
	 * out because a staff makes a rune count meaningless, and skipping the
	 * check was the cautious way to avoid hiding a hint from someone
	 * wielding one — the fix is to model the staff, not to stop asking.
	 *
	 * carriedCountOf covers worn equipment as well as inventory, which is
	 * what makes a WIELDED staff count.
	 */
	private boolean hasElement(String element, int needed)
	{
		if (needed <= 0)
		{
			return true;
		}
		for (String staff : ELEMENT_STAVES.get(element))
		{
			if (itemTracker.carriedCountOf(staff) > 0)
			{
				return true;
			}
		}
		return itemTracker.carriedCountOf(element + " runes") >= needed;
	}

	/**
	 * The standard-book teleport a sub NAMES, or null — "Use mind bomb
	 * and camelot tele" -> Camelot Teleport. Matched on the DESTINATION
	 * word, since the guide never writes the full spell name.
	 *
	 * The destination must sit either side of a tele word ("camelot
	 * tele", "Teleport to Varrock"). Merely MENTIONING a town is not a
	 * teleport instruction, and three steps in the guide prove it: "Use
	 * the falador teletab" (a tab, not the spell), "Use house tab and run
	 * back to thurgo ... run back to Falador" (a destination on foot),
	 * and "Home tele to lumby and run north to Varrock east bank" (a
	 * different teleport entirely). The optional "port" carries a word
	 * boundary, which is what makes "teletab" fail to match.
	 *
	 * Castability is deliberately NOT required here, unlike the spell
	 * SUGGESTION path. "Use mind bomb and camelot tele" is the guide
	 * telling you to BOOST into Camelot Teleport, so the player's real
	 * Magic level is under 45 by design — gating on castable() silenced
	 * the one step in the guide that most needs the prompt (owner,
	 * 2026-08-08). A suggestion has to be castable to be worth making; a
	 * prescription is the guide's call, and missing runes are the item
	 * badges' job to report, not the hint's.
	 */
	private TeleportSpell prescribedSpell(String subText)
	{
		String lower = subText.toLowerCase(Locale.ROOT);
		for (TeleportSpell spell : TELEPORT_SPELLS)
		{
			String destination = java.util.regex.Pattern.quote(
				spell.name.toLowerCase(Locale.ROOT).replace(" teleport", ""));
			boolean named = java.util.regex.Pattern
				.compile("\\b" + destination + "\\s+tele(?:port)?\\b"
					+ "|\\btele(?:port)?\\s+to\\s+" + destination + "\\b")
				.matcher(lower).find();
			if (named)
			{
				return spell;
			}
		}
		return null;
	}

	/**
	 * The guide's spelling of a minigame -> the game's.
	 *
	 * HAND-AUTHORED, never fuzzy, for the same reason the quest-name
	 * aliases are: the guide writes "Burthrope", the game "Burthorpe",
	 * and the two differ by a TRANSPOSITION, so neither is a prefix of
	 * the other and the slang-tolerant word matching cannot bridge them.
	 * The owner met it as a Minigames list where every other entry
	 * highlighted and Burthorpe Games Room did not (2026-08-19).
	 *
	 * Normalising HERE, where the goal is stored, fixes every consumer at
	 * once — the picker highlight, GROUPING_MINIGAMES membership, and the
	 * landing lookup all key off this one string, and all three were
	 * failing on the same typo.
	 *
	 * A bare "Burthorpe" means the games room too: it is the only
	 * Grouping teleport that lands there, which is what the guide's
	 * "minigame tele to Burthrope" is asking for.
	 */
	private static final java.util.Map<String, String> MINIGAME_ALIASES = java.util.Map.of(
		"burthrope games' room", "Burthorpe Games Room",
		"burthrope games room", "Burthorpe Games Room",
		"burthrope", "Burthorpe Games Room",
		"burthorpe", "Burthorpe Games Room");

	/** The game's name for a minigame the guide may have spelled its own way. */
	private static String canonicalMinigame(String name)
	{
		if (name == null)
		{
			return null;
		}
		String key = name.toLowerCase(Locale.ROOT).replace('’', '\'').trim();
		return MINIGAME_ALIASES.getOrDefault(key, name);
	}

	/** The minigame-teleport name matching this place name, or null. */
	private String minigameByName(String placeName)
	{
		for (String minigame : minigameBySub.values())
		{
			if (minigame.equalsIgnoreCase(placeName))
			{
				return minigame;
			}
		}
		// Through the alias map as well: a clicked "Burthrope" place link
		// asks for the same teleport as the step text does, and only the
		// game's spelling is in GROUPING_MINIGAMES.
		String canonical = canonicalMinigame(placeName);
		String key = canonical.toLowerCase(Locale.ROOT).replace('’', '\'');
		return GROUPING_MINIGAMES.contains(key) ? canonical : null;
	}

	/**
	 * A "world 444" link in the guide text was clicked. On the login
	 * screen this switches the world directly (like the Default World
	 * plugin). In game, automated hopping (client.hopToWorld) is not
	 * permitted on the Plugin Hub — we open the world switcher and let
	 * the player click the world themselves.
	 */
	private void hopToWorld(int worldNumber)
	{
		clientThread.invoke(() -> {
			net.runelite.http.api.worlds.WorldResult worldResult = worldService.getWorlds();
			net.runelite.http.api.worlds.World world =
				worldResult == null ? null : worldResult.findWorld(worldNumber);
			if (world == null)
			{
				log.warn("World {} not found in the world list", worldNumber);
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					client.addChatMessage(ChatMessageType.CONSOLE, "",
						"IRONSCAPE: world " + worldNumber + " isn't in the world list.", null);
				}
				return;
			}
			if (client.getWorld() == worldNumber)
			{
				return; // already there
			}

			if (client.getGameState() == GameState.LOGIN_SCREEN)
			{
				// The api World is a client-side struct we fill from the
				// downloaded world list entry.
				net.runelite.api.World rsWorld = client.createWorld();
				rsWorld.setActivity(world.getActivity());
				rsWorld.setAddress(world.getAddress());
				rsWorld.setId(world.getId());
				rsWorld.setPlayerCount(world.getPlayers());
				rsWorld.setLocation(world.getLocation());
				rsWorld.setTypes(net.runelite.client.util.WorldUtil.toWorldTypes(world.getTypes()));
				client.changeWorld(rsWorld);
				return;
			}

			client.openWorldHopper();
			client.addChatMessage(ChatMessageType.CONSOLE, "",
				"IRONSCAPE: pick world " + worldNumber + " in the world switcher.", null);
		});
	}

	private Guide guideFor(GuideVariant variant)
	{
		return guides.computeIfAbsent(variant, v -> {
			try
			{
				return guideLoader.load(v);
			}
			catch (IOException e)
			{
				// Bundled resources can't really be missing; if this ever
				// fires something is badly wrong with the jar itself.
				throw new IllegalStateException("Could not load bundled guide " + v, e);
			}
		});
	}

	/**
	 * Sidebar icon, drawn in code (16x16): an orange square with "IO".
	 * TODO replace with real icon art before a Plugin Hub release.
	 */
	private static BufferedImage drawIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(230, 138, 23)); // RuneLite-ish orange
		g.fillRoundRect(0, 0, 16, 16, 5, 5);
		g.setColor(Color.WHITE);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
		g.setStroke(new BasicStroke(1f));
		// Centered by eye on the 16px square.
		g.drawString("IO", 2, 12);
		g.dispose();
		return image;
	}

	/**
	 * Tells Guice how to build our config object. RuneLite backs it with the
	 * user's settings storage, so values persist across sessions. Every
	 * plugin with a config interface has one of these @Provides methods.
	 */
	@Provides
	IronscapeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IronscapeConfig.class);
	}
}

package com.ironscape.annotations;

import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/**
 * How far along an errand chain the player is.
 *
 * Pulled out of the plugin so the ORDER RULE can be tested without a game
 * client, because the rule is not obvious and getting it wrong is silent:
 * a chain that comes back on itself (into Keep Le Faye, up two floors,
 * fight, back down, out) marks the fight done on the way IN unless
 * position is judged in the right place.
 *
 * The rule, in one line: <b>monotonic conditions may look ahead,
 * reversible ones may not.</b>
 *
 * <ul>
 *   <li><b>Monotonic</b> — a quest var, or owning an item. These cannot
 *       come undone, so a later stage being satisfied proves every stage
 *       before it served its purpose ("the key disappears into the lock").
 *       That look-ahead is what rescues a leg the player teleported past.
 *   <li><b>Reversible</b> — where the player is standing. A position only
 *       proves progress at the moment the chain is waiting for it, so it
 *       is judged at the FRONT of the chain and nowhere else. The same
 *       rule already governs {@code requires.equipped}, which is
 *       frontier-only because worn gear comes off.
 * </ul>
 */
public final class ErrandProgress
{
	/** Everything about the world one chain needs to judge itself. */
	public interface World
	{
		int varValue(Integer varbit, Integer varp);

		/** In the inventory or worn — never the bank. */
		int carriedCount(String item);

		/** Carried or banked. */
		int totalCount(String item);

		/** Null when the player's position is not known this tick. */
		WorldPoint here();
	}

	/**
	 * How near an OPTIONAL leg must be before it speaks up.
	 *
	 * An optional leg is a side task that happens to sit near the route --
	 * a diary talk, a field of flax -- so "while you are here anyway" is
	 * literally its condition. Beyond this it is transparent: the chain
	 * runs past it as though it were not there.
	 */
	public static final int OPTIONAL_NUDGE_RADIUS = 40;

	private ErrandProgress()
	{
	}

	private static boolean optional(StepAnnotation.Errand stage)
	{
		return Boolean.TRUE.equals(stage.optional);
	}

	/**
	 * Advance {@code done} as far as the world allows and return the index
	 * of the first unsatisfied stage — {@code chain.size()} when the chain
	 * is complete. {@code done} is the caller's sticky set: a stage seen
	 * satisfied once stays satisfied for the session, because most of these
	 * items are spent on the very next stage.
	 */
	public static int advance(String stepId, List<StepAnnotation.Errand> chain,
		Set<String> done, World world)
	{
		// PASS 1 — monotonic conditions, judged anywhere in the chain.
		for (int i = 0; i < chain.size(); i++)
		{
			StepAnnotation.Errand stage = chain.get(i);
			if (optional(stage) || isPositional(stage)
				|| !monotonicSatisfied(stage, i, chain.size(), world))
			{
				continue;
			}
			if (Boolean.TRUE.equals(stage.given) || stage.bit != null)
			{
				// Hand-ins are INDEPENDENT: giving Da Vinci his ethenea
				// first must not mark Hops and Chancy done behind it. Only
				// the normal "the key served its purpose" cascade implies
				// the earlier stages.
				//
				// A BIT gate is the same shape, and this is why the rule is
				// worth stating rather than flagging per chain: a threshold
				// is ordinal, so reaching it really does imply everything
				// before it, but one bit says nothing whatever about
				// another. The ten Ardougne easy diary tasks are ten
				// unrelated errands packed into one varp, and cascading
				// from Aleck's Emporium in Yanille (bit 11, done) marked
				// the Fishing Trawler, the combat camp and Tindel's sword
				// done behind it — so the chain skipped all three and
				// routed straight to the cloak (owner, in play,
				// 2026-08-11, confirmed against his own diary tab).
				done.add(stageKey(stepId, chain, i));
			}
			else
			{
				for (int k = 0; k <= i; k++)
				{
					// ... and the cascade never reaches an OPTIONAL leg.
					// Carrying bat bones proves you walked past the flax
					// field; it does not prove you picked any. That
					// inference is exactly why the diary legs of the
					// Merlin chain had never once guided anyone.
					if (!optional(chain.get(k)))
					{
						done.add(stageKey(stepId, chain, k));
					}
				}
			}
		}
		// PASS 1b — OPTIONAL legs, each judged alone.
		//
		// They sit outside the ordering entirely: nothing implies them and
		// they imply nothing, so a side task can be done at any point, or
		// never. Positional ones get no "closer to the next stage" escape
		// either -- being on your way somewhere else is not picking flax.
		for (int i = 0; i < chain.size(); i++)
		{
			StepAnnotation.Errand stage = chain.get(i);
			if (!optional(stage))
			{
				continue;
			}
			boolean satisfied = isPositional(stage)
				? atStage(stage, world.here())
				: monotonicSatisfied(stage, i, chain.size(), world);
			if (satisfied)
			{
				done.add(stageKey(stepId, chain, i));
			}
		}
		// PASS 2 — positional conditions, at the front only. Everything
		// before the front is done by definition, so a satisfied front
		// stage marks only itself, and the loop then re-reads the front so
		// several legs can fall in one tick (walking out of a zone can
		// satisfy a leave-stage and the waypoint after it at once).
		for (int front = front(stepId, chain, done, world); front < chain.size();
			front = front(stepId, chain, done, world))
		{
			StepAnnotation.Errand stage = chain.get(front);
			if (!isPositional(stage) || !positionalSatisfied(stage, front, chain, world.here()))
			{
				break;
			}
			done.add(stageKey(stepId, chain, front));
		}
		return front(stepId, chain, done, world);
	}

	/**
	 * The leg to guide: the first unsatisfied one, except that an OPTIONAL
	 * leg is passed over unless the player is already near it.
	 *
	 * That is what makes it optional in both directions. It never blocks --
	 * skipping the diary can never wedge a quest chain, which the seeded
	 * note on the Sherlock leg was already worried about -- and it never
	 * disappears, because nothing behind it can imply it. It simply waits
	 * until you are in the area and then asks.
	 */
	public static int front(String stepId, List<StepAnnotation.Errand> chain,
		Set<String> done, World world)
	{
		for (int i = 0; i < chain.size(); i++)
		{
			StepAnnotation.Errand stage = chain.get(i);
			if (done.contains(stageKey(stepId, chain, i)))
			{
				continue;
			}
			if (optional(stage) && !nearStage(stage, world.here(), OPTIONAL_NUDGE_RADIUS))
			{
				continue;
			}
			return i;
		}
		return chain.size();
	}

	/**
	 * Is the chain done? OPTIONAL legs do not count -- a step whose work is
	 * its chain is finished when the work is, whether or not you took the
	 * diary detour on the way.
	 */
	public static boolean complete(String stepId, List<StepAnnotation.Errand> chain, Set<String> done)
	{
		for (int i = 0; i < chain.size(); i++)
		{
			if (!optional(chain.get(i)) && !done.contains(stageKey(stepId, chain, i)))
			{
				return false;
			}
		}
		return true;
	}

	private static boolean nearStage(StepAnnotation.Errand stage, WorldPoint here, int radius)
	{
		return here != null
			&& here.distanceTo2D(new WorldPoint(stage.x, stage.y, stage.plane)) <= radius;
	}

	/** Standing at the stage itself -- its own radius, no escape hatches. */
	private static boolean atStage(StepAnnotation.Errand stage, WorldPoint here)
	{
		if (stage.zone != null)
		{
			return here != null && Boolean.TRUE.equals(stage.leave) != stage.zone.contains(here);
		}
		if (stage.region != null)
		{
			return here != null
				&& Boolean.TRUE.equals(stage.leave) != (here.getRegionID() == stage.region);
		}
		return nearStage(stage, here, stage.radius != null ? stage.radius : 12);
	}

	/**
	 * Sticky-satisfaction key for one stage.
	 *
	 * Carries the stage's INDEX because a chain may legitimately visit one
	 * place twice — the first floor of Keep Le Faye is a leg on the way up
	 * and another on the way down — and a key built from coordinates alone
	 * would let the first visit tick the second.
	 */
	public static String stageKey(String stepId, List<StepAnnotation.Errand> chain, int index)
	{
		StepAnnotation.Errand stage = chain.get(index);
		String what;
		if (varGated(stage))
		{
			what = "var:" + (stage.varbit != null ? stage.varbit : "p" + stage.varp)
				+ (stage.bit != null ? "#" + stage.bit : ">=" + stage.value);
		}
		else
		{
			what = stage.item != null ? stage.item : "wp:" + stage.x + "," + stage.y;
		}
		return stepId + "|" + index + "|" + what;
	}

	/**
	 * Is this leg about WHERE THE PLAYER IS — a zone, a region, or a plain
	 * waypoint? A var gate wins over everything (quest progress orders
	 * stages that proximity cannot), and a zone or region wins over the
	 * item branches, so a positional stage can still carry an item for its
	 * badge while the position remains the gate.
	 */
	public static boolean isPositional(StepAnnotation.Errand stage)
	{
		if (varGated(stage))
		{
			return false;
		}
		return stage.zone != null || stage.region != null || stage.item == null;
	}


	/**
	 * Does this stage turn on a VAR reading rather than where you are or
	 * what you hold? Either a threshold (value) or a single bit — diaries
	 * pack a whole tier into one varp, so a bit test is the only honest
	 * question there. One helper because three places asked it separately
	 * and a new gate kind has to reach all three.
	 */
	private static boolean varGated(StepAnnotation.Errand stage)
	{
		return (stage.value != null || stage.bit != null)
			&& (stage.varbit != null || stage.varp != null);
	}

	private static boolean monotonicSatisfied(StepAnnotation.Errand stage, int index,
		int chainSize, World world)
	{
		if (varGated(stage))
		{
			int v = world.varValue(stage.varbit, stage.varp);
			// A bit test, never a threshold: see StepAnnotation.Errand.bit.
			return stage.bit != null ? (v & (1 << stage.bit)) != 0 : v >= stage.value;
		}
		if (stage.item == null)
		{
			return false;
		}
		if (Boolean.TRUE.equals(stage.given))
		{
			// HAND-IN stage: done once the item has left your hands.
			return world.carriedCount(stage.item) == 0;
		}
		// Intermediate stages count CARRIED only: quest keys are all
		// literally named "Key", and an unrelated one in the BANK must not
		// skip the crate. The LAST stage is the objective itself and may
		// sit banked — still done.
		return (index == chainSize - 1
			? world.totalCount(stage.item)
			: world.carriedCount(stage.item)) > 0;
	}

	private static boolean positionalSatisfied(StepAnnotation.Errand stage, int index,
		List<StepAnnotation.Errand> chain, WorldPoint here)
	{
		if (here == null)
		{
			return false;
		}
		if (stage.zone != null)
		{
			// Precise "am I in yet?", and the only condition that tells
			// FLOORS apart. `leave` inverts it: the way OUT of a one-way
			// interior is a leg with somewhere to be and something to
			// click, and no coordinate can express it, because every tile
			// outside the door is a few tiles from every tile inside it.
			return Boolean.TRUE.equals(stage.leave) != stage.zone.contains(here);
		}
		if (stage.region != null)
		{
			return Boolean.TRUE.equals(stage.leave) != (here.getRegionID() == stage.region);
		}
		// Item-less WAYPOINT stage (the cave entrance on the way to the
		// warriors): satisfied by getting there — or by being closer to the
		// NEXT stage than to it (a teleport skipped it; it served its
		// purpose either way).
		int radius = stage.radius != null ? stage.radius : 12;
		WorldPoint mine = new WorldPoint(stage.x, stage.y, stage.plane);
		if (here.distanceTo2D(mine) <= radius)
		{
			return true;
		}
		if (index + 1 >= chain.size())
		{
			return false;
		}
		StepAnnotation.Errand next = chain.get(index + 1);
		return here.distanceTo2D(new WorldPoint(next.x, next.y, next.plane))
			< here.distanceTo2D(mine);
	}

	/** One short line describing a stage: its note, else its item, else where it is. */
	public static String checklistLabel(StepAnnotation.Errand stage)
	{
		if (stage.note != null && !stage.note.trim().isEmpty())
		{
			// First SENTENCE of the note: a full stop followed by a space.
			//
			// Written with indexOf rather than a regex on purpose. This was
			// `split("(?<=\.)\s")` and reached the file as `split("(?<=.)s")`
			// — the escapes were eaten generating this method through a
			// script — which means "any character followed by an s", so
			// every label was chopped at its first lowercase s: "Ask
			// Wizard Cromperty…" rendered as "A". It cost three rebuilds
			// spent adjusting a layout that had been correct since the
			// first fix. Nothing to escape here, nothing to eat.
			String first = stage.note.trim();
			int sentence = first.indexOf(". ");
			if (sentence > 0)
			{
				first = first.substring(0, sentence + 1);
			}
			return first.length() > 90 ? first.substring(0, 88) + "..." : first;
		}
		if (stage.item != null)
		{
			return com.ironscape.items.ItemTracker.capitalize(stage.item);
		}
		return "Go to " + stage.x + ", " + stage.y;
	}
}

package com.ironscape.annotations;

import com.google.gson.Gson;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.RuneLite;

/**
 * Loads and saves step annotations. Two layers:
 *
 *  1. BUNDLED — annotations.json shipped inside the plugin (community
 *     contributions, currently empty). Read-only.
 *  2. LOCAL — ~/.runelite/ironscape/annotations.json, written by the
 *     capture button. Overrides bundled per field. This file is
 *     pretty-printed exactly so it can be shared/PR'd upstream.
 *
 * Deliberately NOT stored via ConfigManager: annotations describe the
 * guide, not the player, so they shouldn't switch with RuneLite profiles.
 */
@Slf4j
@Singleton
public class AnnotationManager
{
	private static final int FILE_VERSION = 1;

	private final Gson gson;
	private final File localFile;

	private Map<String, StepAnnotation> bundled = new HashMap<>();
	private Map<String, StepAnnotation> local = new HashMap<>();

	@Inject
	public AnnotationManager(Gson gson)
	{
		this(gson, new File(RuneLite.RUNELITE_DIR, "ironscape/annotations.json"));
	}

	/** Test constructor: point the local file somewhere harmless. */
	AnnotationManager(Gson gson, File localFile)
	{
		// Pretty printing so the local file stays hand-editable and diffable.
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.localFile = localFile;
	}

	public synchronized void load()
	{
		bundled = readBundled();
		local = readLocal();
		log.debug("Annotations loaded: {} bundled, {} local", bundled.size(), local.size());
	}

	/** The step's target location, local file winning over bundled. Null if none. */
	/**
	 * Is this step's ⌖ one the PLAYER captured, rather than one we shipped?
	 *
	 * A capture is the most deliberate thing anyone can say about where a
	 * step happens - he stood on the tile and pressed the button - so it
	 * outranks even an adopted alternative, which only names a town.
	 */
	public synchronized boolean hasOwnTarget(String stepId)
	{
		StepAnnotation l = local.get(stepId);
		return l != null && l.target != null && !Boolean.TRUE.equals(l.target.cleared);
	}

	public synchronized StepAnnotation.Target getTarget(String stepId)
	{
		StepAnnotation l = local.get(stepId);
		if (l != null && l.target != null)
		{
			// A cleared tombstone masks a wrong BUNDLED target (the seeded
			// Ardy farming shop pin was 70 tiles off) without touching the
			// read-only bundle; capturing writes a real target over it.
			return Boolean.TRUE.equals(l.target.cleared) ? null : l.target;
		}
		StepAnnotation b = bundled.get(stepId);
		return b == null ? null : b.target;
	}

	/** Where to train while the step's skill requirement is unmet; null if none. */
	public synchronized StepAnnotation.Target getTrainAt(String stepId)
	{
		StepAnnotation l = local.get(stepId);
		if (l != null && l.trainAt != null)
		{
			return l.trainAt;
		}
		StepAnnotation b = bundled.get(stepId);
		return b == null ? null : b.trainAt;
	}

	/** What the training at getTrainAt consumes; null if none. */
	public synchronized String getTrainWith(String stepId)
	{
		StepAnnotation l = local.get(stepId);
		if (l != null && l.trainWith != null)
		{
			return l.trainWith;
		}
		StepAnnotation b = bundled.get(stepId);
		return b == null ? null : b.trainWith;
	}

	/** The step's auto-completion requirement, local winning over bundled. Null if none. */
	public synchronized StepAnnotation.Requirement getRequirement(String stepId)
	{
		StepAnnotation l = local.get(stepId);
		if (l != null && l.requires != null)
		{
			return l.requires;
		}
		StepAnnotation b = bundled.get(stepId);
		return b == null ? null : b.requires;
	}

	/** The step/sub's mid-quest errand chain, local winning over bundled. Empty if none. */
	public synchronized List<StepAnnotation.Errand> getErrands(String annotationId)
	{
		StepAnnotation l = local.get(annotationId);
		if (l != null && l.errands != null && !l.errands.isEmpty())
		{
			return l.errands;
		}
		StepAnnotation b = bundled.get(annotationId);
		return b == null || b.errands == null ? Collections.emptyList() : b.errands;
	}

	/** Chat-menu options to highlight for a step/sub, local over bundled. Empty if none. */
	public synchronized List<String> getDialog(String annotationId)
	{
		StepAnnotation l = local.get(annotationId);
		if (l != null && l.dialog != null && !l.dialog.isEmpty())
		{
			return l.dialog;
		}
		StepAnnotation b = bundled.get(annotationId);
		return b == null || b.dialog == null ? Collections.emptyList() : b.dialog;
	}

	/** Emote this step asks for ("Goblin bow"), local winning over bundled. Null if none. */
	/** Is this step declared finished-when-you-hold-its-items? See {@link StepAnnotation#completeOnItems}. */
	public synchronized boolean completesOnItems(String annotationId)
	{
		StepAnnotation l = local.get(annotationId);
		if (l != null && l.completeOnItems != null)
		{
			return Boolean.TRUE.equals(l.completeOnItems);
		}
		StepAnnotation b = bundled.get(annotationId);
		return b != null && Boolean.TRUE.equals(b.completeOnItems);
	}

	public synchronized String getEmote(String annotationId)
	{
		StepAnnotation l = local.get(annotationId);
		if (l != null && l.emote != null)
		{
			return l.emote;
		}
		StepAnnotation b = bundled.get(annotationId);
		return b == null ? null : b.emote;
	}

	/** Items needed for a step/sub-step, local file winning over bundled. Empty if none. */
	public synchronized List<StepAnnotation.ItemNeed> getItems(String annotationId)
	{
		StepAnnotation l = local.get(annotationId);
		if (l != null && l.items != null && !l.items.isEmpty())
		{
			return l.items;
		}
		StepAnnotation b = bundled.get(annotationId);
		return b == null || b.items == null ? Collections.emptyList() : b.items;
	}

	/**
	 * The network stop this step really means, or null. See
	 * {@link StepAnnotation#travelVia}.
	 */
	public synchronized String getTravelVia(String annotationId)
	{
		StepAnnotation l = local.get(annotationId);
		if (l != null && l.travelVia != null)
		{
			return l.travelVia;
		}
		StepAnnotation b = bundled.get(annotationId);
		return b == null ? null : b.travelVia;
	}

	/**
	 * Is this item one the quest HANDS the player, under any of the given
	 * annotation keys (step and sub)? See {@link StepAnnotation.ItemNeed#granted}.
	 * Names match case-insensitively, exactly as they were seeded.
	 *
	 * @param annotationIds keys to look under; nulls are skipped
	 */
	public synchronized boolean isGranted(String itemName, String... annotationIds)
	{
		if (itemName == null)
		{
			return false;
		}
		for (String annotationId : annotationIds)
		{
			if (annotationId == null)
			{
				continue;
			}
			for (StepAnnotation.ItemNeed need : getItems(annotationId))
			{
				if (Boolean.TRUE.equals(need.granted) && need.name != null
					&& need.name.equalsIgnoreCase(itemName))
				{
					return true;
				}
			}
		}
		return false;
	}

