	/**
	 * Every step id with completion requirements — ALL entries of a step's
	 * list must be met. A step's `requiresAll` wins over its single
	 * `requires`; the local file wins over bundled per step.
	 */
	public synchronized Map<String, List<StepAnnotation.Requirement>> allRequirements()
	{
		Map<String, List<StepAnnotation.Requirement>> out = new HashMap<>();
		bundled.forEach((id, a) -> {
			List<StepAnnotation.Requirement> requirements = effectiveRequirements(a);
			if (requirements != null)
			{
				out.put(id, requirements);
			}
		});
		local.forEach((id, a) -> {
			List<StepAnnotation.Requirement> requirements = effectiveRequirements(a);
			if (requirements != null)
			{
				out.put(id, requirements);
			}
		});
		return out;
	}

	private static List<StepAnnotation.Requirement> effectiveRequirements(StepAnnotation annotation)
	{
		if (annotation.requiresAll != null && !annotation.requiresAll.isEmpty())
		{
			return annotation.requiresAll;
		}
		return annotation.requires == null ? null : Collections.singletonList(annotation.requires);
	}

	/**
	 * A guide refresh gave some edited steps new ids (see GuideManifest):
	 * re-key the LOCAL annotations so captured targets survive the edit.
	 * Bundled annotations are read-only and stay put — an orphaned
	 * bundled key is harmless and gets fixed at the next bundle
	 * regeneration. Returns how many annotations moved.
	 */
	public synchronized int remapIds(Map<String, String> remap)
	{
		if (remap.isEmpty() || local.isEmpty())
		{
			return 0;
		}
		Map<String, StepAnnotation> remapped = new HashMap<>();
		int moved = 0;
		for (Map.Entry<String, StepAnnotation> entry : local.entrySet())
		{
			String newKey = com.ironscape.guide.GuideManifest.remapId(entry.getKey(), remap);
			if (newKey == null)
			{
				// The clause this annotation pointed at was edited away.
				// Unlike a progress tick, a captured target is real work —
				// keep it under the old key rather than deleting it.
				newKey = entry.getKey();
			}
			if (!newKey.equals(entry.getKey()))
			{
				moved++;
			}
			// merge() would need field-level rules; last-in wins is fine
			// because a collision means the target key already had data.
			remapped.putIfAbsent(newKey, entry.getValue());
		}
		if (moved > 0)
		{
			local = remapped;
			saveLocal();
		}
		return moved;
	}

	/** Called by the capture button: remember where this step happens. */
	public synchronized void setTarget(String stepId, WorldPoint point)
	{
		setTarget(stepId, point, false);
	}

	/** Capture variant: safespot targets get the floating "Safespot" label. */
	public synchronized void setTarget(String stepId, WorldPoint point, boolean safespot)
	{
		StepAnnotation annotation = local.computeIfAbsent(stepId, id -> new StepAnnotation());
		StepAnnotation.Target target = new StepAnnotation.Target();
		target.x = point.getX();
		target.y = point.getY();
		target.plane = point.getPlane();
		target.safespot = safespot ? Boolean.TRUE : null;
		// A CAPTURE IS A SPOT, NOT A PERSON. An unflagged ⌖ nominates the
		// nearest NPC within 4 tiles and hangs the step's item over them,
		// which is a fallback built for SEEDED pins that name nobody -- aimed
		// at a tile the player is standing on it just crowns whoever wandered
		// past (owner, in play 2026-08-31: a citizen outlined in the middle of
		// a Varlamore street). Someone capturing a shopkeeper can turn it back
		// on from the ⌖ menu.
		target.npc = Boolean.FALSE;
		annotation.target = target;
		saveLocal();
	}

	/**
	 * Turn the nearest-person outline on or off for a captured ⌖.
	 * No-op on a bundled pin: those are reviewed data, not the player's.
	 */
	public synchronized void setTargetOutlinesNpc(String stepId, boolean outline)
	{
		StepAnnotation l = local.get(stepId);
		if (l == null || l.target == null)
		{
			return;
		}
		l.target.npc = outline ? Boolean.TRUE : Boolean.FALSE;
		saveLocal();
	}

	/** Does this step's ⌖ currently outline the nearest person? */
	public synchronized boolean targetOutlinesNpc(String stepId)
	{
		StepAnnotation.Target target = getTarget(stepId);
		return target != null && !Boolean.FALSE.equals(target.npc);
	}

	/** Is the EFFECTIVE target (local over bundled) flagged as a safespot? */
	public synchronized boolean isSafespotTarget(String stepId)
	{
		StepAnnotation.Target target = getTarget(stepId);
		return target != null && Boolean.TRUE.equals(target.safespot);
	}

	/** What a right-click "remove captured location" actually did. */
	public enum ClearResult
	{
		/** Local capture deleted; a bundled pin (if any) shows again. */
		REMOVED_LOCAL,
		/** No local capture — the BUNDLED pin was masked with a tombstone. */
		MASKED_BUNDLED,
		/** Nothing visible to remove. */
		NOTHING
	}

	/**
	 * Right-click on the capture button. Two-stage: the first remove
	 * forgets the LOCAL capture (an accidental ⌖ click writes a wrong
	 * target), falling back to any bundled pin; removing again — or
	 * removing when only a bundled pin shows — masks the bundled pin with
	 * a `cleared` tombstone, because a wrong SEEDED pin (the Ardy farming
	 * shop was 70 tiles off) must be removable in-game too. Capturing a
	 * new location replaces the tombstone.
	 */
	public synchronized ClearResult clearTarget(String stepId)
	{
		StepAnnotation l = local.get(stepId);
		StepAnnotation b = bundled.get(stepId);
		boolean hasBundled = b != null && b.target != null;
		if (l != null && l.target != null)
		{
			if (Boolean.TRUE.equals(l.target.cleared))
			{
				return ClearResult.NOTHING; // already tombstoned
			}
			l.target = null;
			if (!hasBundled)
			{
				saveLocal();
				return ClearResult.REMOVED_LOCAL;
			}
			// fall through: local capture gone, mask the bundled pin too —
			// the player is standing there saying "this spot is wrong".
		}
		if (!hasBundled)
		{
			return ClearResult.NOTHING;
		}
		StepAnnotation annotation = local.computeIfAbsent(stepId, id -> new StepAnnotation());
		StepAnnotation.Target tombstone = new StepAnnotation.Target();
		tombstone.cleared = true;
		annotation.target = tombstone;
		saveLocal();
		return ClearResult.MASKED_BUNDLED;
	}

	/**
	 * One bundled file per guide corpus. Step ids are content hashes, so
	 * the key spaces can't collide and a flat merge is safe.
	 */
	private static final String[] BUNDLED_FILES = {"annotations_oziris.json"};

	/** Package-private so tests can inject a bundled corpus. */
	Map<String, StepAnnotation> readBundled()
	{
		Map<String, StepAnnotation> merged = new HashMap<>();
		for (String file : BUNDLED_FILES)
		{
			try (InputStream in = com.ironscape.DataFiles.open(AnnotationManager.class, file))
			{
				if (in == null)
				{
					continue; // a variant without bundled annotations is fine
				}
				merged.putAll(parse(new InputStreamReader(in, StandardCharsets.UTF_8)));
			}
			catch (IOException e)
			{
				log.warn("Could not read bundled annotations from {}", file, e);
			}
		}
		return merged;
	}

	private Map<String, StepAnnotation> readLocal()
	{
		if (!localFile.exists())
		{
			return new HashMap<>();
		}
		try (Reader reader = new FileReader(localFile))
		{
			return parse(reader);
		}
		catch (IOException | RuntimeException e)
		{
			// A corrupt file must not take the plugin down — but don't
			// silently overwrite the player's annotation work either.
			log.warn("Could not read local annotations from {}", localFile, e);
			return new HashMap<>();
		}
	}

	private Map<String, StepAnnotation> parse(Reader reader)
	{
		AnnotationFile file = gson.fromJson(reader, AnnotationFile.class);
		Map<String, StepAnnotation> annotations =
			file == null || file.annotations == null ? new HashMap<>() : file.annotations;
		for (StepAnnotation annotation : annotations.values())
		{
			annotation.items = splitCompoundRunes(annotation.items);
		}
		return annotations;
	}

	/**
	 * The guide writes "all of your mind and air runes" as ONE item, but
	 * it's two — each rune type needs its own have/need check or the name
	 * never matches anything you own. Only single-word types sharing a
	 * trailing "runes" split; prose like "lost tribe brooch and book"
	 * stays one entry.
	 */
	private static final Pattern COMPOUND_RUNES = Pattern.compile(
		"^(?:all (?:of )?(?:your )?)?(\\w+(?:, ?\\w+)*,? and \\w+) runes?$");

	static List<StepAnnotation.ItemNeed> splitCompoundRunes(List<StepAnnotation.ItemNeed> items)
	{
		if (items == null)
		{
			return null;
		}
		List<StepAnnotation.ItemNeed> out = new ArrayList<>(items.size());
		for (StepAnnotation.ItemNeed item : items)
		{
			Matcher m = item.name == null ? null
				: COMPOUND_RUNES.matcher(item.name.toLowerCase(Locale.ROOT).trim());
			if (m == null || !m.matches())
			{
				out.add(item);
				continue;
			}
			for (String type : m.group(1).split(",? and |, ?"))
			{
				StepAnnotation.ItemNeed rune = new StepAnnotation.ItemNeed();
				rune.name = type + " runes";
				rune.quantity = item.quantity;
				out.add(rune);
			}
		}
		return out;
	}

	private void saveLocal()
	{
		File dir = localFile.getParentFile();
		if (dir != null && !dir.exists() && !dir.mkdirs())
		{
			log.warn("Could not create annotation directory {}", dir);
			return;
		}
		AnnotationFile file = new AnnotationFile();
		file.version = FILE_VERSION;
		file.annotations = local;
		try (Writer writer = new FileWriter(localFile))
		{
			gson.toJson(file, writer);
		}
		catch (IOException e)
		{
			log.warn("Could not save annotations to {}", localFile, e);
		}
	}

	/** On-disk shape: {"version": 1, "annotations": {"<stepId>": {...}}} */
	private static class AnnotationFile
	{
		int version;
		Map<String, StepAnnotation> annotations;
	}
}

package com.ironscape;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/**
 * Plugin settings. RuneLite generates the implementation of this interface
 * at runtime and renders a settings UI from it automatically — we only
 * declare what the options are.
 *
 * "ironscape" is the config group key: every value is stored under it in
 * the user's RuneLite profile. Progress persistence (step 3 of the build
 * plan) will use this same mechanism via ConfigManager.
 */
@ConfigGroup("ironscape")
public interface IronscapeConfig extends Config
{
	@ConfigItem(
		keyName = "showCompletedSteps",
		name = "Show completed steps",
		description = "Keep completed steps visible in the panel instead of hiding them"
	)
	default boolean showCompletedSteps()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showCaptureButtons",
		name = "Show capture buttons",
		description = "Show the per-step button that saves your current location as that step's target (for building navigation annotations)"
	)
	default boolean showCaptureButtons()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoCompleteSteps",
		name = "Auto-complete steps",
		description = "Automatically tick off steps whose annotated requirement (e.g. a skill level) you have met"
	)
	default boolean autoCompleteSteps()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showStepOverlay",
		name = "Show step overlay",
		description = "On-screen box with your current step's remaining actions and live item/level counts (alt-drag to move)"
	)
	default boolean showStepOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHandoffBanner",
		name = "Show Quest Helper handoff banners",
		description = "Draw an on-screen banner (and send a notification) when guidance changes hands: when our route stands down for a quest, and when a guide step finishes part way through one and you should stop following Quest Helper"
	)
	default boolean showHandoffBanner()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showQuestStartMarker",
		name = "Quest start marker",
		description = "Float the blue quest icon over a quest's start point while you head there; disappears once the quest begins (and Quest Helper takes over)"
	)
	default boolean showQuestStartMarker()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showGroundItemMarkers",
		name = "Mark ground items",
		description = "Highlight the tiles of ground items the current step wants picked up (item spawns, dropped quest items)"
	)
	default boolean showGroundItemMarkers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTargetMarker",
		name = "Mark target tile",
		description = "Highlight the exact tile of the current step's captured ⌖ location in the world (dig spots, item spawns)"
	)
	default boolean showTargetMarker()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTeleportHints",
		name = "Highlight teleport UI",
		description = "When the current step is a minigame teleport, highlight the tab, dropdown entry, and Teleport button to click, Quest Helper-style"
	)
	default boolean showTeleportHints()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoNavigate",
		name = "Auto-navigate to next step",
		description = "After a step is ticked off, point Shortest Path at the next open step's target (a captured ⌖ location, or a recognised NPC/quest/place name in its text)"
	)
	default boolean autoNavigate()
	{
		return true;
	}

	/**
	 * Auto-navigation only runs while the guide panel is open.
	 *
	 * <p>The Quest Helper stand-down only knows about quests THIS GUIDE is
	 * on. Go and do a quest of your own while the guide sits on a grind step
	 * and nothing stands down, so the route is re-posted over Quest Helper
	 * every few seconds (owner, in play). Having the panel open is the
	 * honest signal that you are following the guide right now.
	 */
	@ConfigItem(
		keyName = "navigateOnlyWhenPanelOpen",
		name = "Only navigate while the panel is open",
		description = "Stop drawing routes while the guide panel is closed, so following something else (like Quest Helper) is not interrupted. A route already drawn is left alone; death routing still always works"
	)
	default boolean navigateOnlyWhenPanelOpen()
	{
		return true;
	}

	/**
	 * GREEN on purpose. Quest Helper outlines in cyan, and so did every one
	 * of these overlays, so on a quest step there was no way to tell "the
	 * guide needs this" from "Quest Helper says click this now" — the two
	 * plugins were drawing the same colour over each other (owner, in
	 * play). Green for us, cyan for QH.
	 */
	@ConfigItem(
		keyName = "hintColour",
		name = "Highlight colour",
		description = "Colour of the plugin's item, NPC and object outlines. Green by default so they read apart from Quest Helper's cyan"
	)
	default java.awt.Color hintColour()
	{
		return new java.awt.Color(0, 255, 128);
	}

	@ConfigItem(
		keyName = "showInventoryHints",
		name = "Highlight step items in inventory",
		description = "Outline the carried items the current step is about (its tools, ingredients and tabs) in the inventory"
	)
	default boolean showInventoryHints()
	{
		return true;
	}

}

package com.ironscape.places;

import com.google.gson.Gson;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.RuneLite;

/**
 * The gazetteer: place/NPC names mapped to world coordinates. Any name in
 * here becomes a clickable link EVERYWHERE it appears in the guide text —
 * clicking routes there via Shortest Path. One capture lights up every
 * mention at once.
 *
 * Same two-layer scheme as annotations: a bundled community file inside
 * the jar, overridden per name by ~/.runelite/ironscape/places.json.
 */
@Slf4j
@Singleton
public class PlaceManager
{
	/** Link prefix used in generated HTML; StepRow recognises it on click. */
	public static final String LINK_PREFIX = "bruh:place:";

	private static final int FILE_VERSION = 1;

	private final Gson gson;
	private final File localFile;

	private Map<String, Place> bundled = new HashMap<>();
	private Map<String, Place> local = new HashMap<>();

	/** Case-insensitive alternation over all known names, longest first. Null when empty. */
	private Pattern namePattern;

	@Inject
	public PlaceManager(Gson gson)
	{
		this(gson, new File(RuneLite.RUNELITE_DIR, "ironscape/places.json"));
	}

	/** Explicit local file — tests and audit dumps point this at a scratch path. */
	public PlaceManager(Gson gson, File localFile)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.localFile = localFile;
	}

	public synchronized void load()
	{
		bundled = read(() -> {
			InputStream in = com.ironscape.DataFiles.open(PlaceManager.class, "places.json");
			return in == null ? null : new InputStreamReader(in, StandardCharsets.UTF_8);
		});
		// Item SOURCES ("glarial's pebble" -> Golrie's cell) share the place
		// namespace: same links, same routing, plus a how-to note chatted on
		// click. Real places win a name clash.
		read(() -> {
			InputStream in = com.ironscape.DataFiles.open(PlaceManager.class, "item_sources.json");
			return in == null ? null : new InputStreamReader(in, StandardCharsets.UTF_8);
		}).forEach(bundled::putIfAbsent);
		local = read(() -> localFile.exists() ? new FileReader(localFile) : null);
		rebuildPattern();
		loadQuestGivers();
		loadShopKeepers();
		log.debug("Places loaded: {} bundled, {} local, {} quest givers, {} shop keepers",
			bundled.size(), local.size(), questGivers.size(), shopKeepers.size());
	}

	/** The NPC who sells this item, by name, or null. */
	public synchronized String sourceVendor(String name)
	{
		Place place = local.get(key(name));
		if (place == null)
		{
			place = bundled.get(key(name));
		}
		return place == null ? null : place.vendor;
	}

	/** The scene object vending this item (lowercase), or null. */
	public synchronized String sourceObject(String name)
	{
		Place place = local.get(key(name));
		if (place == null)
		{
			place = bundled.get(key(name));
		}
		return place == null ? null : place.object;
	}

	/** False when this source's vendor is an OBJECT — no NPC nomination. */
	public synchronized boolean sourceNominatesNpc(String name)
	{
		Place place = local.get(key(name));
		if (place == null)
		{
			place = bundled.get(key(name));
		}
		return place == null || !Boolean.FALSE.equals(place.npc);
	}

	/** The item source's how-to note, or null for ordinary places. */
	public synchronized String note(String name)
	{
		Place place = local.get(key(name));
		if (place == null)
		{
			place = bundled.get(key(name));
		}
		return place == null ? null : place.note;
	}

	/** Quest name (lowercase) -> the NPC who starts it (wiki-seeded, bundled). */
	private Map<String, String> questGivers = new HashMap<>();

	/** The NPC who starts this quest, or null when unknown. */
	public synchronized String questGiver(String questName)
	{
		return questGivers.get(questName.toLowerCase(Locale.ROOT));
	}

	private void loadQuestGivers()
	{
		try (InputStream in = com.ironscape.DataFiles.open(PlaceManager.class, "quest_givers.json"))
		{
			if (in == null)
			{
				return;
			}
			GiversFile file = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), GiversFile.class);
			if (file != null && file.givers != null)
			{
				questGivers = file.givers;
			}
		}
		catch (Exception e)
		{
			log.warn("Could not read bundled quest givers", e);
		}
	}

	private static class GiversFile
	{
		int version;
		Map<String, String> givers;
	}

	/** Step id -> the shopkeeper NPC of that buy-step's shop (wiki-seeded). */
	private Map<String, String> shopKeepers = new HashMap<>();

	/**
	 * The NPC who runs the shop this buy step targets, or null when
	 * unknown. Named beats nearest: the pin's closest NPC was crowning
	 * the Master Farmer with the compost icon while Richard ran the shop
	 * four tiles away (owner report 2026-08-05).
	 */
	public synchronized String shopKeeper(String stepId)
	{
		return shopKeepers.get(stepId);
	}

	private void loadShopKeepers()
	{
		try (InputStream in = com.ironscape.DataFiles.open(PlaceManager.class, "shop_npcs.json"))
		{
			if (in == null)
			{
				return;
			}
			KeepersFile file = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), KeepersFile.class);
			if (file != null && file.keepers != null)
			{
				shopKeepers = file.keepers;
			}
		}
		catch (Exception e)
		{
			log.warn("Could not read bundled shop keepers", e);
		}
	}

	private static class KeepersFile
	{
		int version;
		Map<String, String> keepers;
	}

	public synchronized WorldPoint get(String name)
	{
		Place place = local.get(key(name));
		if (place == null)
		{
			place = bundled.get(key(name));
		}
		return place == null ? null : new WorldPoint(place.x, place.y, place.plane);
	}

	/**
	 * Is this name a place you TRAVEL to, as opposed to a quest?
	 *
	 * Quest start points live in the same namespace so a quest name can be
	 * clicked for a route, but they are not destinations in their own
	 * right: the guide has bare steps reading "Cabin fever" and "One small
	 * favour", and treating those as "be here" would let walking past the
	 * giver tick off a whole quest. The type field already records the
	 * difference, so this is a data question rather than a guess.
	 */
	public synchronized boolean isTravelDestination(String name)
	{
		Place place = local.get(key(name));
		if (place == null)
		{
			place = bundled.get(key(name));
		}
		return place != null && !"quest".equals(place.type) && !"transport".equals(place.type);
	}

	/**
	 * Like get(), but forgiving about directional prefixes — the guide's
	 * authored location tags say "West of Lumbridge" or "South-west of
	 * Castle Wars"; the base place is close enough for navigation.
	 */
	public synchronized WorldPoint getLoose(String name)
	{
		WorldPoint exact = get(name);
		if (exact != null)
		{
			return exact;
		}
		String stripped = name.replaceFirst(
			"(?i)^(?:north|south|east|west)(?:[ -](?:east|west))?\\s+of\\s+", "");
		return stripped.equals(name) ? null : get(stripped);
	}

	/** Save a place under a name and start linkifying it. */
	public synchronized void add(String name, WorldPoint point)
	{
		Place place = new Place();
		place.display = name.trim();
		place.x = point.getX();
		place.y = point.getY();
		place.plane = point.getPlane();
		local.put(key(name), place);
		save();
		rebuildPattern();
	}

	/**
	 * The location of the first known place name mentioned in the text,
	 * or null. Used to derive a navigation target for steps that were
	 * never ⌖-captured ("Talk to Reldo" -> Reldo's spot).
	 *
	 * QUEST names only count when the text says to start/do that quest —
	 * an incidental mention ("your Shield of Arrav partner") must not
	 * route you to the quest start. Clicking a quest link by hand still
	 * always navigates; this filter is for AUTOMATIC targeting only.
	 */
	public synchronized WorldPoint firstPlaceIn(String text)
	{
		return firstPlaceIn(text, false);
	}

	/**
	 * firstPlaceIn for the SHOPKEEPER anchor: additionally skips
	 * object-vendor sources (npc:false — a chest, a dig spot), so their
	 * doorway bystanders never get nominated (the Cook wore the milk
	 * icon because "buckets of milk" in the step text matched the
	 * trapdoor source).
	 */
	public synchronized WorldPoint firstNominatingPlaceIn(String text)
	{
		return firstPlaceIn(text, true);
	}

	private synchronized WorldPoint firstPlaceIn(String text, boolean forNpcNomination)
	{
		if (namePattern == null)
		{
			return null;
		}
		String lower = text.toLowerCase(Locale.ROOT).replace('’', '\'');
		Matcher matcher = namePattern.matcher(text);
		while (matcher.find())
		{
			String key = key(matcher.group());
			Place place = local.containsKey(key) ? local.get(key) : bundled.get(key);
			if (place == null)
			{
				continue;
			}
			// Transport networks ("spirit tree") are CLICK affordances that
			// route to the nearest one — never automatic targets: journeys
			// START next to one, so auto-targeting (and arrival detection!)
			// would misfire on the spot the player is leaving from.
			if ("transport".equals(place.type))
			{
				continue;
			}
			if (forNpcNomination && Boolean.FALSE.equals(place.npc))
			{
				continue;
			}
			if ("quest".equals(place.type)
				&& !lower.contains("start " + key)
				&& !lower.contains("begin " + key)
				&& !lower.contains("do " + key)
				&& !lower.contains("complete " + key)
				&& !lower.contains("finish " + key))
			{
				continue;
			}
			return new WorldPoint(place.x, place.y, place.plane);
		}
		return null;
	}

	/**
	 * The LAST recognised place in the text — the destination of a travel
	 * sub: "Home tele to Lumbridge and run north to Varrock east bank"
	 * ends at Varrock east bank, not Lumbridge. Same quest-name filtering
	 * as firstPlaceIn.
	 */
	public synchronized WorldPoint lastPlaceIn(String text)
	{
		Place place = lastPlaceMatchIn(text);
		return place == null ? null : new WorldPoint(place.x, place.y, place.plane);
	}

	/**
	 * The DISPLAY name of the place {@link #lastPlaceIn} answers with, so a
	 * control can SAY where it is about to send you instead of making the
	 * reader infer it from the sentence.
	 *
	 * <p>Shares its body with lastPlaceIn rather than repeating the matching
	 * rules, which are subtle enough (transport networks excluded, quest
	 * places only after a doing-verb) that two copies would drift.
	 */
	public synchronized String lastPlaceNameIn(String text)
	{
		Place place = lastPlaceMatchIn(text);
		return place == null ? null : place.display;
	}

	private Place lastPlaceMatchIn(String text)
	{
		if (namePattern == null)
		{
			return null;
		}
		String lower = text.toLowerCase(Locale.ROOT).replace('\u2019', '\'');
		Matcher matcher = namePattern.matcher(text);
		Place last = null;
		while (matcher.find())
		{
			String key = key(matcher.group());
			Place place = local.containsKey(key) ? local.get(key) : bundled.get(key);
			if (place == null)
			{
				continue;
			}
			// Same transport-network exclusion as firstPlaceIn.
			if ("transport".equals(place.type))
			{
				continue;
			}
			if ("quest".equals(place.type)
				&& !lower.contains("start " + key)
				&& !lower.contains("begin " + key)
				&& !lower.contains("do " + key)
				&& !lower.contains("complete " + key)
				&& !lower.contains("finish " + key))
			{
				continue;
			}
			last = place;
		}
		return last;
	}

	/**
	 * Wraps every known place name in the given ESCAPED html fragment with
	 * a bruh:place: link. Case-insensitive, longest name wins.
	 */
	public synchronized String linkify(String escapedHtml)
	{
		if (namePattern == null)
		{
			return escapedHtml;
		}
		Matcher matcher = namePattern.matcher(escapedHtml);
		StringBuffer sb = new StringBuffer();
		while (matcher.find())
		{
			// normalized key in the href, original spelling as the label
			String href = LINK_PREFIX + encode(key(matcher.group()));
			matcher.appendReplacement(sb,
				Matcher.quoteReplacement("<a href='" + href + "'>" + matcher.group() + "</a>"));
		}
		matcher.appendTail(sb);
		return sb.toString();
	}

	private void rebuildPattern()
	{
		List<String> names = new ArrayList<>();
		bundled.values().forEach(p -> names.add(p.display));
		local.values().forEach(p -> names.add(p.display));
		if (names.isEmpty())
		{
			namePattern = null;
			return;
		}
		// Longest first so "Romeo & Juliet" beats "Romeo".
		names.sort((a, b) -> b.length() - a.length());
		StringBuilder alternation = new StringBuilder();
		for (String name : names)
		{
			if (alternation.length() > 0)
			{
				alternation.append('|');
			}
			alternation.append(tolerantPattern(name));
		}
		namePattern = Pattern.compile("\\b(?:" + alternation + ")\\b",
			Pattern.CASE_INSENSITIVE);
	}

	/**
	 * A regex for one name that tolerates the punctuation drift between
	 * the wiki, the guide's Google-Docs text, and HTML escaping:
	 * both apostrophes (' and ’), and & as either "&" or "&amp;".
	 */
	private static String tolerantPattern(String name)
	{
		StringBuilder sb = new StringBuilder();
		for (char c : name.toCharArray())
		{
			if (Character.isLetterOrDigit(c) || c == ' ')
			{
				sb.append(c);
			}
			else if (c == '\'' || c == '’')
			{
				sb.append("['’]");
			}
			else if (c == '&')
			{
				sb.append("(?:&amp;|&)");
			}
			else
			{
				sb.append(Pattern.quote(String.valueOf(c)));
			}
		}
		return sb.toString();
	}

	/**
	 * [start, end) span of every place name occurring in the text — lets
	 * the NPC matcher ignore an NPC name that's really part of a place
	 * ("Barbarian" inside "Barbarian Village").
	 */
	public synchronized List<int[]> placeSpans(String text)
	{
		List<int[]> spans = new ArrayList<>();
		if (namePattern == null)
		{
			return spans;
		}
		Matcher matcher = namePattern.matcher(text);
		while (matcher.find())
		{
			spans.add(new int[]{matcher.start(), matcher.end()});
		}
		return spans;
	}

	/** Normalized lookup key: lowercase, straight apostrophes, raw ampersand. */
	private static String key(String name)
	{
		return name.toLowerCase(Locale.ROOT).trim()
			.replace('’', '\'')
			.replace("&amp;", "&");
	}

	/**
	 * Percent-encode a place key so it can ride inside a Swing HTML href,
	 * which StepRow decodes when the link is clicked. Purely internal: this
	 * string never leaves the client and no request is ever made with it.
	 *
	 * Hand-rolled rather than java.net.URLEncoder because the plugin hub's
	 * automated review reasonably treats a java.net import as evidence of
	 * networking, and this plugin does none — it was costing us the fast
	 * lane for a string utility we can write in ten lines.
	 *
	 * Encodes every byte outside [A-Za-z0-9], so the output is always plain
	 * ASCII and safe in an attribute.
	 */
	public static String encode(String name)
	{
		StringBuilder out = new StringBuilder();
		for (byte raw : name.getBytes(StandardCharsets.UTF_8))
		{
			int b = raw & 0xFF;
			boolean unreserved = (b >= 'a' && b <= 'z')
				|| (b >= 'A' && b <= 'Z')
				|| (b >= '0' && b <= '9');
			if (unreserved)
			{
				out.append((char) b);
			}
			else
			{
				out.append('%');
				out.append(Character.toUpperCase(Character.forDigit(b >> 4, 16)));
				out.append(Character.toUpperCase(Character.forDigit(b & 0xF, 16)));
			}
		}
		return out.toString();
	}

	/**
	 * Reverse of {@link #encode}: read a link payload back out of the href
	 * it was embedded in. Both halves live here so they cannot drift apart —
	 * a mismatch would silently break every place link in the panel.
	 */
	public static String decode(String encoded)
	{
		java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
		for (int i = 0; i < encoded.length(); i++)
		{
			char c = encoded.charAt(i);
			if (c == '%' && i + 2 < encoded.length())
			{
				int hi = Character.digit(encoded.charAt(i + 1), 16);
				int lo = Character.digit(encoded.charAt(i + 2), 16);
				if (hi >= 0 && lo >= 0)
				{
					bytes.write((hi << 4) | lo);
					i += 2;
					continue;
				}
			}
			bytes.write(c);
		}
		return new String(bytes.toByteArray(), StandardCharsets.UTF_8);
	}

	private interface ReaderSupplier
	{
		Reader open() throws IOException;
	}

	private Map<String, Place> read(ReaderSupplier source)
	{
		try
		{
			Reader reader = source.open();
			if (reader == null)
			{
				return new HashMap<>();
			}
			try (Reader r = reader)
			{
				PlaceFile file = gson.fromJson(r, PlaceFile.class);
				return file == null || file.places == null ? new HashMap<>() : file.places;
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read places file", e);
			return new HashMap<>();
		}
	}

	private void save()
	{
		File dir = localFile.getParentFile();
		if (dir != null && !dir.exists() && !dir.mkdirs())
		{
			log.warn("Could not create {}", dir);
			return;
		}
		PlaceFile file = new PlaceFile();
		file.version = FILE_VERSION;
		file.places = local;
		try (Writer writer = new FileWriter(localFile))
		{
			gson.toJson(file, writer);
		}
		catch (IOException e)
		{
			log.warn("Could not save places to {}", localFile, e);
		}
	}

	/** On-disk: {"version":1,"places":{"duke horacio":{"display":"Duke Horacio","x":3210,...}}} */
	private static class PlaceFile
	{
		int version;
		Map<String, Place> places;
	}

	private static class Place
	{
		String display;
		/** "quest" for quest start points; null for NPCs/towns. */
		String type;
		int x;
		int y;
		int plane;
		/** Item sources only: HOW to get it, chatted when the link routes. */
		String note;
		/**
		 * Item sources only, false = the vendor is an OBJECT (a chest, a
		 * dig spot) — the nearest-NPC anchor must not crown a bystander
		 * (the Lumbridge Cook wore the milk icon for the Culinaromancer's
		 * Chest). Null/absent = NPC nomination allowed.
		 */
		Boolean npc;
		/**
		 * Item sources only: the SCENE OBJECT that vends the item
		 * (lowercase, e.g. "culinaromancer's chest") — outlined with the
		 * goal item overhead while the goal is unmet, the object-vendor
		 * counterpart of the shopkeeper outline.
		 */
		String object;
		/**
		 * Item sources only: the NPC who sells it, BY NAME ("Diango") —
		 * named outlines never fall back to nearest-to-pin (a Market
		 * Guard walked past the stall and wore the card icon).
		 */
		String vendor;
	}
}

package com.ironscape.items;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.bank.BankSearch;

/**
 * The clickable button inside the bank interface that toggles the
 * guide-items view. The button only flips a flag and relayouts: while
 * active, BankMissingSection hides the native layout's children after
 * every bank build and draws per-step sections instead — no search or
 * tab state is touched, so the view is identical from any tab.
 *
 * Everything here must run on the client thread.
 */
@Slf4j
@Singleton
public class BankFilterButton
{
	private static final int BUTTON_SIZE = 25;
	// Sits left of where Quest Helper puts its button (408), so both fit.
	private static final int BUTTON_X = 380;
	private static final int BUTTON_Y = 5;

	private final Client client;
	private final net.runelite.client.callback.ClientThread clientThread;
	private final BankSearch bankSearch;

	/** True while the bank is showing only guide items. */
	@Getter
	private boolean active;

	private Widget background;

	@Inject
	public BankFilterButton(Client client,
		net.runelite.client.callback.ClientThread clientThread, BankSearch bankSearch)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.bankSearch = bankSearch;
	}

	/** (Re)create the button when the bank interface loads. */
	public void init()
	{
		Widget parent = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (parent == null)
		{
			log.info("bank filter button: bank UNIVERSE widget missing — button not created");
			return;
		}
		log.info("bank filter button: created on bank open");
		active = false;

		background = createGraphic(parent, "IRONSCAPE Optimal",
			SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL,
			BUTTON_SIZE, BUTTON_SIZE, BUTTON_X, BUTTON_Y);
		background.setAction(1, "View guide items");
		background.setOnOpListener((JavaScriptCallback) event -> toggle());

		createGraphic(parent, "",
			SpriteID.AchievementDiaryIcons.BLUE_QUESTS,
			BUTTON_SIZE - 6, BUTTON_SIZE - 6, BUTTON_X + 3, BUTTON_Y + 3);
	}

	/** Game tick of the last accepted toggle — the op event double-fires. */
	private int lastToggleTick = -1;

	private void toggle()
	{
		// One physical click delivers TWO op events (log showed activate +
		// deactivate ~a second apart, every time) — the filter switched
		// itself off before the player could see it. Anything within 3
		// ticks (~1.8s) of the last accepted toggle is the double-fire; a
		// deliberate re-click is slower than that.
		if (client.getTickCount() - lastToggleTick < 3)
		{
			log.info("bank filter: swallowed duplicate op event ({} ticks after toggle)",
				client.getTickCount() - lastToggleTick);
			return;
		}
		lastToggleTick = client.getTickCount();
		if (active)
		{
			log.info("bank filter: deactivated by button");
			deactivate(true);
		}
		else
		{
			log.info("bank filter: activated");
			active = true;
			background.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED);
			background.revalidate();
			// No search state is touched — the filter view simply hides the
			// native layout's children after each build (BankMissingSection)
			// and draws its own sections, so it works the same from any tab.
			//
			// invokeLater is LOAD-BEARING: this op listener runs INSIDE the
			// click's clientscript, and layoutBank() runs the bank build
			// script SYNCHRONOUSLY — re-entering the script engine from a
			// script froze the whole client. Deferred one tick, the build
			// runs from a clean stack.
			clientThread.invokeLater(() -> {
				if (active)
				{
					bankSearch.layoutBank();
				}
			});
		}
	}

	/**
	 * Turn the filter off.
	 *
	 * @param clearSearch also reset the bank search and relayout — true
	 *                    when the bank should snap back to its normal view
	 *                    (button toggled off, player clicked a real tab);
	 *                    false when the player just opened their OWN
	 *                    search, which must be left alone (their search
	 *                    interaction already relayouts).
	 */
	public void deactivate(boolean clearSearch)
	{
		if (!active)
		{
			return;
		}
		active = false;
		if (background != null)
		{
			background.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
			background.revalidate();
		}
		if (clearSearch)
		{
			// BankSearch.reset defers to the client thread internally, so
			// this is safe from any event context.
			bankSearch.reset(true);
		}
	}

	private static Widget createGraphic(Widget parent, String name, int spriteId,
		int width, int height, int x, int y)
	{
		Widget widget = parent.createChild(-1, WidgetType.GRAPHIC);
		widget.setOriginalWidth(width);
		widget.setOriginalHeight(height);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setSpriteId(spriteId);
		widget.setName(name);
		widget.setHasListener(true);
		widget.revalidate();
		return widget;
	}
}

package com.ironscape.items;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.RuneLite;
import net.runelite.client.game.ItemManager;

/**
 * Knows how many of each item the player owns: inventory + equipment live,
 * plus the bank as of the last time it was opened.
 *
 * The bank can only be read while its interface is open (a game
 * limitation every plugin shares), so we snapshot it on every bank visit
 * and persist the snapshot per game account — the same approach the Bank
 * Memory plugin uses. Counts are keyed by lowercase item NAME, because
 * step annotations name items in prose, not by id.
 *
 * All game reads happen on the client thread (the plugin forwards events
 * here); the Swing panel only reads the finished name->count map.
 */
@Slf4j
@Singleton
public class ItemTracker
{
	private final Client client;
	private final ItemManager itemManager;
	private final Gson gson;

	/** inventory + equipment + bank snapshot, by lowercase item name. Guarded by `this`. */
	private final Map<String, Integer> ownedByName = new HashMap<>();

	/** inventory + equipment only (what you have ON you). Guarded by `this`. */
	private final Map<String, Integer> carriedByName = new HashMap<>();

	/** EQUIPMENT only — "Equip Gas mask" is done when it's worn, not owned. */
	private final Map<String, Integer> wornByName = new HashMap<>();

	/** Bank snapshot by lowercase item name (client thread only). */
	private Map<String, Integer> bankByName = new HashMap<>();

	/** Id-keyed tallies, for variants that share one name. See countById. */
	private final Map<Integer, Integer> carriedById = new HashMap<>();
	private final Map<Integer, Integer> ownedById = new HashMap<>();
	private Map<Integer, Integer> bankById = new HashMap<>();

	/** Which account the current bank snapshot belongs to. */
	private long accountHash = -1;

	@Inject
	public ItemTracker(Client client, ItemManager itemManager, Gson gson)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.gson = gson;
	}

	/** How many of this item the player owns anywhere (0 if none or unknown name). Safe from any thread. */
	public synchronized int countOf(String name)
	{
		return resolve(ownedByName, name);
	}

	/** How many the player has ON them (inventory + worn), excluding the bank. */
	public synchronized int carriedCountOf(String name)
	{
		return resolve(carriedByName, name);
	}

	/** How many the player is WEARING — carrying one in the bag doesn't count. */
	public synchronized int wornCountOf(String name)
	{
		return resolve(wornByName, name);
	}

	/**
	 * Count one EXACT item id, for annotation entries that name an id
	 * because the item's name is shared with another item.
	 *
	 * No alias, substitute or family logic: an id is already unambiguous,
	 * and every one of those mechanisms exists to paper over names.
	 */
	public synchronized int countOfId(int id)
	{
		return ownedById.getOrDefault(id, 0);
	}

	/** As countOfId, inventory + worn only. */
	public synchronized int carriedCountOfId(int id)
	{
		return carriedById.getOrDefault(id, 0);
	}

	/**
	 * Items that COUNT AS another item — a Bruma torch lights braziers
	 * and fires, so "tinderbox 0/1" must go green for the player who
	 * upgraded. One-directional: the torch satisfies tinderbox needs,
	 * never the other way around.
	 */
	/** Every metal tier of a tool: bare "pickaxe" means ANY pickaxe. */
	private static String[] tiers(String tool)
	{
		String[] metals = {"bronze", "iron", "steel", "black", "mithril", "adamant", "rune", "dragon"};
		String[] out = new String[metals.length];
		for (int i = 0; i < metals.length; i++)
		{
			out[i] = metals[i] + " " + tool;
		}
		return out;
	}

	private static final Map<String, String[]> SUBSTITUTES = Map.ofEntries(
		Map.entry("tinderbox", new String[]{"bruma torch"}),
		Map.entry("hammer", new String[]{"imcando hammer"}),
		// Bare "gloves"/"boots" in the guide mean the basic leather ones
		// the clothes shops sell.
		Map.entry("glove", new String[]{"leather gloves"}),
		Map.entry("gloves", new String[]{"leather gloves"}),
		Map.entry("boot", new String[]{"leather boots"}),
		Map.entry("boots", new String[]{"leather boots"}),
		// An unqualified tool means any tier you own ("take out pickaxe").
		Map.entry("pickaxe", tiers("pickaxe")),
		Map.entry("pickaxes", tiers("pickaxe")),
		Map.entry("axe", tiers("axe")),
		Map.entry("axes", tiers("axe")));

	/**
	 * Bare family words: "runes" means the runes you bought, "bars" the
	 * bars you smelted, "beads" the four imp bead colours — no single
	 * item can match, so anything in the family counts. Suffixes are in
	 * CANONICAL (singular) form and members are matched canonically,
	 * because the game names some families singular ("Black bead") and
	 * others plural ("Steel nails").
	 */
	private static final Map<String, String> FAMILY_SUFFIX = Map.of(
		"runes", " rune",
		"all runes", " rune",
		"all of your runes", " rune",
		"bars", " bar",
		"beads", " bead",
		"nails", " nail",
		"nail", " nail");

	private static int resolve(Map<String, Integer> counts, String name)
	{
		String suffix = FAMILY_SUFFIX.get(name.toLowerCase(Locale.ROOT).trim());
		if (suffix != null)
		{
			int total = 0;
			for (Map.Entry<String, Integer> entry : counts.entrySet())
			{
				if (canonical(entry.getKey()).endsWith(suffix))
				{
					total += entry.getValue();
				}
			}
			return total;
		}
		String[] chain = aliases(name);
		Integer base = null;
		for (String candidate : chain)
		{
			Integer count = counts.get(candidate);
			if (count != null)
			{
				base = count;
				break;
			}
		}
		// Even with zero of the item itself, a substitute still counts —
		// look substitutes up under every alias, not just the matched one.
		int substitutes = 0;
		for (String candidate : chain)
		{
			String[] alternates = SUBSTITUTES.get(candidate);
			if (alternates == null)
			{
				continue;
			}
			for (String alternate : alternates)
			{
				substitutes += counts.getOrDefault(alternate, 0);
			}
			break;
		}
		// Last resort: canonical comparison that forgives apostrophes,
		// possessives and plural drift — the guide writes "wizard mind
		// bombs", the item is "Wizard's mind bomb". Exact/alias/substitute
		// matches above always win.
		if (base == null && substitutes == 0)
		{
			// canonical of the RESOLVED key (chain[0]), not the raw name.
			// aliases() is where "gp"->coins, "noted X"->X, teletab->tab
			// and the whole COLLOQUIAL map get applied, so measuring the
			// raw name here meant a colloquial could never reach this
			// fallback: "super antipoison" -> "superantipoison" was a
			// dead entry against the carried "Superantipoison(1)", which
			// is what the new dose test caught on its very first run.
			String want = canonical(chain.length > 0 ? chain[0] : name);
			// A goal that NAMES a dose means that dose. canonical() folds
			// "(4)" away so any dose satisfies any other, which is right
			// for "drink a restore potion" and wrong for "decant them
			// until you have 6 full pots" — twenty-four 1-dose vials would
			// read 6/6 while the step's whole job is turning them into
			// four-dose ones. Dose-less goals are untouched: this only
			// engages when the annotation spells the dose out.
			String wantDose = doseOf(name);
			if (!want.isEmpty())
			{
				for (Map.Entry<String, Integer> entry : counts.entrySet())
				{
					if (!canonical(entry.getKey()).equals(want))
					{
						continue;
					}
					if (wantDose != null && !wantDose.equals(doseOf(entry.getKey())))
					{
						continue;
					}
					return entry.getValue();
				}
			}
		}
		return (base == null ? 0 : base) + substitutes;
	}

	/**
	 * Does a carried item (by its in-game name) satisfy a guide goal name?
	 * Full matching stack: aliases, substitutes (any pickaxe tier),
	 * family sums and canonical spelling drift. Used by the inventory
	 * hint overlay to light up the step's items.
	 */
	public static boolean nameMatchesGoal(String itemName, String goalName)
	{
		return resolve(Map.of(itemName.toLowerCase(Locale.ROOT), 1), goalName) > 0;
	}

	/** The "(4)" of "Superantipoison(4)", or null when it names no dose. */
	private static String doseOf(String name)
	{
		java.util.regex.Matcher m = DOSE.matcher(name);
		return m.find() ? m.group(1) : null;
	}

	private static final java.util.regex.Pattern DOSE =
		java.util.regex.Pattern.compile("\\((\\d+)\\)");

	/**
	 * Spelling-drift-proof form of an item name: lowercase, punctuation
	 * gone (so possessive 's collapses), every word depluralized.
	 * "Wizard's mind bomb" and "wizard mind bombs" both become
	 * "wizard mind bomb".
	 */
	// Public so the audit dump can emit the REAL canonical forms rather
	// than a second copy of this method (com.ironscape.goals is a
	// different package). Pure function; nothing else changes.
	public static String canonical(String name)
	{
		StringBuilder sb = new StringBuilder();
		// Numeric potion doses collapse: "Restore potion(3)" and the
		// guide's "restore potion" are the same thing, any dose counts.
		// Non-numeric parens ("(unf)") are DIFFERENT items and stay.
		for (String word : name.toLowerCase(Locale.ROOT).replaceAll("\\(\\d+\\)", "")
			.replaceAll("[^a-z0-9 ]", "").split("\\s+"))
		{
			if (word.isEmpty())
			{
				continue;
			}
			// Irregular -ves plurals fold to their -f singular: leaves ->
			// leaf; knives and knife both land on "knif".
			if (word.length() > 4 && word.endsWith("ves"))
			{
				word = word.substring(0, word.length() - 3) + "f";
			}
			else if (word.length() > 3 && word.endsWith("fe"))
			{
				word = word.substring(0, word.length() - 1);
			}
			// "glass"/"grass" keep their s; short words like "gp" too.
			else if (word.length() > 3 && word.endsWith("s") && !word.endsWith("ss"))
			{
				word = word.substring(0, word.length() - 1);
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(word);
		}
		return sb.toString();
	}

