	/**
	 * The in-game item names a guide phrase might refer to, most literal
	 * first. The guide abbreviates: "100 mind" means Mind runes, "1 log" is
	 * the item "Logs", "2 buckets" is the item "Bucket", "bolts of cloth"
	 * is "Bolt of cloth", "POH tab" is "Teleport to house". Also used by
	 * the bank filter.
	 */
	public static String[] aliases(String name)
	{
		String key = name.toLowerCase(Locale.ROOT).trim();
		// "fire staff (equip)" — the parenthetical is an instruction to
		// wear it, not part of the item name. Doses like "(1)" stay.
		key = key.replaceFirst("\\s*\\((?:equip(?:ped)?|wear|worn)\\)$", "");
		// noted items canonicalize to the real item when counting, so
		// "noted planks" is just "planks"
		if (key.startsWith("noted "))
		{
			key = key.substring("noted ".length());
		}
		// the guide says gp/gold/cash; the item is "Coins"
		if (key.equals("gp") || key.equals("gold") || key.equals("cash") || key.equals("money"))
		{
			key = "coins";
		}
		// "Buy 20 teleports for chronicle": the item is a "Teleport card".
		if (key.equals("teleports") || key.equals("teleport cards"))
		{
			key = "teleport card";
		}
		// Traiborn's bone-payment key is a "Silverlight key" (Demon Slayer).
		if (key.equals("demon slayer key"))
		{
			key = "silverlight key";
		}
		// Rune Mysteries' hand-ins are "Research package" and "Research
		// notes" in-game; kits call them by the quest's name (owner-hit).
		if (key.equals("rune mysteries notes"))
		{
			key = "research notes";
		}
		if (key.equals("rune mysteries package"))
		{
			key = "research package";
		}
		// Prince Ali's colloquials: the crafted items are literally named
		// "Paste" and "Key print" — the guide (and everyone) says otherwise.
		if (key.equals("skin paste"))
		{
			key = "paste";
		}
		if (key.equals("key imprint"))
		{
			key = "key print";
		}
		// "few cakes" / "plenty of stews" are cakes and stews — annotation
		// item names carry the guide's quantifier words; strip them like
		// the goal detector does or the count never matches anything.
		key = key.replaceFirst("^(?:a )?(?:few|couple|plenty|some|bunch) (?:of )?", "");
		// "house teletabs" / "fally teletab" are the same words the
		// COLLOQUIAL map already knows as "house tabs" / "fally tab".
		key = key.replace("teletab", "tab");
		// the guide says "arrowheads"; smithable metal ones are named
		// "arrowtips" in game. Metal-specific on purpose: "Broad
		// arrowheads" really is called arrowheads.
		key = key.replaceFirst(
			"^(bronze|iron|steel|mithril|adamant|rune|amethyst) arrowheads?$", "$1 arrowtips");
		String colloquial = COLLOQUIAL.get(key);
		if (colloquial != null)
		{
			key = colloquial;
		}
		String singular = key.endsWith("s") ? key.substring(0, key.length() - 1) : key;

		// "bolts of cloth" -> "bolt of cloth": the plural sits on the FIRST
		// word in of-phrases, so depluralize that too.
		String[] words = key.split(" ", 2);
		String firstSingular = words[0].endsWith("s")
			? words[0].substring(0, words[0].length() - 1) + (words.length > 1 ? " " + words[1] : "")
			: key;

		java.util.List<String> out = new java.util.ArrayList<>(java.util.List.of(
			key,             // exact:      "mind rune"
			singular,        // deplural:   "buckets" -> "bucket"
			firstSingular,   // of-phrase:  "bolts of cloth" -> "bolt of cloth"
			key + "s",       // plural:     "log" -> "logs"
			key + " rune",   // elemental:  "mind" -> "mind rune"
			singular + " rune", // "minds" -> "mind rune"
			// ORES, the same shorthand one metal over: everybody says
			// "grab 4 copper", the item is "Copper ore", and the badge sat
			// at 0/4 beside a copper-ore ICON — because item_ids gave the
			// name a sprite while counting matched by name and found
			// nothing (owner, in play). Safe for the same reason the rune
			// alias is: it only ever resolves if that item really exists.
			key + " ore",
			singular + " ore"));
		// Shop packs: the guide says "bucket pack", the item is "Empty
		// bucket pack". (Feather/bait packs really are named "X pack",
		// so the un-prefixed key stays first.)
		if (key.endsWith(" pack"))
		{
			out.add("empty " + key);
		}
		// Elemental staves: the guide says "fire staff", the item is
		// "Staff of fire". (Battlestaves really are "Fire battlestaff",
		// caught by the exact key.)
		String stem = singular.endsWith(" staff")
			? singular.substring(0, singular.length() - " staff".length()) : null;
		if (stem != null && java.util.Set.of("fire", "water", "air", "earth").contains(stem))
		{
			out.add("staff of " + stem);
		}
		// Irregular -ves plurals: "woad leaves" is the item "Woad leaf",
		// "knives" is "Knife".
		if (key.endsWith("ves"))
		{
			String base = key.substring(0, key.length() - 3);
			out.add(base + "f");
			out.add(base + "fe");
		}
		// "rune pick" is a rune pickaxe; "varrock armor" is spelt armour.
		if (singular.endsWith(" pick"))
		{
			out.add(singular + "axe");
		}
		if (key.contains("armor"))
		{
			out.add(key.replace("armor", "armour"));
		}
		// Last resort: drop a trailing parenthetical — annotation authors
		// write "bones (kill goblins south of the jail)". Runs after the
		// literal candidates so real parens ("super antipoison(1)") win.
		String noParen = key.replaceFirst("\\s*\\([^)]*\\)$", "").trim();
		if (!noParen.equals(key) && !noParen.isEmpty())
		{
			out.add(noParen);
			out.add(noParen.endsWith("s") ? noParen.substring(0, noParen.length() - 1) : noParen + "s");
		}
		return out.toArray(new String[0]);
	}

	/** Resolved icon item ids by guide item name; -1 = no icon found. */
	private final Map<String, Integer> iconIdByName = new HashMap<>();

	/**
	 * Bundled name -> item id map seeded from the OSRS Wiki
	 * (tools/seed-item-ids.mjs). The price-list search below only knows
	 * TRADEABLE items; this covers quest items and other untradeables so
	 * they get sprites too. Loaded lazily on first icon lookup.
	 */
	private Map<String, Integer> bundledItemIds;

	private Map<String, Integer> bundledItemIds()
	{
		if (bundledItemIds == null)
		{
			bundledItemIds = new HashMap<>();
			try (java.io.InputStream in = com.ironscape.DataFiles.open(ItemTracker.class, "item_ids.json"))
			{
				if (in != null)
				{
					Map<String, Double> parsed = gson.fromJson(
						new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8),
						new TypeToken<Map<String, Double>>()
						{
						}.getType());
					parsed.forEach((name, id) -> bundledItemIds.put(name, id.intValue()));
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Could not read bundled item ids", e);
			}
		}
		return bundledItemIds;
	}

	/**
	 * Puts the item's sprite on a Swing label (async — RuneLite fills the
	 * image in when loaded). Names resolve through the same alias chain
	 * the counters use, against the client's item price list; quest-only
	 * untradeables simply get no icon.
	 */
	public void attachIcon(String name, javax.swing.JLabel label)
	{
		int id = iconIdFor(name);
		if (id > 0)
		{
			itemManager.getImage(id).addTo(label);
		}
	}

	/**
	 * Sprite for an EXACT item id — an id-keyed need already knows precisely
	 * which item it means, so it should not go looking the name up again.
	 * "Priest gown (top)" is not a name any item has; it only ever resolved
	 * because the alias chain drops the parenthetical, and it would have
	 * given both halves the same sprite.
	 */
	public void attachIconById(int id, javax.swing.JLabel label)
	{
		if (id > 0)
		{
			itemManager.getImage(id).addTo(label);
		}
	}

	/**
	 * Drop everything read from the data files, so ::ironreload picks up an
	 * edited item_ids.json or gear_sets.json. The icon memo goes with them:
	 * it caches the ANSWER, so a name that once resolved to nothing would
	 * stay resolved to nothing however many ids were added underneath it.
	 */
	public synchronized void reloadBundledData()
	{
		bundledItemIds = null;
		gearSets = null;
		iconIdByName.clear();
	}

	/** The item id whose sprite represents this guide item name; -1 = none found. */
	public synchronized int iconIdFor(String name)
	{
		return iconIdByName.computeIfAbsent(
			name.toLowerCase(Locale.ROOT).trim(), this::lookupIconId);
	}

	/**
	 * Named item sets bundled from the wiki (items/gear_sets.json) —
	 * "warm clothing" is the Wintertodt list. Loaded lazily.
	 */
	private Map<String, List<String>> gearSets;

	private Map<String, List<String>> gearSets()
	{
		if (gearSets == null)
		{
			gearSets = new HashMap<>();
			try (java.io.InputStream in = com.ironscape.DataFiles.open(ItemTracker.class, "gear_sets.json"))
			{
				if (in != null)
				{
					GearSetsFile parsed = gson.fromJson(
						new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8),
						GearSetsFile.class);
					if (parsed != null && parsed.sets != null)
					{
						gearSets = parsed.sets;
					}
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Could not read bundled gear sets", e);
			}
		}
		return gearSets;
	}

	private static class GearSetsFile
	{
		int version;
		Map<String, List<String>> sets;
	}

	/**
	 * How many DISTINCT items of the named set the player carries or wears
	 * (bank excluded — the check is "am I equipped for this right now").
	 */
	public int distinctCarried(String setName)
	{
		int have = 0;
		for (String name : gearSets().getOrDefault(setName, Collections.emptyList()))
		{
			if (carriedCountOf(name) > 0)
			{
				have++;
			}
		}
		return have;
	}

	/** 200000 -> "200,000": item counts in badges/overlays get grouping. */
	public static String formatCount(int n)
	{
		return String.format(Locale.US, "%,d", n);
	}

	/**
	 * "compost pack" -> "Compost pack" for DISPLAY (badges, overlays) —
	 * guide/annotation names are lowercase for matching, but the panel
	 * should read like the game does (owner ask). Never use this on
	 * names that feed matching.
	 */
	public static String capitalize(String name)
	{
		return name == null || name.isEmpty()
			? name
			: Character.toUpperCase(name.charAt(0)) + name.substring(1);
	}

	/** Cached stackability by guide item name; see bankCountable. */
	private final Map<String, Boolean> stackableByName =
		new java.util.concurrent.ConcurrentHashMap<>();

	/**
	 * Should this goal count the BANK as well as carried items? Only when
	 * the quantity physically can't be carried: more than an inventory of
	 * a NON-stackable item ("gather 130 planks"). 1000 arrow shafts is one
	 * stack — the step means "holding them", so banking them again must
	 * re-open it, exactly like any other carried goal.
	 */
	public boolean bankCountable(String name, int quantity)
	{
		// Gold is WEALTH, not cargo: "until 200k cash" counts the bank no
		// matter what — banked coins showing 0/200,000 after a relog read
		// as lost progress. (Spending it later never re-opens the step;
		// the reopen logic skips coin goals.)
		for (String alias : aliases(name))
		{
			if (alias.equals("coins"))
			{
				return true;
			}
		}
		// A FULL inventory's worth ("buy 1 inv of bronze bars" = 28) is
		// bought to be banked — count the bank for it, like over-inventory
		// gathers. Below that, carried-only rules apply.
		if (quantity < com.ironscape.goals.GoalDetector.CARRYABLE_LIMIT)
		{
			return false;
		}
		String key = name.toLowerCase(Locale.ROOT).trim();
		Boolean stackable = stackableByName.get(key);
		if (stackable == null)
		{
			// Item compositions may only load on the client thread — the
			// panel's Swing badges asking first CRASHED the panel build
			// (AssertionError truncated the step list). Off-thread, fall
			// back to the quantity-only rule; the next game-tick
			// evaluation caches the real answer and the badges refresh.
			if (!client.isClientThread())
			{
				return true;
			}
			try
			{
				int id = iconIdFor(key);
				stackable = id > 0 && itemManager.getItemComposition(id).isStackable();
			}
			catch (RuntimeException e)
			{
				stackable = false; // unknown item: keep the quantity-only rule
			}
			stackableByName.put(key, stackable);
		}
		return !stackable;
	}

	private int lookupIconId(String name)
	{
		for (String alias : aliases(name))
		{
			// Wiki-seeded map first: it covers untradeables the price
			// list can't resolve.
			Integer bundled = bundledItemIds().get(alias);
			if (bundled != null)
			{
				return bundled;
			}
			// Coins aren't tradeable, so the price-list search misses them.
			if (alias.equals("coins"))
			{
				return net.runelite.api.gameval.ItemID.COINS;
			}
			for (net.runelite.http.api.item.ItemPrice price : itemManager.search(alias))
			{
				if (price.getName().equalsIgnoreCase(alias)
					|| canonical(price.getName()).equals(canonical(alias)))
				{
					return price.getId();
				}
			}
		}
		// A possessive in the REAL name defeats substring search ("wizard
		// mind bomb" never brings back "Wizard's mind bomb"): search the
		// name's last word alone and canonical-compare the hits.
		String[] words = name.toLowerCase(Locale.ROOT).trim().split("\\s+");
		if (words.length > 1)
		{
			String want = canonical(name);
			String lastSingular = words[words.length - 1];
			if (lastSingular.length() > 3 && lastSingular.endsWith("s") && !lastSingular.endsWith("ss"))
			{
				lastSingular = lastSingular.substring(0, lastSingular.length() - 1);
			}
			for (net.runelite.http.api.item.ItemPrice price : itemManager.search(lastSingular))
			{
				if (canonical(price.getName()).equals(want))
				{
					return price.getId();
				}
			}
		}
		// Substitute-only names ("pickaxe" = any tier) have no item of
		// their own — borrow the FIRST substitute's sprite.
		for (String alias : aliases(name))
		{
			String[] alternates = SUBSTITUTES.get(alias);
			if (alternates != null && alternates.length > 0)
			{
				int id = lookupIconId(alternates[0]);
				if (id > 0)
				{
					return id;
				}
			}
		}
		// Family names ("beads", "bars") borrow any family member's sprite.
		// Canonical comparison, same as counting: "Black bead" is singular
		// in game, the suffix is canonical-singular.
		String suffix = FAMILY_SUFFIX.get(name.toLowerCase(Locale.ROOT).trim());
		if (suffix != null)
		{
			for (net.runelite.http.api.item.ItemPrice price : itemManager.search(suffix.trim()))
			{
				if (canonical(price.getName()).endsWith(suffix))
				{
					return price.getId();
				}
			}
		}
		return -1;
	}

	/** Client thread. Forwarded by the plugin on every container change. */
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			bankByName = countByName(event.getItemContainer());
			// Only chance to see the bank BY ID — the persisted snapshot is
			// names only, so this is what an id-keyed need can know about
			// banked stock (see countById).
			bankById = countById(event.getItemContainer());
			saveBank();
			rebuild();
		}
		else if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			rebuild();
		}
	}

	/** Client thread. Load the right account's bank snapshot after login. */
	public void onLoggedIn()
	{
		long hash = client.getAccountHash();
		if (hash != -1 && hash != accountHash)
		{
			accountHash = hash;
			bankByName = loadBank();
		}
		rebuild();
	}

	/**
	 * The account hash is often still -1 on the LOGIN event itself — the
	 * persisted bank snapshot silently never loaded, and every banked
	 * count read 0 until the player physically opened a bank. Called each
	 * game tick; loads the snapshot the moment the hash exists.
	 *
	 * @return true when the snapshot was just loaded (refresh the panel)
	 */
	public boolean ensureBankLoaded()
	{
		if (accountHash != -1)
		{
			return false;
		}
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return false;
		}
		accountHash = hash;
		bankByName = loadBank();
		rebuild();
		log.info("Loaded persisted bank snapshot ({} item names) for account", bankByName.size());
		return true;
	}

	private void rebuild()
	{
		Map<String, Integer> carried = new HashMap<>();
		mergeContainer(carried, client.getItemContainer(InventoryID.INV));
		mergeContainer(carried, client.getItemContainer(InventoryID.WORN));
		// Equipment kept separately too — an "equip X" step needs to tell
		// worn from merely carried, which the merged map can't.
		Map<String, Integer> worn = new HashMap<>();
		mergeContainer(worn, client.getItemContainer(InventoryID.WORN));

		// Bank counts come ONLY from bank container EVENTS (bankByName):
		// withdrawals always fire one, so the snapshot tracks reality.
		// We used to prefer client.getItemContainer(BANK) here, but that
		// cached container was seen retaining withdrawn items ("steel axe
		// 2/1" with one axe carried and none banked) — event-sourced state
		// can't drift like that.
		//
		// DEPOSIT BOXES are the one path into the bank that fires no bank
		// event: items that just left the player's hands while the box is
		// open were deposited, so credit them to the snapshot ourselves —
		// otherwise the gold dropped off at the Port Sarim box reads as
		// vanished until the next real bank visit.
		net.runelite.api.widgets.Widget depositBox =
			client.getWidget(net.runelite.api.gameval.InterfaceID.BankDepositbox.UNIVERSE);
		if (depositBox != null && !depositBox.isHidden())
		{
			boolean credited = false;
			synchronized (this)
			{
				for (Map.Entry<String, Integer> old : carriedByName.entrySet())
				{
					int delta = old.getValue() - carried.getOrDefault(old.getKey(), 0);
					if (delta > 0)
					{
						bankByName.merge(old.getKey(), delta, Integer::sum);
						credited = true;
					}
				}
			}
			if (credited)
			{
				saveBank();
			}
		}

		Map<String, Integer> total = new HashMap<>(bankByName);
		carried.forEach((name, count) -> total.merge(name, count, Integer::sum));

		synchronized (this)
		{
			// did anything LEAVE the player's hands? (give/fix/build steps)
			boolean consumed = false;
			for (Map.Entry<String, Integer> old : carriedByName.entrySet())
			{
				if (carried.getOrDefault(old.getKey(), 0) < old.getValue())
				{
					consumed = true;
					break;
				}
			}
			lastRebuildConsumedCarried = consumed;

			carriedByName.clear();
			carriedByName.putAll(carried);
			wornByName.clear();
			wornByName.putAll(worn);
			ownedByName.clear();
			ownedByName.putAll(total);

			// Id tallies alongside the name ones. Inventory and worn are read
			// live, so they are always right; the bank half is whatever the
			// last bank event saw this session (see countById).
			carriedById.clear();
			carriedById.putAll(countById(client.getItemContainer(InventoryID.INV)));
			countById(client.getItemContainer(InventoryID.WORN))
				.forEach((id, count) -> carriedById.merge(id, count, Integer::sum));
			ownedById.clear();
			ownedById.putAll(bankById);
			carriedById.forEach((id, count) -> ownedById.merge(id, count, Integer::sum));
		}
	}

	private boolean lastRebuildConsumedCarried;

	/** Did the last container change reduce something the player carried? */
	public synchronized boolean lastRebuildConsumedCarried()
	{
		return lastRebuildConsumedCarried;
	}

	private void mergeContainer(Map<String, Integer> counts, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		countByName(container).forEach((name, count) -> counts.merge(name, count, Integer::sum));
	}

	/**
	 * The same tally, keyed by canonical item ID — for the items a NAME
	 * cannot tell apart.
	 *
	 * Both halves of the priest gown are called exactly "Priest gown" (ids
	 * 426 and 428, and the wiki records that same single name for both), so
	 * a name tally can only ever report the pair's total: "1/2", without
	 * saying which half you are missing. Only an annotation that names the
	 * ID can, and only these maps can answer it.
	 *
	 * IN MEMORY ONLY, unlike bankByName. The persisted bank snapshot stores
	 * names, so a half sitting in the bank is invisible to an id-keyed need
	 * until the bank is opened once in this session. That is acceptable
	 * where it is used — an id need is for telling variants apart on a
	 * shopping step you are carrying out — and changing the snapshot format
	 * is a much larger job than this earns.
	 */
	private Map<Integer, Integer> countById(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			if (itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			counts.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
		}
		return counts;
	}

	private Map<String, Integer> countByName(ItemContainer container)
	{
		Map<String, Integer> counts = new HashMap<>();
		for (Item item : container.getItems())
		{
			// -1 = empty slot; quantity 0 = defensive
			if (item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			// A bank PLACEHOLDER is its own item id with quantity 1 —
			// canonicalize() would map it onto the real item and count a
			// phantom copy ("pickaxe 2/1" after withdrawing the only one).
			if (itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			// canonicalize: a noted item counts as the real thing
			int canonicalId = itemManager.canonicalize(item.getId());
			String name = itemManager.getItemComposition(canonicalId).getName()
				.toLowerCase(Locale.ROOT);
			counts.merge(name, item.getQuantity(), Integer::sum);
		}
		return counts;
	}

	// ------------------------------------------------------------------
	// Bank snapshot persistence, one file per game account
	// ------------------------------------------------------------------

	private File bankFile()
	{
		return new File(RuneLite.RUNELITE_DIR, "ironscape/bank-" + accountHash + ".json");
	}

	private void saveBank()
	{
		if (accountHash == -1)
		{
			return;
		}
		File file = bankFile();
		File dir = file.getParentFile();
		if (dir != null && !dir.exists() && !dir.mkdirs())
		{
			log.warn("Could not create {}", dir);
			return;
		}
		try (Writer writer = new FileWriter(file))
		{
			gson.toJson(bankByName, writer);
		}
		catch (IOException e)
		{
			log.warn("Could not save bank snapshot", e);
		}
	}

	private Map<String, Integer> loadBank()
	{
		File file = bankFile();
		if (accountHash == -1 || !file.exists())
		{
			return new HashMap<>();
		}
		try (Reader reader = new FileReader(file))
		{
			Map<String, Integer> loaded = gson.fromJson(reader,
				new TypeToken<Map<String, Integer>>()
				{
				}.getType());
			return loaded == null ? new HashMap<>() : loaded;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not load bank snapshot", e);
			return new HashMap<>();
		}
	}
}

package com.ironscape.items;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * The Quest Helper-style bank view: while the filter is active the
 * native grid is blanked (see the plugin's bankSearchFilter callback)
 * and every upcoming step renders as its own section — a step-title
 * header, then ALL of that step's items with a green/red "have/need"
 * count under each icon; items still missing are ghosted. Rebuilt after
 * every bank layout pass while the filter is active; hidden otherwise.
 *
 * All of it must run on the client thread (the plugin calls update()
 * from BANKMAIN_FINISHBUILDING, deferred to the end of the tick).
 */
@Slf4j
@Singleton
public class BankMissingSection
{
	/** One step's worth of still-missing items, in guide order. */
	public static class Section
	{
		public final String title;
		public final Map<String, Integer> items = new LinkedHashMap<>();

		public Section(String title)
		{
			this.title = title;
		}
	}

	/** Native bank grid geometry: 8 columns of 36x32 icons. */
	private static final int FIRST_COLUMN_X = 51;
	private static final int COLUMN_SPACING = 48;
	/** Icon (32) + have/need line (12) + breathing room. */
	private static final int ROW_SPACING = 52;
	private static final int COLUMNS = 8;

	private static final int HEADER_COLOR = 0xff981f; // RuneScape orange
	private static final int COUNT_MET_COLOR = 0x2ecc40; // green: have >= need
	private static final int COUNT_SHORT_COLOR = 0xff6060; // red: still missing

	private final Client client;
	private final net.runelite.client.callback.ClientThread clientThread;
	private final ItemTracker itemTracker;

	/**
	 * Every widget WE added to the bank container, in creation order, so
	 * the next pass can tear them down. No pooling: see create().
	 */
	private final java.util.Set<Widget> addedWidgets = new java.util.LinkedHashSet<>();

	/** Real bank widgets we moved/restyled last pass, to restore on the next. */
	private final java.util.Set<Widget> movedWidgets = new java.util.HashSet<>();

	/** Where the bank originally had each moved widget: widget -> {x, y}. */
	private final Map<Widget, int[]> movedHome = new java.util.HashMap<>();

	/** Native widgets WE hid, so turning the filter off can show them again. */
	private final java.util.Set<Widget> hiddenByUs = new java.util.LinkedHashSet<>();

	/** Last logged pass shape, so the diagnosis line only prints on change. */
	private String lastShape;

	/** Last per-item branch record, so only CHANGES print. */
	private String lastTrace;

	/** Real bank items the last COMPLETED pass saw (see the not-ready guard). */
	private int lastNativeCount;

	/**
	 * The last pass found FEWER populated item widgets than the bank item
	 * container actually holds — the widgets have not caught up, so an item
	 * that is really in the bank had to be drawn as an unclickable ghost.
	 * The plugin watches this to decide whether a deposit needs the client
	 * prodded into a rebuild; nothing guesses that it is happening.
	 */
	@lombok.Getter
	private boolean lastPassStale;

	/** Bank item widgets carrying an actual item right now. */
	private static int countPopulatedItems(Widget container)
	{
		int populated = 0;
		for (Widget child : container.getDynamicChildren())
		{
			if (child != null && child.getItemId() > 0 && child.getItemQuantity() > 0)
			{
				populated++;
			}
		}
		return populated;
	}

	private final net.runelite.client.game.ItemManager itemManager;

	@Inject
	public BankMissingSection(Client client,
		net.runelite.client.callback.ClientThread clientThread, ItemTracker itemTracker,
		net.runelite.client.game.ItemManager itemManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemTracker = itemTracker;
		this.itemManager = itemManager;
	}

	/** Distinct real (non-placeholder) item stacks the BANK CONTAINER holds. */
	private int bankContainerItems()
	{
		net.runelite.api.ItemContainer bank =
			client.getItemContainer(net.runelite.api.gameval.InventoryID.BANK);
		if (bank == null)
		{
			return -1;
		}
		int count = 0;
		for (net.runelite.api.Item item : bank.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * Item NAMES the bank container holds right now, canonicalized the same
	 * way the widget index is — the authoritative "what is in the bank",
	 * independent of whether the client has drawn a widget for it yet.
	 */
	private java.util.Set<String> bankContainerNames()
	{
		net.runelite.api.ItemContainer bank =
			client.getItemContainer(net.runelite.api.gameval.InventoryID.BANK);
		java.util.Set<String> names = new java.util.HashSet<>();
		if (bank == null)
		{
			return names;
		}
		for (net.runelite.api.Item item : bank.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				names.add(itemManager.getItemComposition(itemManager.canonicalize(item.getId()))
					.getName().toLowerCase(java.util.Locale.ROOT));
			}
		}
		return names;
	}

	/**
	 * Show (or hide) the sections.
	 *
	 * @param trigger what asked for this pass ("build" = the client's own
	 *                bank build, "bank-change" = the container changed under
	 *                us). Part of the logged shape, so a pass that changes
	 *                nothing else still prints when its cause differs —
	 *                without it, "no log line" was misread as "no pass ran".
	 */
	public void update(boolean show, List<Section> sections, String trigger)
	{
		// NOT-READY GUARD, and it must come BEFORE anything below touches
		// the pools. BANKMAIN_BUILD fires TWICE around a withdrawal: the
		// first time the child array has already been resized but the item
		// widgets carry no itemId yet. Laying out from that snapshot found
		// zero real items and drew EVERY icon as a ghost for one frame —
		// the "icons move/disappear as I withdraw" reports. The owner's
		// captured log, one withdrawal:
		//   pass: 9 moved,  2 ghosts, 1461 children
		//   pools went stale (container resized) — recreating
		//   pass: 0 moved, 11 ghosts, 1438 children   <-- this frame
		//   pass: 10 moved, 1 ghosts, 1466 children
		// Skipping leaves the previous layout alone and the very next
		// build (milliseconds later) lays out properly. Guarded on having
		// seen items before, so a genuinely EMPTY bank still renders.
		Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (show && !sections.isEmpty() && itemContainer != null
			&& lastNativeCount > 0 && countPopulatedItems(itemContainer) == 0)
		{
			log.info("bank filter: container not populated yet — keeping the last pass");
			return;
		}

		// Tear down last pass's widgets rather than re-styling them.
		if (itemContainer != null)
		{
			removeAddedWidgets(itemContainer);
		}
		// Put the NATIVE grid back exactly as we found it: original x/y for
		// every widget we moved, and un-hide everything we hid.
		//
		// This used to be unnecessary — we ran DURING the bank build, so the
		// client's own layout overwrote us afterwards ("nothing is
		// permanently lost"). Running at TICK END means our changes now
		// land last and STICK: with the filter off, reopening the bank
		// showed only the step's items, still sitting in our layout, and
		// nothing else. Restoring is our job now.
		for (Widget widget : movedWidgets)
		{
			widget.setItemQuantityMode(1);
			int[] home = movedHome.get(widget);
			if (home != null)
			{
				widget.setOriginalX(home[0]);
				widget.setOriginalY(home[1]);
				widget.revalidate();
			}
		}
		movedWidgets.clear();
		movedHome.clear();
		if (!hiddenByUs.isEmpty())
		{
			for (Widget widget : hiddenByUs)
			{
				try
				{
					widget.setHidden(false);
					widget.revalidate();
				}
				catch (RuntimeException ignored)
				{
					// destroyed by the client's own rebuild
				}
			}
			hiddenByUs.clear();
		}
		if (!show || sections.isEmpty())
		{
			if (itemContainer != null)
			{
				itemContainer.revalidate();
			}
			return;
		}
		Widget container = itemContainer;
		if (container == null)
		{
			return;
		}

		// The stale-pool detection that used to live here is GONE: it only
		// existed because we reused widgets across passes and the bank's
		// rebuild could drop them out from under us. Building fresh every
		// pass makes the whole question moot.
		java.util.Set<Widget> liveChildren = new java.util.HashSet<>();
		for (Widget child : container.getDynamicChildren())
		{
			if (child != null)
			{
				liveChildren.add(child);
			}
		}

		// Index the REAL bank item widgets by their item NAME — including
		// currently hidden ones (items on other tabs). Owned items are laid
		// out by MOVING these into our sections, so their withdraw menu
		// keeps working; only items you don't have are drawn as ghosts.
		// Name (not icon id) is the join key because the guide's names run
		// through the alias chain — "gp" must find the "Coins" stack, whose
		// id never matches the coin ICON id.
		Map<String, Widget> nativeByName = new LinkedHashMap<>();
		for (Widget child : container.getDynamicChildren())
		{
			if (child.getItemId() > 0 && child.getItemQuantity() > 0)
			{
				String name = itemManager.getItemComposition(itemManager.canonicalize(child.getItemId()))
					.getName().toLowerCase(java.util.Locale.ROOT);
				nativeByName.putIfAbsent(name, child);
			}
		}
		// How many real bank items this pass could see — the not-ready guard
		// above compares against it, so "0 now, plenty last time" reads as
		// a half-built container rather than an empty bank.
		lastNativeCount = nativeByName.size();
		int populated = countPopulatedItems(container);
		int inContainer = bankContainerItems();
		// COUNTING both sides and comparing does NOT work: a healthy bank
		// runs ~30 stacks ahead of its populated widgets (302/330 on a
		// freshly opened, fully working filter), so "populated < container"
		// is the normal state and firing a rebuild on it fires constantly.
		// The condition that actually matters is PER ITEM and narrow: we
		// drew a ghost for something the bank container really holds, so
		// there was no widget to move and the player cannot click it.
		java.util.Set<String> containerNames = bankContainerNames();
		lastPassStale = false;
		java.util.Set<Widget> kept = new java.util.HashSet<>();
		// Per-item branch record, logged when it CHANGES: "name=moved" (the
		// real bank widget), "=ghost" (our drawn copy), "=skip" (no icon id,
		// so the slot collapses), "!" = still short. Two blind fixes went
		// past this bug; the log names the item and the branch now.
		List<String> trace = new java.util.ArrayList<>();

		int y = 10;

		int textsUsed = 0;
		int iconsUsed = 0;
		for (Section section : sections)
		{
			if (section.items.isEmpty())
			{
				continue;
			}
			// Full step text, word-wrapped — a cut-off "Buy 3 buckets and 1
			// bucket pack from the gene..." leaves the player guessing.
			for (String line : wrapTitle(section.title))
			{
				Widget header = create(container, WidgetType.TEXT);
				textsUsed++;
				header.setText(line);
				header.setTextColor(HEADER_COLOR);
				header.setFontId(FontID.PLAIN_11);
				header.setTextShadowed(true);
				header.setOriginalX(FIRST_COLUMN_X);
				header.setOriginalY(y);
				header.setOriginalWidth(380);
				header.setOriginalHeight(14);
				header.setHidden(false);
				header.revalidate();
				y += 15;
			}
			y += 2;

			int column = 0;
			boolean anyIcon = false;
			for (Map.Entry<String, Integer> entry : section.items.entrySet())
			{
				int itemId = itemTracker.iconIdFor(entry.getKey());
				if (itemId <= 0)
				{
					// SKIPPED entirely — no icon, no count, and no column
					// taken, so every later item slides up a slot. If this
					// ever flips mid-session it IS the "icons move and go
					// invisible" report; the trace below names it.
					trace.add(entry.getKey() + "=skip");
					continue; // untradeable/unknown name: no icon to show
				}
				int need = entry.getValue();
				// Carried count for anything you're meant to WITHDRAW — the
				// line goes green as items land in your inventory and red
				// again if you bank them back. Unstackable gathers (130
				// planks) still count the bank; holding them all at once
				// was never the goal.
				int have = itemTracker.bankCountable(entry.getKey(), need)
					? itemTracker.countOf(entry.getKey())
					: itemTracker.carriedCountOf(entry.getKey());
				boolean met = have >= need;
				int x = FIRST_COLUMN_X + column * COLUMN_SPACING;

				// Banked? MOVE the real widget here — it stays clickable
				// (Withdraw-1/5/10/X/All), even for items from other tabs.
				// A section further down needing the same item falls back
				// to a ghost copy; the real one can only sit in one place.
				Widget banked = null;
				for (String alias : ItemTracker.aliases(entry.getKey()))
				{
					banked = nativeByName.get(alias);
					if (banked != null)
					{
						break;
					}
				}
				if (banked == null)
				{
					// The alias map is exact names only — "axe" must still
					// find YOUR axe whatever its tier, and "beads" any bead
					// colour. Full matching stack (substitutes, families,
					// canonical drift), first bank-order hit wins.
					for (Map.Entry<String, Widget> nativeEntry : nativeByName.entrySet())
					{
						if (!kept.contains(nativeEntry.getValue())
							&& ItemTracker.nameMatchesGoal(nativeEntry.getKey(), entry.getKey()))
						{
							banked = nativeEntry.getValue();
							break;
						}
					}
				}
				// You cannot MOVE the bank widget of an item you own none of.
				// The loose fallback above (families, canonical drift) scans
				// every bank item and takes the first fuzzy hit, then CLAIMS
				// it via `kept` — so "plague sample", owned 0, was stealing a
				// real stack's widget from the item that needed it. Bank child
				// order changes on every withdrawal, so a different item got
				// robbed each pass: that is the shuffling-and-vanishing icons.
				// Owning none means ghost, always.
				if (banked != null && itemTracker.countOf(entry.getKey()) <= 0)
				{
					banked = null;
				}
				trace.add(entry.getKey()
					+ (banked != null && !kept.contains(banked) ? "=moved" : "=ghost")
					+ (met ? "" : "!"));
				if (banked != null && !kept.contains(banked))
				{
					kept.add(banked);
					movedWidgets.add(banked);
					// Remember where the bank had it, so turning the filter
					// off can put it back.
					movedHome.putIfAbsent(banked,
						new int[]{banked.getOriginalX(), banked.getOriginalY()});
					banked.setOriginalX(x);
					banked.setOriginalY(y);
					// The native stack number draws over the icon's top —
					// cramped next to our have/need line, so hide it (the
					// line already shows how many you own). Display only;
					// the withdraw menu is untouched. The next bank build
					// resets the mode, and so does this pass.
					banked.setItemQuantityMode(0);
					banked.setHidden(false);
					banked.revalidate();
				}
				else
				{
					// Ghost for something the bank REALLY holds = the deposit
					// symptom: the item is back in the bank but the client
					// has not given it a widget, so it renders unclickable
					// with no tooltip. This — not a count comparison — is
					// what justifies prodding the client into a rebuild.
					if (inBankContainer(entry.getKey(), containerNames))
					{
						lastPassStale = true;
					}
					Widget icon = create(container, WidgetType.GRAPHIC);
					iconsUsed++;
					icon.setItemId(itemId);
					icon.setItemQuantity(need);
					icon.setItemQuantityMode(0); // the have/need line says it all
					icon.setOriginalX(x);
					icon.setOriginalY(y);
					icon.setOriginalWidth(36);
					icon.setOriginalHeight(32);
					icon.setOpacity(met ? 0 : 120); // ghosted while still missing
					icon.setName("<col=ff9040>" + entry.getKey() + "</col>");
					icon.setHidden(false);
					icon.revalidate();
				}

				// Quest Helper-style count under the icon: "have/need".
				Widget count = create(container, WidgetType.TEXT);
				textsUsed++;
				count.setText(compact(have) + "/" + compact(need));
				count.setTextColor(met ? COUNT_MET_COLOR : COUNT_SHORT_COLOR);
				count.setFontId(FontID.PLAIN_11);
				count.setTextShadowed(true);
				count.setOriginalX(x - 4);
				count.setOriginalY(y + 33);
				count.setOriginalWidth(COLUMN_SPACING - 2);
				count.setOriginalHeight(12);
				count.setHidden(false);
				count.revalidate();

				anyIcon = true;
				if (++column == COLUMNS)
				{
					column = 0;
					y += ROW_SPACING;
				}
			}
			if (column > 0 || !anyIcon)
			{
				y += column > 0 ? ROW_SPACING : 0;
			}
			y += 6; // breathing room between sections
		}

		// Self-diagnosis for the vanishing-icon reports: one line per pass
		// whenever the composition changes — if icons vanish WITHOUT a new
		// line, the bank redrew without this pass running at all.
		// "native items" counts the bank WIDGETS carrying an item; "in
		// container" counts the bank ITEM CONTAINER. They should agree.
		// When they don't, the widgets are stale — which is the whole
		// deposit question: an item that is in the container but has no
		// populated widget cannot be moved, so it can only be drawn as an
		// unclickable ghost.
		String shape = sections.size() + " sections, " + kept.size() + " moved, "
			+ iconsUsed + " ghosts, " + textsUsed + " texts, "
			+ liveChildren.size() + " container children, "
			+ lastNativeCount + " native items, "
			+ populated + "/" + inContainer + " widgets populated, via " + trigger
			+ (lastPassStale ? " STALE (a ghost the bank really holds)" : "");
		if (!shape.equals(lastShape))
		{
			lastShape = shape;
			log.info("bank filter pass: {}", shape);
		}
		String traceLine = String.join(" ", trace);
		if (!traceLine.equals(lastTrace))
		{
			lastTrace = traceLine;
			log.info("bank filter items: {}", traceLine);
		}

		// NOW take the rest of the container over: hide everything the
		// native layout drew that we didn't move into a section — leftover
		// items and tab separators. Whatever bank tab is selected, the
		// filter view looks the same. The next build redraws the native
		// children, and this pass runs again after it, so nothing is
		// permanently lost.
		java.util.Set<Widget> ours = addedWidgets;
		for (Widget child : container.getDynamicChildren())
		{
			if (!ours.contains(child) && !kept.contains(child) && !child.isHidden())
			{
				child.setHidden(true);
				hiddenByUs.add(child); // so the filter can be undone
			}
		}

		// Fit the scroll area to OUR content (grow or shrink — a 946-item
		// tab leaves a huge stale scroll range behind). DEFERRED: update()
		// runs from onScriptPostFired — still inside the bank build
		// script's interpreter — and calling client.runScript from there
		// re-enters the script engine and hard-freezes the client (both
		// observed freezes: the filter button, and typing "bruh" in the
		// search). One tick later the stack is clean.
		int newScrollHeight = y + 8;
		if (container.getScrollHeight() != newScrollHeight)
		{
			clientThread.invokeLater(() -> {
				Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
				if (items == null || items.getScrollHeight() == newScrollHeight)
				{
					return; // bank closed or already right in the meantime
				}
				items.setScrollHeight(newScrollHeight);
				client.runScript(ScriptID.UPDATE_SCROLLBAR,
					InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS,
					items.getScrollY());
				items.revalidateScroll();
			});
		}
	}

	/**
	 * Does the bank container hold this goal's item? EXACT aliases only.
	 *
	 * The fuzzy nameMatchesGoal fallback is deliberately not used here: it
	 * is the same over-matching that once let "plague sample", owned none
	 * of, claim another item's bank widget, and using it made this flag
	 * read true on every pass including healthy ones. A diagnostic that is
	 * always on says nothing. Family names ("axe", "beads") will not report
	 * — an acceptable blind spot for a signal whose job is to be trusted
	 * when it does fire.
	 */
	private boolean inBankContainer(String goalName, java.util.Set<String> containerNames)
	{
		for (String alias : ItemTracker.aliases(goalName))
		{
			if (containerNames.contains(alias))
			{
				return true;
			}
		}
		return false;
	}

	/** Chars per header line at PLAIN_11 across the item area's width. */
	private static final int HEADER_WRAP_CHARS = 52;
	private static final int HEADER_MAX_LINES = 3;

	/** Greedy word-wrap; the (rare) overflow past 3 lines gets "...". */
	private static java.util.List<String> wrapTitle(String title)
	{
		java.util.List<String> lines = new ArrayList<>();
		String rest = title.trim();
		while (!rest.isEmpty() && lines.size() < HEADER_MAX_LINES)
		{
			if (rest.length() <= HEADER_WRAP_CHARS)
			{
				lines.add(rest);
				return lines;
			}
			int cut = rest.lastIndexOf(' ', HEADER_WRAP_CHARS);
			if (cut <= 0)
			{
				cut = HEADER_WRAP_CHARS; // one giant word; hard-split it
			}
			if (lines.size() == HEADER_MAX_LINES - 1)
			{
				lines.add(rest.substring(0, Math.min(rest.length(), HEADER_WRAP_CHARS - 3)) + "...");
				return lines;
			}
			lines.add(rest.substring(0, cut).trim());
			rest = rest.substring(cut).trim();
		}
		return lines;
	}

	/** 25321 -> "25.3k": the counts must fit under a 36px icon. */
	private static String compact(int n)
	{
		if (n < 10_000)
		{
			return Integer.toString(n);
		}
		if (n < 1_000_000)
		{
			return (n / 100) / 10.0 + "k";
		}
		return (n / 100_000) / 10.0 + "m";
	}

	/** Reuse the pool's n-th widget, or create it on first need. */
	/**
	 * A FRESH child every pass — Quest Helper's lifecycle, and the answer
	 * to the icons that kept blanking. The old version reused pooled
	 * widgets by index, so each one carried whatever the previous pass had
	 * set on it: opacity above all. A slot that held a missing item
	 * (opacity 120) and was then reused for an owned one relied on
	 * setOpacity(0) restoring it, and in practice the icon simply went
	 * blank. QH never re-styles a used widget; it throws them away and
	 * builds again, which is why its bank tab is stable.
	 */
	private Widget create(Widget container, int type)
	{
		Widget widget = container.createChild(-1, type);
		addedWidgets.add(widget);
		return widget;
	}

	/**
	 * Drop last pass's widgets before building again (QH's
	 * removeAddedWidgets). Only the TRAILING run that is entirely ours is
	 * truncated — QH truncates to a child count captured once, which would
	 * delete real bank slots for us if the container ever grew.
	 */
	private void removeAddedWidgets(Widget container)
	{
		if (addedWidgets.isEmpty())
		{
			return;
		}
		Widget[] children = container.getChildren();
		if (children != null)
		{
			int keep = children.length;
			while (keep > 0 && addedWidgets.contains(children[keep - 1]))
			{
				keep--;
			}
			if (keep < children.length)
			{
				container.setChildren(java.util.Arrays.copyOf(children, keep));
				container.revalidate();
			}
		}
		// Anything of ours the bank's own rebuild already dropped, or that
		// isn't in the trailing run, just gets hidden.
		for (Widget widget : addedWidgets)
		{
			try
			{
				widget.setHidden(true);
			}
			catch (RuntimeException ignored)
			{
				// already destroyed by the client's rebuild
			}
		}
		addedWidgets.clear();
	}

	/** The bank interface was rebuilt from scratch: our widgets are gone. */
	public void invalidate()
	{
		addedWidgets.clear();
		// The client rebuilt these too — the recorded positions and hidden
		// flags belong to widgets that no longer exist.
		movedWidgets.clear();
		movedHome.clear();
		hiddenByUs.clear();
	}
}

package com.ironscape;

import java.io.InputStream;

/**
 * Where the plugin's DATA files come from: the copy bundled in the jar.
 *
 * <p>This class used to support a configurable "data folder" that overrode
 * the bundled files, so a data-only correction could be made in a checkout
 * and picked up with {@code ::ironreload} instead of a rebuild. Plugin Hub
 * review rejected it on 2026-09-02 — reading from a directory the user
 * names is outside the plugin's own subdirectory of {@code .runelite}, and
 * the rule there is that all file I/O stays within it. The feature is gone
 * rather than narrowed, which is what the reviewer asked for.
 *
 * <p>The class is kept as the single door every bundled data read goes
 * through, so if that rule ever changes there is one place to change, and
 * so a reader can see at a glance that data comes from the jar and nowhere
 * else. Files the plugin WRITES (captured pins, local places, the guide
 * manifest, bank snapshots, problem reports) live in
 * {@code ~/.runelite/ironscape/} and are unaffected.
 */
public final class DataFiles
{
	private DataFiles()
	{
	}

	/**
	 * The named data file from the jar, resolved against {@code anchor}'s
	 * package the way {@link Class#getResourceAsStream} does. Null when
	 * there is no such resource, which callers already treat as "this
	 * corpus is absent".
	 */
	public static InputStream open(Class<?> anchor, String name)
	{
		return anchor.getResourceAsStream(name);
	}
}

package com.ironscape.guide;

import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * One actionable step of the guide — the unit the player checks off.
 */
@Value
public class GuideStep
{
	/**
	 * Stable identifier: a short hash of the step's own text (see
	 * GuideLoader#stepId). Progress and annotations are keyed by this, so
	 * upstream inserting or reordering steps does NOT invalidate them —
	 * only editing this step's text does.
	 */
	String id;

	/** 0-based position of the chapter/section/step, for display and sorting. */
	int chapterIndex;
	int sectionIndex;
	/** Position within the section. */
	int stepIndex;
	/** Position across the whole guide (0 .. total-1), for the progress bar. */
	int globalIndex;

	/** The full step text with formatting stripped — used for search and hashing. */
	String plainText;

	/** The step text as styled runs, for rendering. */
	List<TextRun> content;

	/**
	 * The step broken into tickable actions: its sentences, then its nested
	 * bullets. Never empty — a one-sentence step has exactly one SubStep.
	 */
	List<SubStep> subSteps;

	/** Indented sub-bullets (gear lists, side notes). Often empty. */
	List<NestedBlock> nestedContent;

	/** Extra trailing paragraphs some steps have, one list of runs each. Usually empty. */
	List<List<TextRun>> additionalContent;

	/**
	 * Upstream per-step info: gp_stack, items_needed, total_time,
	 * skills_quests_met. Values are free-form prose.
	 */
	Map<String, String> metadata;
}

package com.ironscape.guide;

import java.util.List;
import lombok.Value;

/** One of the guide's three chapters. */
@Value
public class GuideChapter
{
	String title;
	List<GuideSection> sections;
	/** End-of-chapter notes (expected stats etc.), one list of runs per footnote. */
	List<List<TextRun>> footnotes;
}

package com.ironscape.guide;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Parses bundled guide JSON (produced by tools/scrape-oziris.mjs) into
 * our internal model. This is the ONLY class that knows the file format —
 * if the shape ever changes, this file is the only one to fix.
 *
 * The format tolerates word-processor noise (fontSize, fontFamily); we
 * keep the formatting that matters for reading (bold, color, links) and
 * drop the rest.
 */
@Singleton // one shared instance; guides are immutable so this is safe
public class GuideLoader
{
	private final Gson gson;

	/**
	 * RuneLite provides a shared Gson instance for plugins to inject —
	 * preferred over new Gson() so settings are consistent client-wide.
	 */
	@Inject
	public GuideLoader(Gson gson)
	{
		this.gson = gson;
	}

	/** Loads a bundled guide variant. Takes ~100ms for the 1MB file. */
	public Guide load(GuideVariant variant) throws IOException
	{
		// The JSON files live in src/main/resources under this class's
		// package, so this resolves relative to GuideLoader.class.
		try (InputStream in = com.ironscape.DataFiles.open(GuideLoader.class, variant.getResourceName()))
		{
			if (in == null)
			{
				throw new IOException("Bundled guide data missing: " + variant.getResourceName());
			}
			return parse(variant, new InputStreamReader(in, StandardCharsets.UTF_8));
		}
	}

	/** Parses guide JSON from any reader (bundled file now; downloaded refresh later). */
	public Guide parse(GuideVariant variant, Reader reader)
	{
		RawGuide raw = gson.fromJson(reader, RawGuide.class);

		List<GuideChapter> chapters = new ArrayList<>();
		List<GuideStep> allSteps = new ArrayList<>();
		Map<String, GuideStep> byId = new LinkedHashMap<>();
		// Tracks how often each hash has been seen, to disambiguate the
		// (currently zero, but theoretically possible) case of two steps
		// with identical text.
		Map<String, Integer> idCounts = new HashMap<>();

		for (int ci = 0; ci < raw.chapters.size(); ci++)
		{
			RawChapter rawChapter = raw.chapters.get(ci);
			List<GuideSection> sections = new ArrayList<>();

			for (int si = 0; si < rawChapter.sections.size(); si++)
			{
				RawSection rawSection = rawChapter.sections.get(si);
				List<GuideStep> steps = new ArrayList<>();

				for (int ti = 0; ti < rawSection.steps.size(); ti++)
				{
					RawStep rawStep = rawSection.steps.get(ti);
					List<TextRun> content = convertRuns(rawStep.content);
					String plainText = plainText(content);

					String id = uniqueId(stepId(plainText), idCounts);
					List<NestedBlock> nested = convertNested(rawStep.nestedContent);

					GuideStep step = new GuideStep(
						id,
						ci, si, ti, allSteps.size(),
						plainText,
						content,
						buildSubSteps(id, content, nested, variant.isAtomicSteps()),
						nested,
						convertParagraphs(rawStep.additionalContent),
						rawStep.metadata == null
							? Collections.emptyMap()
							: Collections.unmodifiableMap(rawStep.metadata));

					steps.add(step);
					allSteps.add(step);
					byId.put(id, step);
				}

				sections.add(new GuideSection(rawSection.title, Collections.unmodifiableList(steps)));
			}

			chapters.add(new GuideChapter(
				rawChapter.title,
				Collections.unmodifiableList(sections),
				convertFootnotes(rawChapter.footnotes)));
		}

		return new Guide(
			variant,
			raw.updatedOn,
			raw.title,
			Collections.unmodifiableList(chapters),
			Collections.unmodifiableList(allSteps),
			Collections.unmodifiableMap(byId));
	}

	/**
	 * A step's id is the first 10 hex chars of the SHA-256 of its own text
	 * (whitespace-collapsed, lowercased). Content-based rather than
	 * positional on purpose: when upstream inserts or reorders steps,
	 * every untouched step keeps its id, so saved progress and annotations
	 * survive. Only a step whose text was edited gets a new id.
	 */
	static String stepId(String plainText)
	{
		String normalized = plainText.replaceAll("\\s+", " ").trim().toLowerCase(Locale.ROOT);
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(normalized.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder();
			for (int i = 0; i < 5; i++) // 5 bytes = 10 hex chars
			{
				hex.append(String.format("%02x", hash[i]));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			// Every JVM is required to ship SHA-256; this cannot happen.
			throw new IllegalStateException(e);
		}
	}

	/**
	 * One tickable sub-step per sentence of the main paragraph, then one
	 * per nested bullet. Falls back to a single sub-step covering the whole
	 * step if splitting somehow yields nothing.
	 *
	 * Atomic-step guides (see GuideVariant#atomicSteps) skip the splitter:
	 * the whole step is ONE action by construction, so it gets exactly one
	 * sub-step and the panel mirrors the source guide's own step list.
	 */
	private static List<SubStep> buildSubSteps(String parentId, List<TextRun> content,
		List<NestedBlock> nested, boolean atomicSteps)
	{
		List<SubStep> subs = new ArrayList<>();
		if (atomicSteps)
		{
			addSubStep(subs, parentId, 0, content);
			return Collections.unmodifiableList(subs);
		}
		for (List<TextRun> sentence : SentenceSplitter.split(content))
		{
			addSubStep(subs, parentId, 0, sentence);
		}
		for (NestedBlock block : nested)
		{
			addSubStep(subs, parentId, block.getLevel(), block.getContent());
		}
		if (subs.isEmpty())
		{
			addSubStep(subs, parentId, 0, content);
		}
		return Collections.unmodifiableList(subs);
	}

	private static void addSubStep(List<SubStep> subs, String parentId, int indentLevel, List<TextRun> runs)
	{
		if (runs.isEmpty())
		{
			return;
		}
		String plain = plainText(runs);
		if (plain.trim().isEmpty())
		{
			return;
		}
		subs.add(new SubStep(
			parentId + ":" + subs.size(),
			subs.size(),
			indentLevel,
			plain,
			Collections.unmodifiableList(runs)));
	}

	/** Appends -2, -3... if the same text (and so the same hash) appears twice. */
	private static String uniqueId(String id, Map<String, Integer> idCounts)
	{
		int seen = idCounts.merge(id, 1, Integer::sum);
		return seen == 1 ? id : id + "-" + seen;
	}

	private static List<TextRun> convertRuns(List<RawRun> rawRuns)
	{
		if (rawRuns == null)
		{
			return Collections.emptyList();
		}
		List<TextRun> runs = new ArrayList<>(rawRuns.size());
		for (RawRun r : rawRuns)
		{
			if (r.text == null || r.text.isEmpty())
			{
				continue;
			}
			RawFormatting f = r.formatting;
			runs.add(new TextRun(
				r.text,
				f != null && Boolean.TRUE.equals(f.bold),
				f != null && Boolean.TRUE.equals(f.italic),
				f != null && Boolean.TRUE.equals(f.underline),
				f != null && Boolean.TRUE.equals(f.strikethrough),
				f == null ? null : toHex(f.color),
				f == null ? null : f.url));
		}
		return Collections.unmodifiableList(runs);
	}

	private static List<NestedBlock> convertNested(List<RawNested> rawNested)
	{
		if (rawNested == null)
		{
			return Collections.emptyList();
		}
		List<NestedBlock> blocks = new ArrayList<>(rawNested.size());
		for (RawNested n : rawNested)
		{
			blocks.add(new NestedBlock(n.level, convertRuns(n.content)));
		}
		return Collections.unmodifiableList(blocks);
	}

	private static List<List<TextRun>> convertParagraphs(List<List<RawRun>> rawParagraphs)
	{
		if (rawParagraphs == null)
		{
			return Collections.emptyList();
		}
		List<List<TextRun>> paragraphs = new ArrayList<>(rawParagraphs.size());
		for (List<RawRun> p : rawParagraphs)
		{
			paragraphs.add(convertRuns(p));
		}
		return Collections.unmodifiableList(paragraphs);
	}

	private static List<List<TextRun>> convertFootnotes(List<RawFootnote> rawFootnotes)
	{
		if (rawFootnotes == null)
		{
			return Collections.emptyList();
		}
		List<List<TextRun>> footnotes = new ArrayList<>(rawFootnotes.size());
		for (RawFootnote fn : rawFootnotes)
		{
			footnotes.add(convertRuns(fn.content));
		}
		return Collections.unmodifiableList(footnotes);
	}

	/** Upstream colors are float r/g/b in 0..1; the panel wants "#rrggbb". */
	private static String toHex(RawColor color)
	{
		if (color == null)
		{
			return null;
		}
		return String.format("#%02x%02x%02x",
			Math.round(color.r * 255), Math.round(color.g * 255), Math.round(color.b * 255));
	}

	private static String plainText(List<TextRun> runs)
	{
		StringBuilder sb = new StringBuilder();
		for (TextRun run : runs)
		{
			sb.append(run.getText());
		}
		return sb.toString();
	}

	// ------------------------------------------------------------------
	// The classes below mirror the upstream JSON exactly. Gson fills them
	// by matching field names to JSON keys. They never leave this file.
	// ------------------------------------------------------------------

	private static class RawGuide
	{
		String updatedOn;
		String title;
		List<RawChapter> chapters;
	}

	private static class RawChapter
	{
		String title;
		List<RawSection> sections;
		List<RawFootnote> footnotes;
		// upstream also has titleFormatted; the plain title is enough for us
	}

	private static class RawSection
	{
		String title;
		List<RawStep> steps;
	}

	private static class RawStep
	{
		List<RawRun> content;
		List<RawNested> nestedContent;
		// a list of paragraphs, each paragraph being a list of runs
		List<List<RawRun>> additionalContent;
		Map<String, String> metadata;
	}

	private static class RawNested
	{
		int level;
		List<RawRun> content;
	}

	private static class RawFootnote
	{
		List<RawRun> content;
		// upstream also has "type", always "chapter_footnote" so far
	}

	private static class RawRun
	{
		String text;
		RawFormatting formatting;
	}

	private static class RawFormatting
	{
		Boolean bold;
		Boolean italic;
		Boolean underline;
		Boolean strikethrough;
		String url;
		RawColor color;
		// fontSize, fontFamily, isLink also exist upstream; not needed
	}

	private static class RawColor
	{
		float r;
		float g;
		float b;
	}
}

