package com.ironscape.guide;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Splits a step's styled text into individual actions, preserving
 * formatting runs across the cuts. Used to turn one prose step into
 * tickable sub-steps.
 *
 * Two passes:
 *  1. sentences — cut after . ! ? when followed by whitespace and a
 *     capital/digit/bracket, and at newlines;
 *  2. clauses — cut sentences at ", " and "; ", because the guide writes
 *     action lists that way ("Grab a knife, 2 buckets, cabbage"). Commas
 *     inside parentheses do NOT split, so "(hop once)" stays attached.
 *     A subordinate fragment ("While visiting Jennifer, ...") is not an
 *     action on its own — it stays glued to the clause it modifies
 *     instead of becoming its own tickbox.
 *
 * Heuristic, not perfect: an abbreviation before a number ("incl. 401")
 * can over-split — the cost is only cosmetic granularity, so we accept it.
 */
final class SentenceSplitter
{
	private static final Pattern SENTENCE_BOUNDARY =
		Pattern.compile("(?<=[.!?])\\s+(?=[\"(A-Z0-9])|\\n+");

	/**
	 * A comma segment starting like this is a subordinate fragment, not a
	 * standalone action: "While visiting Jennifer", "if you have spare
	 * gp", "once inside". It needs the neighbouring clause to mean
	 * anything, so the comma next to it must not cut. Optional leading
	 * connective ("and while...", "then once...") is looked through.
	 */
	private static final Pattern SUBORDINATE_OPENER = Pattern.compile(
		"(?:(?:and|then|or|but|so)\\s+)?(?:while|whilst|when|whenever|once|after|before|if|unless|until)\\b.*",
		Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

	/**
	 * Fragments shorter than this (or with no letters/digits) merge into
	 * the previous sentence. Two, not more: "saw" and "GP" are real items
	 * that deserve their own row.
	 */
	private static final int MIN_FRAGMENT_LENGTH = 2;

	private SentenceSplitter()
	{
	}

	static List<List<TextRun>> split(List<TextRun> runs)
	{
		StringBuilder sb = new StringBuilder();
		for (TextRun run : runs)
		{
			sb.append(run.getText());
		}
		String plain = sb.toString();

		List<int[]> ranges = new ArrayList<>();
		Matcher matcher = SENTENCE_BOUNDARY.matcher(plain);
		int previousEnd = 0;
		while (matcher.find())
		{
			addClauses(ranges, plain, previousEnd, matcher.start());
			previousEnd = matcher.end();
		}
		addClauses(ranges, plain, previousEnd, plain.length());

		List<List<TextRun>> sentences = new ArrayList<>(ranges.size());
		for (int[] range : ranges)
		{
			sentences.add(slice(runs, range[0], range[1]));
		}
		return sentences;
	}

	/**
	 * Splits one sentence [from, to) into clauses at top-level ", " and
	 * "; " (never inside parentheses, never without following whitespace —
	 * which also protects numbers like "1,500").
	 */
	private static void addClauses(List<int[]> ranges, String plain, int from, int to)
	{
		// Pass 1: every candidate comma/semicolon position at paren depth 0.
		List<Integer> boundaries = new ArrayList<>();
		int parenDepth = 0;
		for (int i = from; i < to; i++)
		{
			char c = plain.charAt(i);
			if (c == '(')
			{
				parenDepth++;
			}
			else if (c == ')')
			{
				parenDepth = Math.max(0, parenDepth - 1);
			}
			else if (parenDepth == 0 && (c == ',' || c == ';')
				&& i + 1 < to && Character.isWhitespace(plain.charAt(i + 1)))
			{
				boundaries.add(i);
			}
		}

		// Pass 2: a boundary next to a subordinate SEGMENT does not cut.
		// A subordinate glues to the clause it introduces ("While visiting
		// Jennifer, buy shears" — no cut after "Jennifer"); one that ends
		// the sentence instead glues backward ("buy shears, while visiting
		// Jennifer" — no cut before "while"). Segments, not accumulated
		// clauses: "After the quest, if you have gp, buy X" judges "if you
		// have gp" at the second comma.
		int clauseStart = from;
		for (int k = 0; k < boundaries.size(); k++)
		{
			int cut = boundaries.get(k);
			int segmentBefore = k == 0 ? from : boundaries.get(k - 1) + 1;
			int segmentAfter = k + 1 < boundaries.size() ? boundaries.get(k + 1) : to;
			boolean glueForward = isSubordinate(plain, segmentBefore, cut);
			boolean glueBackward = k == boundaries.size() - 1
				&& isSubordinate(plain, cut + 1, segmentAfter);
			if (!glueForward && !glueBackward)
			{
				addRange(ranges, plain, clauseStart, cut); // the , or ; itself is dropped
				clauseStart = cut + 1;
			}
		}
		addRange(ranges, plain, clauseStart, to);
	}

	/** Does [from, to), ignoring leading whitespace, open with a subordinating conjunction? */
	private static boolean isSubordinate(String plain, int from, int to)
	{
		while (from < to && Character.isWhitespace(plain.charAt(from)))
		{
			from++;
		}
		return SUBORDINATE_OPENER.matcher(plain.substring(from, to)).matches();
	}

	/** Adds [from, to) trimmed; merges trivial fragments (") ." etc.) into the previous range. */
	private static void addRange(List<int[]> ranges, String plain, int from, int to)
	{
		while (from < to && Character.isWhitespace(plain.charAt(from)))
		{
			from++;
		}
		while (to > from && Character.isWhitespace(plain.charAt(to - 1)))
		{
			to--;
		}
		if (from >= to)
		{
			return;
		}

		String text = plain.substring(from, to);
		boolean substantial = text.length() >= MIN_FRAGMENT_LENGTH
			&& text.chars().anyMatch(Character::isLetterOrDigit);
		if (!substantial && !ranges.isEmpty())
		{
			ranges.get(ranges.size() - 1)[1] = to;
			return;
		}
		ranges.add(new int[]{from, to});
	}

	/** Cuts the run list down to the characters in [from, to), keeping each fragment's style. */
	private static List<TextRun> slice(List<TextRun> runs, int from, int to)
	{
		List<TextRun> out = new ArrayList<>();
		int position = 0;
		for (TextRun run : runs)
		{
			int start = position;
			int end = position + run.getText().length();
			position = end;

			int sliceStart = Math.max(from, start);
			int sliceEnd = Math.min(to, end);
			if (sliceStart >= sliceEnd)
			{
				continue;
			}
			out.add(new TextRun(
				run.getText().substring(sliceStart - start, sliceEnd - start),
				run.isBold(), run.isItalic(), run.isUnderline(), run.isStrikethrough(),
				run.getColorHex(), run.getUrl()));
		}
		return out;
	}
}

package com.ironscape.goals;

import com.ironscape.guide.Guide;
import com.ironscape.guide.GuideStep;
import com.ironscape.guide.SubStep;
import com.ironscape.guide.TextRun;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * Reads completion GOALS straight out of sub-step text, no annotations
 * needed:
 *
 *  - "Grab 110 logs", "buy 20 balls of wool"  -> item goal: auto-tick
 *    once you own that many (inventory + equipment + bank snapshot).
 *  - "Start Rune Mysteries" / "Complete Dragon Slayer" -> quest goal:
 *    auto-tick when the quest reaches that state (RuneLite's Quest API
 *    reads this for every quest).
 *
 * Deliberately conservative: item goals REQUIRE an explicit number —
 * "grab a knife" is ambiguous prose, "grab 5 logs" is a measurable goal.
 * Run once per guide load; the plugin checks the resulting lists against
 * live game state.
 */
public final class GoalDetector
{
	/**
	 * The number a "200k"/"2.4m" quantity stands for, or null when this is
	 * not a count at all.
	 *
	 * <p>The FRACTION is the point. Without it the digit group stopped dead
	 * at the decimal point and the match simply restarted after it, so
	 * "2.4m GP" was read as "4m GP" and the step asked for four million
	 * where the guide said two point four (owner, in play 2026-08-28). All
	 * 8 decimal quantities in the guide were wrong the same way, and they
	 * are not all money: "1.2k buckets of sand" asked for 2,000 and "6.2k
	 * maples" for 2,000.
	 *
	 * <p>A fraction with NO suffix is not a quantity of anything - you
	 * cannot gather 2.4 logs - so it is rejected rather than rounded, which
	 * also keeps version-like prose out of the goal list.
	 */
	private static String expandQuantity(String digits, String suffix)
	{
		String plain = digits.replace(",", "");
		boolean fractional = plain.indexOf(46) >= 0;
		if (suffix == null)
		{
			return fractional ? null : plain;
		}
		return new java.math.BigDecimal(plain)
			.multiply(java.math.BigDecimal.valueOf(
				"k".equalsIgnoreCase(suffix) ? 1_000L : 1_000_000L))
			.setScale(0, java.math.RoundingMode.HALF_UP).toPlainString();
	}

	/**
	 * "number + item" pairs — clause splitting turns
	 * "Buy 1250 nature runes, 700 law runes, 50 earth and 20 fire runes"
	 * into fragments where only the first has the verb; the rest start with
	 * their quantity and may chain more with "and".
	 */
	private static final Pattern QUANTITY_NAME = Pattern.compile(
		"(\\d[\\d,]*(?:\\.\\d+)?)([km])?\\s+([a-z][a-z'/ -]+)", Pattern.CASE_INSENSITIVE);

	/**
	 * "keep 3 bars" — an instruction about what to HOLD BACK from the step's
	 * own output, not something to go and acquire. Anchored to the end so it
	 * only vetoes a number that directly follows the word.
	 */
	private static final Pattern RETAIN_INSTRUCTION = Pattern.compile(
		"\\bkeep\\s+(?:the\\s+)?$", Pattern.CASE_INSENSITIVE);

	/**
	 * "Smelt the 5 silver" — what you smelt is CONSUMED, so it is the
	 * material, never the objective. Counting it finished the step the
	 * moment the ore was withdrawn, before any smelting happened (owner,
	 * 2026-08-14: "why would we auto tick when we withdraw 5 silver ore").
	 *
	 * <p>Both steps this matches guide-wide were wrong: the other is "Smelt
	 * 1 inv of gold", which was asking for 28 COINS. Neither can be fixed by
	 * counting the input better, so neither counts it.
	 */
	private static final Pattern CONSUMED_MATERIAL = Pattern.compile(
		"\\bsmelt(?:ing|ed)?\\s+(?:the\\s+)?$", Pattern.CASE_INSENSITIVE);

	/** Words that end an item name ("110 logs AND bank them" -> "logs",
	 *  "5 swamp tar AROUND the cave entrance" -> "swamp tar",
	 *  "130 planks NORTH of the Barb agility course" -> "planks"). */
	private static final Pattern NAME_TERMINATOR = Pattern.compile(
		"\\s+(?:and|from|at|in|to|for|so|until|then|with|on|off|per|as"
			+ "|around|near|along|inside|outside|behind|beside|under|by"
			+ "|north|south|east|west|northwest|northeast|southwest|southeast)\\b.*|[(.,].*");

	/** "air/mind runes" — two alternatives sharing a suffix word. */
	private static final Pattern COMPOUND_NAME = Pattern.compile(
		"([a-z]+)/([a-z]+)\\s+([a-z' ]+)");

	/**
	 * "get 100 compost and saltpetre" — a numbered goal's bare "and" tail
	 * (no number of its own) inherits the quantity: the guide's idiom
	 * means 100 of EACH. The middle char class can't cross digits or
	 * commas, so "5 cloth and 100 nails" list items keep their own counts.
	 */
	private static final Pattern INHERITED_AND_TAIL = Pattern.compile(
		"(\\d[\\d,]*(?:\\.\\d+)?)([km])?\\s+[a-z][a-z'/ -]*?\\s+and\\s+([a-z][a-z' -]+)",
		Pattern.CASE_INSENSITIVE);

	/** Tails that are prose, not a second item ("110 logs and bank them"). */
	private static final java.util.Set<String> AND_TAIL_STOP = java.util.Set.of(
		"them", "it", "they", "you", "your", "the", "a", "an", "then", "bank",
		"use", "make", "drop", "keep", "note", "go", "run", "walk", "head",
		"talk", "buy", "get", "grab", "take", "continue", "finish", "start",
		"do", "sell", "more", "some", "any", "all", "this", "that", "repeat",
		"deposit", "withdraw", "return", "put", "bring", "equip", "wear",
		"open", "click", "pick", "cut", "burn", "cook", "craft", "smith",
		"mine", "fish", "kill", "train",
		// first sweep's catches: verbs/adverbs the guide chains after "and"
		"firemake", "offer", "quickly", "for", "chin", "fletch", "alch",
		"string", "bury", "light", "plant", "superheat", "so", "if", "when");

	/** "inv of bronze bars", "inventories of gold ore" — 28 slots each. */
	private static final Pattern INV_OF = Pattern.compile(
		"^(?:inv|invs|inventory|inventories)\\s+of\\s+(.+)$");

	/** "1 PACK of eyes of newt" — the item is named "Eye of newt pack". */
	private static final Pattern PACK_OF = Pattern.compile("^packs?\\s+of\\s+(.+)$");

	/**
	 * Item names CONTAINING "and": the comma/and list-splitting terminator
	 * shreds them, so they're scanned whole before the pair scan runs.
	 */
