		// "Buy a Player-owned house" is a purchase, but not of an ITEM —
		// no POH exists in any inventory, so the goal could only sit red
		// forever. Caught by the unresolvable-goal audit.
		"player");

	/**
	 * An unnoted inventory holds 28 items. An item goal needing MORE than
	 * that ("pick up 130 planks") can never be satisfied by carried count
	 * alone — those goals count inventory + worn + bank instead, since
	 * banking batches is exactly how the gather is supposed to happen.
	 */
	public static final int CARRYABLE_LIMIT = 28;

	@Value
	public static class ItemGoal
	{
		GuideStep step;
		SubStep sub;
		String itemName;
		int quantity;
		/**
		 * True for "buy X from her shop" — a transaction, not a state.
		 * Already OWNING the item must not tick it; the plugin requires
		 * the carried count to INCREASE while the sub is current.
		 */
		boolean acquisition;
	}

	@Value
	public static class QuestGoal
	{
		GuideStep step;
		SubStep sub;
		Quest quest;
