		java.util.Map.entry("pickpocket", Skill.THIEVING),
		java.util.Map.entry("bury", Skill.PRAYER));

	/** "make/turn the logs INTO a plank" — completing means owning the product. */
	private static final Pattern INTO_PRODUCT = Pattern.compile(
		"\\b(?:make|turn|convert)\\b.*?\\binto\\s+(?:(?:a|an|some)\\s+)?([a-z][a-z'/ -]+)",
		Pattern.CASE_INSENSITIVE);

	/** Purchase verbs — see ItemGoal#acquisition. */
	private static final Pattern PURCHASE_VERB = Pattern.compile(
		"\\b(?:buy|purchase)\\b", Pattern.CASE_INSENSITIVE);

	/** "Make the hangover cure" — completing means holding the product. */
	private static final Pattern MAKE_PRODUCT = Pattern.compile(
		"\\bmake\\s+(?:(?:a|an|some|the)\\s+)?([a-z][a-z'/ -]+)",
		Pattern.CASE_INSENSITIVE);

	private GoalDetector()
	{
	}

	public static Goals detect(Guide guide)
	{
		List<ItemGoal> itemGoals = new ArrayList<>();
		List<QuestGoal> questGoals = new ArrayList<>();
		List<SkillActionGoal> actionGoals = new ArrayList<>();
		List<TravelGoal> travelGoals = new ArrayList<>();
		List<InteractionGoal> interactionGoals = new ArrayList<>();
		List<CountedSkillGoal> countedGoals = new ArrayList<>();
		List<MinigameTeleportGoal> minigameGoals = new ArrayList<>();
		List<SkillLevelGoal> levelGoals = new ArrayList<>();
		List<DepletionGoal> depletionGoals = new ArrayList<>();

		for (GuideStep step : guide.getAllSteps())
		{
			int stepQuestsBefore = questGoals.size();
			int stepItemsBefore = itemGoals.size();
			// True while we're inside a comma-list of items within this
			// step ("Grab a bucket of milk, raw sardine, doogle leaves…").
			boolean inItemList = false;
			// Whether that list was opened with a purchase verb — bare
			// continuations of "buy 5 X, 3 Y" are purchases too.
			boolean acquisitionList = false;
			for (SubStep sub : step.getSubSteps())
			{
				int itemsBefore = itemGoals.size();
				int questsBefore = questGoals.size();
				acquisitionList = detectItemGoal(step, sub, itemGoals, inItemList, acquisitionList);
				boolean producedItems = itemGoals.size() > itemsBefore;
				inItemList = producedItems;
				detectQuestGoal(step, sub, questGoals);
				// "burn them to level 50 firemaking" — a level target.
				List<SkillLevelGoal> subLevels = detectLevelGoals(step, sub);
				levelGoals.addAll(subLevels);
				// Item goals are stronger evidence than an action verb —
				// "chop 110 logs" waits for the logs, not the first swing.
				// A level target likewise beats "first xp drop ticks it".
				if (!producedItems && subLevels.isEmpty())
				{
					detectActionGoal(step, sub, actionGoals);
				}
				// "Give the letter to Romeo" — needs consumption, not just
				// arrival. Wins over travel/location semantics.
				String firstWord = sub.getPlainText().trim().toLowerCase(Locale.ROOT)
					.split("[^a-z]+", 2)[0];
				boolean interaction = !producedItems && questGoals.size() == questsBefore
					&& INTERACTION_FIRST_WORDS.contains(firstWord)
					&& !PRONOUN_OBJECT.matcher(sub.getPlainText().trim()).find();
				if (interaction)
				{
					interactionGoals.add(new InteractionGoal(step, sub));
				}

				// "Teleport using the chronicle" — completed by the position
				// jump, unless another goal already owns this sub.
				if (!producedItems && !interaction && questGoals.size() == questsBefore
					&& TRAVEL_WORDS.matcher(sub.getPlainText()).find())
				{
					travelGoals.add(new TravelGoal(step, sub));
				}

				// "make bookcases until out of planks" — done when the item
				// runs out, regardless of any level reached on the way.
				Matcher depletion = UNTIL_OUT_OF.matcher(sub.getPlainText());
				if (depletion.find())
				{
					String depleted = NAME_TERMINATOR.matcher(depletion.group(1))
						.replaceFirst("").trim().toLowerCase(Locale.ROOT);
					if (depleted.length() >= 3)
					{
						depletionGoals.add(new DepletionGoal(step, sub, depleted));
					}
				}

				// "Minigame teleport to X" — remember which minigame, so the
				// overlay can point at the Grouping UI while this sub is next.
				Matcher minigame = MINIGAME_TELEPORT.matcher(sub.getPlainText());
				if (minigame.find())
				{
					minigameGoals.add(new MinigameTeleportGoal(step, sub, minigame.group(1).trim()));
				}

				// "train construction (6 chairs, 1 rug...)" -> counted XP drops.
				// Not when a level target exists — "train fm to 50" counts
				// levels, not drops (and the 50 would poison the drop sum).
				Matcher train = TRAIN_SKILL.matcher(sub.getPlainText());
				if (!producedItems && subLevels.isEmpty() && train.find())
				{
					Skill skill = Skill.valueOf(train.group(1).toUpperCase(Locale.ROOT));
					int count = 0;
					Matcher quantities = Pattern.compile("\\b(\\d{1,3})\\b").matcher(sub.getPlainText());
					while (quantities.find())
					{
						count += Integer.parseInt(quantities.group(1));
					}
					// No numbers = no target: "train construction with your
					// planks" must not tick off the FIRST xp drop. Leave it
					// to an annotation or the manual checkbox.
					if (count > 0)
					{
						countedGoals.add(new CountedSkillGoal(step, sub, skill, count));
					}
				}
			}

			// NOTE-carried quantities: "Buy buckets of sand and soda ash"
			// with "Note: ...around 600 buckets of sand and 600 soda ash"
			// — the note holds the real target, so an unnumbered goal
			// (quantity 1) adopts the note's number for its name.
			if (!step.getAdditionalContent().isEmpty() && itemGoals.size() > stepItemsBefore)
			{
				StringBuilder noteText = new StringBuilder();
				for (List<TextRun> paragraph : step.getAdditionalContent())
				{
					for (TextRun run : paragraph)
					{
						noteText.append(run.getText());
					}
					noteText.append(' ');
				}
				String note = noteText.toString().toLowerCase(Locale.ROOT);
				for (int i = stepItemsBefore; i < itemGoals.size(); i++)
				{
					ItemGoal goal = itemGoals.get(i);
					if (goal.getQuantity() != 1)
					{
						continue;
					}
					Matcher noted = Pattern.compile(
						"(\\d[\\d,]*)(k?)\\s+(?:x\\s*)?(?:of\\s+)?"
							+ Pattern.quote(goal.getItemName())).matcher(note);
					if (noted.find())
					{
						long quantity = Long.parseLong(noted.group(1).replace(",", ""))
							* ("k".equalsIgnoreCase(noted.group(2)) ? 1000L : 1L);
						if (quantity > 1 && quantity <= 50_000_000)
						{
							itemGoals.set(i, new ItemGoal(goal.getStep(), goal.getSub(),
								goal.getItemName(), (int) quantity, goal.isAcquisition()));
						}
					}
				}
			}

			// The step's authored quest tag ("quest": "Alfred Grimhand's
			// Barcrawl") beats text matching when the prose abbreviates
			// ("Start Barcrawl miniquest"). Only when the text yielded no
			// quest goal, and never for "until <part>" checkpoint steps —
			// those complete via their varbit/varp annotation, and a
			// started-state goal would tick them the moment the quest began.
			if (questGoals.size() == stepQuestsBefore && !step.getSubSteps().isEmpty())
			{
				addMetadataQuestGoal(step, questGoals);
			}
		}
		return new Goals(itemGoals, questGoals, actionGoals, travelGoals, interactionGoals,
			countedGoals, minigameGoals, levelGoals, depletionGoals);
	}

	private static void addMetadataQuestGoal(GuideStep step, List<QuestGoal> out)
	{
		String name = step.getMetadata().get("quest");
		if (name == null)
		{
			return;
		}
		String text = step.getPlainText().toLowerCase(Locale.ROOT);
		if (text.contains("until") || text.contains("up to"))
		{
			return; // mid-quest checkpoint step; annotations own completion
		}
		// The tag also decorates PREP steps ("Make the hangover cure for
		// plague city quest") — quest state says nothing about those, and
		// questStatus does NOT separate them (the site tags prep steps with
		// a status too; see GoalDetectorTest). So a step still has to look
		// like it acts on the quest, by one of two tests:
		//
		//   a verb   "Do Desert Treasure", "Start Barcrawl miniquest"
		//   the NAME the step text is just the quest's name, give or take a
		//            trailing "quest" and a parenthetical aside
		//
		// The second is new. Without it, bare-name steps ("Cabin fever",
		// "Watchtower quest", "One small favour", "Rum deal (Req 42
		// slayer...)") got no quest goal and so had NO completion path at
		// all except arrival — itself gated on a kit the quest consumes, so
		// they could never auto-tick. The prep step fails both tests: its
		// text leads with its own action and only mentions the quest in a
		// trailing "for X quest".
		if (!Pattern.compile("\\b(?:start|begin|do|complete|finish|continue)\\b")
				.matcher(text).find()
			&& !textIsJustTheQuestName(text, name))
		{
			return;
		}
		String status = step.getMetadata().get("questStatus");
		Quest quest = questByName(name);
		if (quest != null)
		{
			out.add(new QuestGoal(step, step.getSubSteps().get(0), quest,
				"complete".equalsIgnoreCase(status)));
		}
	}

	/**
	 * Is the step's whole text just the quest's name? Compared against the
	 * guide's own TAG rather than the game's name, since the two disagree
	 * ("Forgettable Tale..." is tagged truncated), and either may be the
	 * shorter — so a prefix match either way counts.
	 */
	private static boolean textIsJustTheQuestName(String text, String tag)
	{
		String bare = text.replaceAll("\\([^)]*\\)", " ")          // "(Req 42 slayer...)"
			.replaceAll("\\b(?:mini)?quest\\b", " ")               // "Watchtower quest"
			.replaceAll("[^a-z0-9 ]", " ")
			.replaceAll("\\s+", " ").trim();
		String wanted = tag.toLowerCase(Locale.ROOT)
			.replaceAll("[^a-z0-9 ]", " ")
			.replaceAll("\\s+", " ").trim();
		if (bare.isEmpty() || wanted.isEmpty())
		{
			return false;
		}
		return bare.startsWith(wanted) || wanted.startsWith(bare);
	}

	/**
	 * The guide's quest tag -> the RuneLite Quest whose name the game uses.
	 *
	 * Hand-authored rather than fuzzy-matched, because the near-misses are
	 * genuinely ambiguous: "Desert Treasure" prefixes both "Desert Treasure
	 * I" and "Desert Treasure II - The Fallen Empire", and "Rag and Bone
	 * Man" prefixes I and II. Every entry below was checked against the
	 * step that carries the tag (build/quest-names.tsv dumps the enum).
	 */
	private static final java.util.Map<String, String> QUEST_NAME_ALIASES = java.util.Map.of(
		"vampire slayer", "Vampyre Slayer",                  // renamed in game
		"garden of tranquility", "Garden of Tranquillity",   // two Ls
		"hand in the sand", "The Hand in the Sand",          // leading article
		"desert treasure", "Desert Treasure I",              // guide predates the sequel
		"desert treasure ii", "Desert Treasure II - The Fallen Empire",
		"rag and bone man", "Rag and Bone Man I",            // guide's step is the first part
		"recipe for disaster (evil dave)", "Recipe for Disaster - Evil Dave");

	/** Exact name first, then the alias table. Null when nothing matches. */
	private static Quest questByName(String name)
	{
		String wanted = name.trim();
		String alias = QUEST_NAME_ALIASES.get(wanted.toLowerCase(Locale.ROOT));
		if (alias != null)
		{
			wanted = alias;
		}
		for (Quest quest : Quest.values())
		{
			if (quest.getName().equalsIgnoreCase(wanted))
			{
				return quest;
			}
		}
		return null;
	}

	/**
	 * Every "number + skill word" pair in the sub-step is a level target:
	 * "burn them to level 50 firemaking", "get 43 prayer", "until 70 range".
	 * Parentheticals are commentary and skipped, same as for items. If a
	 * skill appears twice the higher target wins.
	 */
	private static List<SkillLevelGoal> detectLevelGoals(GuideStep step, SubStep sub)
	{
		String text = sub.getPlainText().replaceAll("\\([^)]*\\)", " ");
		java.util.Map<Skill, Integer> targets = new java.util.LinkedHashMap<>();
		Matcher matcher = LEVEL_SKILL.matcher(text);
		while (matcher.find())
		{
			Skill skill = SKILL_BY_WORD.get(matcher.group(2).toLowerCase(Locale.ROOT));
			int level = Integer.parseInt(matcher.group(1));
			if (skill != null && level >= 2 && level <= 99)
			{
				targets.merge(skill, level, Math::max);
			}
		}
		// "(15 Smithing required)": requirement notes hide in the
		// parentheticals stripped above — scan the RAW text for them.
		Matcher required = REQUIRED_LEVEL.matcher(sub.getPlainText());
		while (required.find())
		{
			Skill skill = SKILL_BY_WORD.get(required.group(2).toLowerCase(Locale.ROOT));
			int level = Integer.parseInt(required.group(1));
			if (skill != null && level >= 2 && level <= 99)
			{
				targets.merge(skill, level, Math::max);
			}
		}

		// "9 Hunter and Slayer": the number distributes over BOTH skills —
		// the pair scan above only credits the first.
		Matcher shared = SHARED_LEVEL.matcher(text);
		while (shared.find())
		{
			Skill second = SKILL_BY_WORD.get(shared.group(3).toLowerCase(Locale.ROOT));
			int level = Integer.parseInt(shared.group(1));
			if (second != null
				&& SKILL_BY_WORD.containsKey(shared.group(2).toLowerCase(Locale.ROOT))
				&& level >= 2 && level <= 99)
			{
				targets.merge(second, level, Math::max);
			}
		}
		List<SkillLevelGoal> goals = new ArrayList<>(targets.size());
		targets.forEach((skill, level) -> goals.add(new SkillLevelGoal(step, sub, skill, level)));
		return goals;
	}

	/**
	 * Clause glue that can precede the real action verb: "and do a lap...",
	 * "then chop...". Skipped before the verb lookup.
	 */
	private static final java.util.Set<String> LEADING_CONNECTIVES = java.util.Set.of(
		"and", "then", "also", "now", "next", "finally", "optionally");

	/** "do a lap of the Shayzien agility course" -> an Agility XP drop. */
	private static final Pattern AGILITY_LAP = Pattern.compile(
		"\\blaps?\\b.*\\bagility course\\b", Pattern.CASE_INSENSITIVE);

	/** "9 Hunter and Slayer" — one number shared by two skill words. */
	private static final Pattern SHARED_LEVEL = Pattern.compile(
		"\\b(\\d{1,2})\\s+([a-z]+)\\s+and\\s+([a-z]+)", Pattern.CASE_INSENSITIVE);

	/**
	 * "(15 Smithing required)" — requirement notes live in parentheticals,
	 * which the main level scan strips as commentary. The word "required"
	 * makes this one safe to read.
	 */
	private static final Pattern REQUIRED_LEVEL = Pattern.compile(
		"\\b(\\d{1,2})\\s+([a-z]+)\\s+(?:required|req\\b)", Pattern.CASE_INSENSITIVE);

	private static final String RUNE_WORD =
		"fire|water|air|earth|mind|body|chaos|law|nature|cosmic|death|blood|soul|wrath|astral";

	/**
	 * "300 earth and water" — one number, two rune types: the pair scan
	 * credits only the first, so the second needs the same quantity.
	 * Rune words only; "3 buckets and 1 bucket pack" has its own numbers.
	 */
	private static final Pattern SHARED_RUNE_QUANTITY = Pattern.compile(
		"\\b(\\d[\\d,]*)\\s+(?:" + RUNE_WORD + ")s?(?:\\s+runes?)?\\s+and\\s+((?:" + RUNE_WORD + ")s?)\\b",
		Pattern.CASE_INSENSITIVE);

	/** "Chop down a dying tree" -> a Woodcutting XP drop completes it. */
	private static void detectActionGoal(GuideStep step, SubStep sub, List<SkillActionGoal> out)
	{
		String text = sub.getPlainText().trim().toLowerCase(Locale.ROOT);
		String[] words = text.split("[^a-z]+");
		int first = 0;
		while (first < words.length
			&& (words[first].isEmpty() || LEADING_CONNECTIVES.contains(words[first])))
		{
			first++;
		}
		Skill skill = first < words.length ? ACTION_VERB_SKILLS.get(words[first]) : null;
		if (skill == null && AGILITY_LAP.matcher(text).find())
		{
			skill = Skill.AGILITY;
		}
		if (skill != null)
		{
			out.add(new SkillActionGoal(step, sub, skill));
		}
	}

	/**
	 * "Kill 1 cow calf for meat" — the goal is the LOOT in your
	 * inventory (Quest Helper-style item requirement), never an "item"
	 * named after the NPC. Only mapped early-game meat drops; an
	 * unmapped kill stays a manual checkbox.
	 */
	private static final Pattern KILL_FOR_MEAT = Pattern.compile(
		"\\b(?:kill|safespot|slay|fight|defeat)\\s+(?:a|an|the)?\\s*(\\d+)?\\s*([a-z' ]+?)(?:\\s+with\\b[^,.]*?)?\\s+for\\s+(?:it'?s\\s+|its\\s+|their\\s+|the\\s+)?meat\\b",
		Pattern.CASE_INSENSITIVE);

	/**
	 * "Pickpocket HAM members for a rusty sword" — the goal is the named
	 * LOOT itself. Only fires when the tail resolves to a real item
	 * (addIfValid validates), so "kill wizards for xp" stays manual.
	 */
	private static final Pattern LOOT_FOR_ITEM = Pattern.compile(
		"\\b(?:pickpocket|steal from|thieve|kill|slay|safespot|give|hand)\\b[^,.]*?\\s+for\\s+"
			+ "(?:a|an|the)?\\s*(\\d+)?\\s*([a-z' ]+?)(?:\\s*[,.(]|$)",
		Pattern.CASE_INSENSITIVE);

	/** "for a ..." tails that are never loot (first sweep 2026-08-06). */
	private static final java.util.Set<String> LOOT_STOP = java.util.Set.of(
		"hours", "couple of hours", "minutes", "while", "bit", "bone",
		"xp", "exp", "money", "cash", "profit");

	private static final java.util.Map<String, String> MEAT_BY_NPC = java.util.Map.of(
		"chicken", "raw chicken",
		"cow", "raw beef",
		"cow calf", "raw beef",
		"calf", "raw beef",
		"rat", "raw rat meat",
		"giant rat", "raw rat meat",
		"bear", "raw bear meat",
		"yak", "raw yak meat");

	/**
	 * "Fill 3 buckets with milk" -> 3 buckets OF milk: the empty
	 * containers must not tick it. Known fillable containers only, so
	 * "fill 1 inventory of buckets with water" falls through unchanged.
	 */
	private static final Pattern FILL_WITH = Pattern.compile(
		"\\bfill\\s+(?:a|an|the)?\\s*(\\d+)?\\s*(buckets?|jugs?|vials?|bowls?|cups?|waterskins?)\\s+with\\s+([a-z]+)",
		Pattern.CASE_INSENSITIVE);

	/** "Fill 1 inventory of buckets with water" — 28 slots' worth. */
	private static final Pattern INVENTORY_FILL = Pattern.compile(
		"\\bfill\\s+(?:a|an|1|one)?\\s*(?:inv|inventory)\\s+of\\s+(buckets?|jugs?|vials?|bowls?|cups?)\\s+with\\s+([a-z]+)",
		Pattern.CASE_INSENSITIVE);

	/**
	 * Returns the acquisition flag a bare continuation of this step's item
	 * list should inherit: a sub with its own verb (re)defines the list
	 * ("buy 5 X" -> purchases), a bare continuation carries it unchanged,
	 * and a sub without goals breaks the list.
	 */
	private static boolean detectItemGoal(GuideStep step, SubStep sub, List<ItemGoal> out,
		boolean inItemList, boolean inheritedAcquisition)
	{
		// Parentheticals are commentary, not shopping — "(so there are 3
		// planks left in your bank)" must not become a "planks left" goal.
		String text = sub.getPlainText().trim().replaceAll("\\([^)]*\\)", " ");
		boolean ownPurchase = PURCHASE_VERB.matcher(text).find();
		int before = out.size();
		java.util.Set<String> seen = new java.util.HashSet<>();

		Matcher kill = KILL_FOR_MEAT.matcher(text);
		if (kill.find())
		{
			String npc = kill.group(2).trim().toLowerCase(Locale.ROOT);
			String meat = MEAT_BY_NPC.get(npc);
			if (meat == null && npc.endsWith("s"))
			{
				meat = MEAT_BY_NPC.get(npc.substring(0, npc.length() - 1));
			}
			if (meat != null)
			{
				addIfValid(out, step, sub, kill.group(1) == null ? "1" : kill.group(1),
					meat, seen, false);
			}
			return false;
		}

		// "... for a rusty sword": the named loot is the goal. Mirrors the
		// meat rule's early return — a rejected tail stays a manual
		// checkbox rather than feeding the pair scan an NPC name.
		Matcher loot = LOOT_FOR_ITEM.matcher(text);
		if (loot.find())
		{
			String tail = loot.group(2).trim().toLowerCase(Locale.ROOT);
			// Real loot names are short ("rusty sword") — a rambling tail
			// ("couple of hours just to get some low level seeds...") is
			// prose, and addIfValid would shred it into a garbage goal.
			// Quest names aren't loot either ("...for Merlin's crystal"),
			// and generic "bone" names a Rag & Bone wishlist skull with no
			// bundled id yet.
			boolean questName = false;
			for (net.runelite.api.Quest quest : net.runelite.api.Quest.values())
			{
				if (quest.getName().equalsIgnoreCase(tail))
				{
					questName = true;
					break;
				}
			}
			if (tail.split(" ").length <= 3 && !questName && !LOOT_STOP.contains(tail))
			{
				addIfValid(out, step, sub, loot.group(1) == null ? "1" : loot.group(1),
					tail, seen, false);
			}
			return false;
		}

		Matcher invFill = INVENTORY_FILL.matcher(text);
		if (invFill.find())
		{
			addIfValid(out, step, sub, "28",
				invFill.group(1).toLowerCase(Locale.ROOT) + " of "
					+ invFill.group(2).toLowerCase(Locale.ROOT), seen, false);
			return false;
		}

		Matcher fillWith = FILL_WITH.matcher(text);
		if (fillWith.find())
		{
			addIfValid(out, step, sub, fillWith.group(1) == null ? "1" : fillWith.group(1),
				fillWith.group(2).toLowerCase(Locale.ROOT) + " of "
					+ fillWith.group(3).toLowerCase(Locale.ROOT), seen, false);
			return false;
		}

		// "Kill 5 hill giants": the number counts kills, not items — strip
		// it so the pair scan below can't invent a "hill giants" goal.
		text = text.replaceAll(
			"(?i)\\b(kill|fight|defeat|slay|safespot)\\s+(?:a|an|the)?\\s*\\d+\\s+", "$1 ");

		// "buy ... and pestle and mortar": names containing "and" never
		// survive the list terminator — scan the known ones whole and add
		// them DIRECTLY (addIfValid would shred them the same way).
		String lowerText = text.toLowerCase(Locale.ROOT);
		for (String andName : AND_ITEM_NAMES)
		{
			if (lowerText.contains(andName) && seen.add(andName + ":1"))
			{
				out.add(new ItemGoal(step, sub, andName, 1, ownPurchase));
			}
		}

		// Every "number + name" pair anywhere in the fragment, so "buy 5
		// bolts of cloth and 100 steel nails" yields BOTH goals. Junk pairs
		// ("world 444 is recommended") die in addIfValid's name checks.
		Matcher pairs = QUANTITY_NAME.matcher(text);
		while (pairs.find())
		{
			String preceding = text.substring(0, pairs.start());
			if (CONSUMED_MATERIAL.matcher(preceding).find())
			{
				continue; // the material, not the objective — see the pattern
			}
			if (RETAIN_INSTRUCTION.matcher(preceding).find())
			{
				// "keep 3 bars" says what to hold BACK, not what to go and
				// get. It read as a goal and sat green at 3/3 off bars
				// already in the bank, which both misinforms and lets the
				// step finish without the smelting it is actually about
				// (owner, 2026-08-14, step 288).
				//
				// Only "keep". The obvious generalisation — veto any number
				// introduced by a word already on NOT_AN_ITEM_FIRST_WORD —
				// was MEASURED and rejected: of its 3 hits guide-wide, 2 are
				// real goals ("Bank 7 logs for later" needs 7 logs, "Fill 3
				// buckets with milk" is one this detector deliberately
				// builds). Leading a clause and following a number are
				// different jobs.
				continue;
			}
			// "200k cash" / "1m gp": expand the k/m suffix into the number.
			String quantity = expandQuantity(pairs.group(1), pairs.group(2));
			if (quantity == null)
			{
				continue;
			}
			addIfValid(out, step, sub, quantity, pairs.group(3), seen, ownPurchase);
		}

		// "300 earth and water": give the second rune type the shared number.
		Matcher sharedRunes = SHARED_RUNE_QUANTITY.matcher(text);
		while (sharedRunes.find())
		{
			addIfValid(out, step, sub, sharedRunes.group(1).replace(",", ""),
				sharedRunes.group(2), seen, ownPurchase);
		}

		// "get 100 compost and saltpetre": the bare tail inherits the
		// number — without this, only compost became a goal and the step
		// auto-ticked with zero saltpetre gathered (owner hit this).
		// addIfValid's junk checks + the audit sweep guard the fallout.
		Matcher inherited = INHERITED_AND_TAIL.matcher(text);
		while (inherited.find())
		{
			String tail = inherited.group(3);
			String firstWord = tail.split("[\\s'-]+")[0].toLowerCase(Locale.ROOT);
			if (AND_TAIL_STOP.contains(firstWord))
			{
				continue;
			}
			String quantity = expandQuantity(inherited.group(1), inherited.group(2));
			if (quantity == null)
			{
				continue;
			}
			addIfValid(out, step, sub, quantity, tail, seen, ownPurchase);
		}

		// "Buy 8 woad leaves, offer 20gp to get 2 leaves": the bare word
		// re-mentions the SAME item. A goal whose name is the word-suffix
		// OR word-prefix of another goal in this sub is a fragment of it
		// ("pestle" beside "pestle and mortar"), not a second item.
		for (int i = out.size() - 1; i >= before; i--)
		{
			String shortName = out.get(i).getItemName();
			for (int j = before; j < out.size(); j++)
			{
				if (i != j
					&& (out.get(j).getItemName().endsWith(" " + shortName)
						|| out.get(j).getItemName().startsWith(shortName + " ")))
				{
					out.remove(i);
					break;
				}
			}
		}

		if (out.size() > before)
		{
			// MIXED purchase list: "Buy candle, 2 fishing rods, lobster
			// pot". The numbered part is found above and returns, so the
			// unnumbered siblings were dropped and the panel showed one
			// badge where the guide asked for three (owner, 2026-08-08).
			// Purchases list with commas at least as often as with "and",
			// so a comma sibling carrying no number of its own is one more
			// thing to buy. Purchases only: outside a shopping list a
			// comma usually separates ACTIONS, not items.
			if (ownPurchase)
			{
				addUnnumberedSiblings(out, step, sub, text, seen);
			}
			return ownPurchase; // numbered goals found; done
		}

		// "Make the logs into a plank" — done when you own the product.
		Matcher product = INTO_PRODUCT.matcher(text);
		if (product.find())
		{
			addIfValid(out, step, sub, "1", product.group(1), seen, false);
			return false;
		}

		// "Make the hangover cure" — done when you hold the product. Not
		// on training steps ("train construction ... make bookcases"), and
		// not on open-ended loops ("make bookcases UNTIL out of planks"):
		// the built things never enter the inventory, and an item goal
		// here would shadow the counted xp-drop goal.
		String lower = text.toLowerCase(Locale.ROOT);
		if (!lower.contains("train") && !lower.contains("until"))
		{
			Matcher made = MAKE_PRODUCT.matcher(text);
			// "MAKE SURE you're consistent with all your farming and
			// birdhouses" is an idiom, not a crafting instruction. It was
			// harmless while only the first product was taken (the phrase
			// that followed was not an item and got rejected); splitting on
			// "and" reached "birdhouses", which IS an item, and would have
			// let a "Get 58 slayer" step finish on owning one. Found by
			// reading the goal dump after the split went in.
			if (made.find() && !made.group(1).toLowerCase(Locale.ROOT).startsWith("sure "))
			{
				// "make a sickle AND unstrung holy symbol" makes two things,
				// and the step is only done when you hold both. Taking just
				// the first would finish it one item early.
				//
				// The junk this lets through is caught downstream rather than
				// prevented: of the 3 steps that match guide-wide, 2 are prose
				// ("make molten glass and CUT GEMS UNTIL 45 crafting", "make
				// sure you're consistent with all your farming AND
				// BIRDHOUSES"), and addIfValid's name checks reject them —
				// verified against the goal dump and the unresolvable-goal
				// audit after this went in, not assumed.
				for (String eachProduct : made.group(1).split("\\s+and\\s+"))
				{
					addIfValid(out, step, sub, "1", eachProduct, seen, false);
				}
				if (!out.isEmpty() && out.size() > before)
				{
					return false;
				}
			}
		}

		// "Grab a bucket of milk" — acquisition verb, no number: one of it.
		Matcher verbOnly = VERB_NO_QUANTITY.matcher(text);
		if (verbOnly.find())
		{
			// "Buy buckets of sand AND soda ash": in a purchase, every
			// and-separated part of the unnumbered list is its own item.
			// (Non-purchases keep just the first part — "get the touch
			// paper and give the potions" must not invent a 'give' item.)
			String[] parts = verbOnly.group(1).split("\\s+and\\s+");
			addIfValid(out, step, sub, "1", parts[0], seen, ownPurchase);
			for (int i = 1; ownPurchase && i < parts.length; i++)
			{
				// "buy chocolate dust ... and MAKE energy pots": an action
				// verb opens a new clause, not another purchased item.
				// ("make" is absent from NOT_AN_ITEM_FIRST_WORD because
				// MAKE_PRODUCT wants it — list it here explicitly.)
				String firstWord = parts[i].trim().split("[^a-z]+", 2)[0];
				if (NOT_AN_ITEM_FIRST_WORD.contains(firstWord)
					|| java.util.Set.of("make", "craft", "smith", "cook", "mix", "brew")
						.contains(firstWord))
				{
					break;
				}
				addIfValid(out, step, sub, "1", parts[i], seen, true);
			}
			return ownPurchase;
		}

		// "raw sardine" — a bare noun fragment continuing the item list
		// started by an earlier fragment of this step.
		if (inItemList)
		{
			String cleaned = NAME_TERMINATOR.matcher(text).replaceFirst("").trim();
			// "a house teleport" is elliptical for "grab a house teleport" —
			// strip the article or the name check rejects it, and the sub
			// then wrongly falls through to travel detection ("teleport").
			cleaned = cleaned.replaceFirst("(?i)^(?:a|an|some|the)\\s+", "");
			if (BARE_ITEM.matcher(cleaned).matches()
				&& !NOT_AN_ITEM_FIRST_WORD.contains(
					cleaned.split(" ")[0].toLowerCase(Locale.ROOT)))
			{
				addIfValid(out, step, sub, "1", cleaned, seen, inheritedAcquisition);
				return inheritedAcquisition;
			}
		}
		return false;
	}

	/**
	 * The comma/and separated parts of a purchase list that carry NO
	 * number of their own — the "candle" and "lobster pot" of "Buy
	 * candle, 2 fishing rods, lobster pot". Numbered parts are already
	 * goals by the time this runs, and addIfValid's `seen` set keeps a
	 * re-parsed one from doubling up.
	 *
	 * Everything from the buy verb onwards is the list; a part opening
	 * with a non-item word (an action verb, a preposition) ends it, the
	 * same rule the and-separated path uses.
	 */
	private static void addUnnumberedSiblings(List<ItemGoal> out, GuideStep step,
		SubStep sub, String text, java.util.Set<String> seen)
	{
		Matcher list = VERB_NO_QUANTITY.matcher(text);
		if (!list.find())
		{
			return;
		}
		String tail = text.substring(list.start(1));
		for (String raw : tail.split("\\s*,\\s*|\\s+and\\s+"))
		{
			String part = raw.trim().replaceFirst("(?i)^(?:a|an|some|your|the)\\s+", "");
			// A leading number means the numbered pass already had it.
			if (part.isEmpty() || Character.isDigit(part.charAt(0)))
			{
				continue;
			}
			part = NAME_TERMINATOR.matcher(part).replaceFirst("").trim();
			if (!BARE_ITEM.matcher(part).matches())
			{
				continue;
			}
			String firstWord = part.split("[^A-Za-z]+", 2)[0].toLowerCase(Locale.ROOT);
			if (NOT_AN_ITEM_FIRST_WORD.contains(firstWord)
				|| java.util.Set.of("make", "craft", "smith", "cook", "mix", "brew")
					.contains(firstWord))
			{
				break; // an action verb opens a new clause: the list is over
			}
			addIfValid(out, step, sub, "1", part, seen, true);
		}
	}

	private static void addIfValid(List<ItemGoal> out, GuideStep step, SubStep sub,
		String rawQuantity, String rawName, java.util.Set<String> seen, boolean acquisition)
	{
		int quantity;
		try
		{
			quantity = Integer.parseInt(rawQuantity.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return;
		}
		if (quantity < 1 || quantity > 50_000_000)
		{
			return; // junk pair ("world 444" survives elsewhere; sanity cap)
		}
		String name = NAME_TERMINATOR.matcher(rawName).replaceFirst("").trim().toLowerCase(Locale.ROOT);

		// "iron bars JUST northwest", "garlic UPSTAIRS", "50 construction
		// BANKED" — trailing adverbs are prose, not part of a name.
		name = name.replaceFirst(
			"\\s+(?:just|now|upstairs|banked|nearby|later|again|first|today)$", "");

		// "1 inv of bronze bars" is 28 of them; "2 inventories of gold
		// ore" is 56.
		Matcher inventories = INV_OF.matcher(name);
		if (inventories.matches())
		{
			name = inventories.group(1);
			quantity = quantity * 28;
		}

		// "1 PACK of eyes of newt" -> "eyes of newt pack"; the alias
		// chain's first-word deplural then reaches "Eye of newt pack".
		Matcher packOf = PACK_OF.matcher(name);
		if (packOf.matches())
		{
			name = packOf.group(1) + " pack";
		}

		// "4 red, 4 blue, 5 yellow dye" / "1 soft, 1 hard leather": the
		// shared noun sits on the LAST list entry only.
		String subLower = sub.getPlainText().toLowerCase(Locale.ROOT);
		if (java.util.Set.of("red", "blue", "yellow", "green", "orange", "purple").contains(name)
			&& subLower.contains("dye"))
		{
			name = name + " dye";
		}
		else if ((name.equals("soft") || name.equals("hard")) && subLower.contains("leather"))
		{
			name = name + " leather";
		}

		// "one POH tab" -> quantity 1 of "poh tab"
		String[] numberSplit = name.split(" ", 2);
		Integer numberWord = NUMBER_WORDS.get(numberSplit[0]);
		if (numberWord != null && numberSplit.length > 1)
		{
			name = numberSplit[1];
			if (quantity == 1)
			{
				quantity = numberWord;
			}
		}

		// "a few cakes" is cakes, not an item called "few cakes", and
		// "plenty of digsite pendants" is digsite pendants. The vague
		// quantity stays 1 — owning any satisfies it poorly but
		// predictably, and the badge counts the REAL item.
		while (name.matches("(?:few|couple|plenty|of)\\s.*"))
		{
			name = name.substring(name.indexOf(' ') + 1);
		}

		// "110 logs" good; "110 of the things you like most" is not an item.
		// "gp" gets a pass on the length rule — it's the guide's word for coins.
		if ((name.length() < 3 && !name.equals("gp")) || name.split(" ").length > 4)
		{
			return;
		}
		if (NAME_REJECT_FIRST_WORD.contains(name.split(" ")[0])
			|| NAME_REJECT_EXACT.contains(name))
		{
			return;
		}
		// "get 43 prayer" / "5 attack" are levels, not items
		String singular = name.endsWith("s") ? name.substring(0, name.length() - 1) : name;
		if (SKILL_WORDS.contains(name) || SKILL_WORDS.contains(singular))
		{
			return;
		}
		// "the Superglass Make lunar spell" — MAKE_PRODUCT sees "make
		// lunar spell" inside the spell's NAME. Spells are never items.
		if (name.endsWith(" spell") || name.endsWith(" spells") || name.equals("spell"))
		{
			return;
		}

		if (!seen.add(name + ":" + quantity))
		{
			return; // same pair matched twice in one fragment
		}

		// "air/mind runes" means BOTH items: expand to "air runes" + "mind runes".
		Matcher compound = COMPOUND_NAME.matcher(name);
		if (compound.matches())
		{
			out.add(new ItemGoal(step, sub, compound.group(1) + " " + compound.group(3), quantity, acquisition));
			out.add(new ItemGoal(step, sub, compound.group(2) + " " + compound.group(3), quantity, acquisition));
			return;
		}
		// "bat bones/black candle" — full names either side of the slash.
		if (name.contains("/"))
		{
			for (String part : name.split("/"))
			{
				part = part.trim();
				if (part.length() >= 3)
				{
					out.add(new ItemGoal(step, sub, part, quantity, acquisition));
				}
			}
			return;
		}

		out.add(new ItemGoal(step, sub, name, quantity, acquisition));
	}

	private static void detectQuestGoal(GuideStep step, SubStep sub, List<QuestGoal> out)
	{
		// straight apostrophes: the guide writes "Witch’s Potion" (curly),
		// the Quest enum says "Witch's Potion"
		String text = sub.getPlainText().toLowerCase(Locale.ROOT).replace('’', '\'');
		if (!text.contains("start") && !text.contains("begin") && !text.contains("continue")
			&& !text.contains("complete") && !text.contains("finish") && !text.contains("do "))
		{
			return; // cheap pre-filter before the quest-name scan
		}

		for (Quest quest : Quest.values())
		{
			String questName = quest.getName().toLowerCase(Locale.ROOT);
			if (verbPhrase(text, questName, "complete", "finish", "do"))
			{
				out.add(new QuestGoal(step, sub, quest, true));
				return; // one quest goal per sub-step is plenty
			}
			if (verbPhrase(text, questName, "start", "begin"))
			{
				out.add(new QuestGoal(step, sub, quest, false));
				return;
			}
		}
	}

	/**
	 * "complete Tower of Life" AND "complete THE Tower of Life" — the
	 * guide freely inserts the article, which used to break the match
	 * (so finishing the quest never ticked the sub).
	 */
	private static boolean verbPhrase(String text, String questName, String... verbs)
	{
		for (String verb : verbs)
		{
			if (text.contains(verb + " " + questName)
				|| text.contains(verb + " the " + questName))
			{
				return true;
			}
		}
		return false;
	}
}

package com.ironscape.travel;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Every teleport an ITEM can provide — diary cloaks, teleport jewellery,
 * tablets, memoirs — with where it lands and what it takes to use.
 *
 * The hint used to know only minigame teleports, standard-spellbook spells,
 * the free home teleport and the Chronicle, so it offered a Varrock teleport
 * for a West Ardougne target while an Ardougne cloak sat in the bag that
 * lands next door (owner, 2026-08-11).
 *
 * The data is Shortest Path's, converted by tools/seed-teleport-items.mjs —
 * see that file for why this is not a wiki scrape. Re-running it picks up
 * their corrections.
 *
 * This class is deliberately free of client calls: it holds the conditions
 * and asks a {@link Availability} for the game state, so the matching rules
 * can be tested without a running game.
 */
@Slf4j
public final class TeleportItems
{
	/** A varbit/varplayer clause: {@code id op value}. */
	public static final class VarCondition
	{
		int id;
		String op;
		int value;

		public boolean met(int actual)
		{
			switch (op)
			{
				case "=":
					return actual == value;
				case ">":
					return actual > value;
				case "<":
					return actual < value;
				case "&":
					// Bitmask: the named bits must be set. A `>=` here would
					// let any OTHER bit in the same var satisfy it — the
					// barcrawl-stamp trap (wave 6).
					return (actual & value) == value;
				case "@":
					// A real-time countdown in minutes: the var holds a
					// minute stamp and the teleport is ready once `value`
					// minutes have passed. Handled by the caller, which
					// knows the wall clock; treated as met here.
					return true;
				default:
					return false;
			}
		}

		public int getId()
		{
			return id;
		}

		public boolean isCooldown()
		{
			return "@".equals(op);
		}

		public int getValue()
		{
			return value;
		}
	}

	/** A level gate. {@code skill} is a Skill name, or TOTAL / QUEST. */
	public static final class SkillNeed
	{
		int level;
		String skill;

		public int getLevel()
		{
			return level;
		}

		public String getSkill()
		{
			return skill;
		}
	}

	/** One destination an item can take you to. */
	public static final class Entry
	{
		String display;
		@SerializedName("itemIds")
		int[] itemIds;
		int x;
		int y;
		int plane;
		boolean consumable;
		int maxWilderness;
		List<VarCondition> varbits;
		List<VarCondition> varplayers;
		List<SkillNeed> skills;
		List<String> quests;

		private WorldPoint destination;

		/** The option to pick in the item's menu — "Ardougne cloak: Kandarin Monastery". */
		public String getDisplay()
		{
			return display;
		}

		public int[] getItemIds()
		{
			return itemIds;
		}

		public WorldPoint getDestination()
		{
			if (destination == null)
			{
				destination = new WorldPoint(x, y, plane);
			}
			return destination;
		}

		public boolean isConsumable()
		{
			return consumable;
		}

		public List<VarCondition> getVarbits()
		{
			return varbits == null ? Collections.emptyList() : varbits;
		}

		public List<VarCondition> getVarplayers()
		{
			return varplayers == null ? Collections.emptyList() : varplayers;
		}

		public List<SkillNeed> getSkills()
		{
			return skills == null ? Collections.emptyList() : skills;
		}

		public List<String> getQuests()
		{
			return quests == null ? Collections.emptyList() : quests;
		}

		/**
		 * The item name the player would recognise, taken from the label:
		 * "Ardougne cloak: Kandarin Monastery" -> "Ardougne cloak".
		 */
		public String itemLabel()
		{
			int colon = display.indexOf(':');
			return colon > 0 ? display.substring(0, colon).trim() : display;
		}
	}

	/**
	 * What the game says right now. Implemented by the plugin against the
	 * client; implemented by tests against fixed values.
	 */
	public interface Availability
	{
		/** Does the player hold or wear this item id? */
		boolean carries(int itemId);

		int varbit(int id);

		int varplayer(int id);

		/** Level in a named skill, or -1 if the name is not a skill. */
		int skillLevel(String skill);

		int totalLevel();

		int questPoints();

		boolean questFinished(String questName);
	}

	private final List<Entry> entries;

	private TeleportItems(List<Entry> entries)
	{
		this.entries = entries;
	}

	public List<Entry> all()
	{
		return entries;
	}

	/**
	 * The entry Shortest Path means by a given label.
	 *
	 * An exact match is right here and a fuzzy one would be wrong: this
	 * index is built FROM Shortest Path's own table, so the strings are the
	 * same strings. If one ever stops matching, the answer is to re-run the
	 * seeder, not to loosen the comparison.
	 */
	public Entry byDisplay(String display)
	{
		if (display == null)
		{
			return null;
		}
		for (Entry entry : entries)
		{
			if (display.equals(entry.getDisplay()))
			{
				return entry;
			}
		}
		return null;
	}

	public int size()
	{
		return entries.size();
	}

	/**
	 * Every teleport the player could use RIGHT NOW, in no particular
	 * order. Ranking is the caller's job — it is the one that knows where
	 * the player is going.
	 */
	public List<Entry> available(Availability state)
	{
		List<Entry> usable = new ArrayList<>();
		for (Entry entry : entries)
		{
			if (isAvailable(entry, state))
			{
				usable.add(entry);
			}
		}
		return usable;
	}

	/**
	 * Every gate must pass. Anything we cannot evaluate fails CLOSED — a
	 * teleport we wrongly withhold costs a hint, one we wrongly offer sends
	 * the player digging for an item they do not have (wave 25's rule for
	 * unresolved quest names, same reasoning).
	 */
	public boolean isAvailable(Entry entry, Availability state)
	{
		boolean holdsOne = false;
		for (int id : entry.getItemIds())
		{
			if (state.carries(id))
			{
				holdsOne = true;
				break;
			}
		}
		if (!holdsOne)
		{
			return false;
		}
		for (VarCondition condition : entry.getVarbits())
		{
			if (!condition.met(state.varbit(condition.getId())))
			{
				return false;
			}
		}
		for (VarCondition condition : entry.getVarplayers())
		{
			if (!condition.met(state.varplayer(condition.getId())))
			{
				return false;
			}
		}
		for (SkillNeed need : entry.getSkills())
		{
			int have;
			// TOTAL and QUEST are not skills — they are the max cape's total
			// level and the quest cape's quest points, which share this
			// column in the source data.
			if ("TOTAL".equals(need.getSkill()))
			{
				have = state.totalLevel();
			}
			else if ("QUEST".equals(need.getSkill()))
			{
				have = state.questPoints();
			}
			else
			{
				have = state.skillLevel(need.getSkill());
			}
			if (have < need.getLevel())
			{
				return false;
			}
		}
		for (String quest : entry.getQuests())
		{
			if (!state.questFinished(quest))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * An index with nothing in it, for a field that must be non-null before
	 * the plugin has started. Deliberately NOT "load it with a throwaway
	 * Gson" — the Plugin Hub rejects fresh Gson instances outright, and the
	 * real load happens in startUp with the client's injected one.
	 */
	public static TeleportItems empty()
	{
		return new TeleportItems(Collections.emptyList());
	}

	/** Load the bundled index; never throws, and an unreadable file yields an empty one. */
	public static TeleportItems load(Gson gson)
	{
		try (InputStream in = com.ironscape.DataFiles.open(TeleportItems.class, "teleport_items.json"))
		{
			if (in == null)
			{
				log.warn("teleport_items.json missing — teleport items will not be suggested");
				return new TeleportItems(Collections.emptyList());
			}
			Entry[] loaded = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), Entry[].class);
			if (loaded == null)
			{
				return new TeleportItems(Collections.emptyList());
			}
			List<Entry> valid = new ArrayList<>(loaded.length);
			for (Entry entry : loaded)
			{
				// A row with no display or no items cannot be acted on, and
				// silently keeping it would inflate the count this is
				// measured by.
				if (entry != null && entry.display != null
					&& entry.itemIds != null && entry.itemIds.length > 0)
				{
					valid.add(entry);
				}
			}
			return new TeleportItems(Collections.unmodifiableList(valid));
		}
		catch (Exception e)
		{
			log.warn("Could not read the teleport item index", e);
			return new TeleportItems(Collections.emptyList());
		}
	}
}

package com.ironscape.travel;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * How far it really is to WALK from each teleport landing to anywhere on the
 * surface.
 *
 * The first-leg hint used to rank landings by straight-line distance, and a
 * straight line cannot see a mountain. Keep Le Faye is ~145 tiles from the
 * Burthorpe Games Room and ~240 from the Fishing Trawler landing, so Burthorpe
 * won — but Keep Le Faye is on the far side of White Wolf Mountain, so the walk
 * is 476 tiles against the Trawler's 405. The owner took the hint and landed in
 * a corner. The Ardougne wall, every river and every island are the same shape.
 *
 * Real path distance lives in Shortest Path's pathfinder, and the Plugin Hub
 * forbids reaching across classloaders into another plugin. But SP publishes
 * the data its pathfinder runs on — a collision map and its transport tables —
 * so {@code tools/build-travel-distances.mjs} does that search offline, once,
 * at full tile resolution, and bundles the answers as a distance field per
 * landing.
 *
 * <p><b>What the numbers mean.</b> Tiles walked, counting only crossings ANY
 * account can make: no quest gates, no skill gates, no items beyond coins. So a
 * distance here is an upper bound on the real walk — a player with the agility
 * shortcut gets there sooner. That is deliberate. Erring long means the hint
 * suggests a teleport less often, and suggesting one too eagerly is the fault
 * this class exists to fix.
 *
 * <p><b>Resolution.</b> The query point is rounded to a 32-tile cell holding
 * the nearest reachable tile in it. On the guide's own pins that reads ~7%
 * short, which is small against the 40% margin the hint already demands.
 */
@Slf4j
@Singleton
public class TravelDistances
{
	/** No answer: the table is missing, or nothing ungated reaches that cell. */
	public static final int UNKNOWN = -1;

	private static final String RESOURCE = "/com/ironscape/travel/travel_distances.bin.gz";
	private static final int FORMAT_VERSION = 1;
	private static final int UNREACHABLE = 65535;

	private int cell;
	private int minX;
	private int minY;
	private int width;
	private int height;
	private final Map<String, char[]> fields = new HashMap<>();

	public TravelDistances()
	{
		try (InputStream raw = TravelDistances.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("No bundled travel distance table; first-leg hints fall back to straight lines");
				return;
			}
			read(new DataInputStream(new GZIPInputStream(raw)));
		}
		catch (IOException | RuntimeException e)
		{
			// Never fatal. Everything downstream treats UNKNOWN as "use the old
			// straight-line metric", so a bad table costs accuracy, not function.
			fields.clear();
			log.warn("Could not read the bundled travel distance table", e);
		}
	}

	/**
	 * The file is little-endian (written by Node), DataInputStream reads
	 * big-endian, hence the byte swaps. Fields are stored as char[] purely
	 * because char is Java's unsigned 16-bit type.
	 */
	private void read(DataInputStream in) throws IOException
	{
		byte[] magic = new byte[4];
		in.readFully(magic);
		if (!"IRTD".equals(new String(magic, StandardCharsets.US_ASCII)))
		{
			throw new IOException("not a travel distance table");
		}
		int version = readInt(in);
		if (version != FORMAT_VERSION)
		{
			throw new IOException("travel distance table is version " + version
				+ ", this build reads version " + FORMAT_VERSION);
		}
		cell = readInt(in);
		minX = readInt(in);
		minY = readInt(in);
		width = readShort(in);
		height = readShort(in);
		int count = readInt(in);
		for (int i = 0; i < count; i++)
		{
			byte[] name = new byte[readInt(in)];
			in.readFully(name);
			char[] cells = new char[width * height];
			for (int c = 0; c < cells.length; c++)
			{
				cells[c] = (char) readShort(in);
			}
			fields.put(new String(name, StandardCharsets.UTF_8), cells);
		}
		log.debug("travel distances: {} landings, {}x{} cells of {} tiles",
			fields.size(), width, height, cell);
	}

	private static int readInt(DataInputStream in) throws IOException
	{
		return Integer.reverseBytes(in.readInt());
	}

	private static int readShort(DataInputStream in) throws IOException
	{
		return Short.toUnsignedInt(Short.reverseBytes(in.readShort()));
	}

	/** True once the bundled table loaded; false means every query answers UNKNOWN. */
	public boolean isLoaded()
	{
		return !fields.isEmpty();
	}

	/** The landing names this table knows, for the test that guards them against the plugin's own list. */
	public java.util.Set<String> origins()
	{
		return fields.keySet();
	}

	/**
	 * Tiles to walk from {@code origin}'s landing spot to {@code target}, or
	 * {@link #UNKNOWN} when no ungated route exists — which is the honest
	 * answer for a target behind a quest gate, and the reason a landing on
	 * Mos Le'Harmless never wins a first leg to the mainland.
	 */
	public int distance(String origin, WorldPoint target)
	{
		char[] field = fields.get(origin);
		if (field == null || target == null)
		{
			return UNKNOWN;
		}
		int index = cellIndex(target);
		if (index < 0)
		{
			return UNKNOWN;
		}
		int d = field[index];
		return d == UNREACHABLE ? UNKNOWN : d;
	}

	/**
	 * Does ANY landing reach this target? The hint uses it to pick a metric
	 * and stay on it: mixing walked tiles for one candidate with a straight
	 * line for the next compares two different things, so when the table
	 * cannot speak about a target at all, every candidate falls back together.
	 */
	public boolean reachable(WorldPoint target)
	{
		int index = cellIndex(target);
		if (index < 0)
		{
			return false;
		}
		for (char[] field : fields.values())
		{
			if (field[index] != UNREACHABLE)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The cell holding this point, or -1 if it is off the surface grid. Plane
	 * is deliberately ignored: a 32-tile cell cannot resolve a staircase, and
	 * the ground floor underneath an upstairs pin is where you walk to anyway.
	 */
	private int cellIndex(WorldPoint p)
	{
		if (p == null || !isLoaded())
		{
			return -1;
		}
		int cx = (p.getX() - minX) / cell;
		int cy = (p.getY() - minY) / cell;
		if (p.getX() < minX || p.getY() < minY || cx >= width || cy >= height)
		{
			return -1;
		}
		return cy * width + cx;
	}
}

package com.ironscape.progress;

import com.ironscape.guide.Guide;
import com.ironscape.guide.GuideStep;
import com.ironscape.guide.GuideVariant;
import com.ironscape.guide.SubStep;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Which steps the player has checked off, per guide variant.
 *
 * Persistence: one config value per variant, a comma-joined list of step
 * ids, written through RuneLite's ConfigManager. That means progress lives
 * in the ACTIVE RuneLite profile — switching profile switches progress,
 * and cloud-synced profiles carry it between machines. This replaces the
 * website's browser localStorage.
 */
@Slf4j
@Singleton
public class ProgressManager
{
	private static final String CONFIG_GROUP = "ironscape";

	private final ConfigManager configManager;

	// In-memory cache so we don't re-parse the config string on every
	// checkbox read. Rebuilt after a profile switch via invalidate().
	private final Map<GuideVariant, Set<String>> cache = new EnumMap<>(GuideVariant.class);

	// Counted xp-drop progress ("train construction (6 chairs...)"): how many
	// drops have been seen per sub-step id. Same cache/persist scheme as
	// completed ids, stored as comma-joined "subId=count" pairs.
	private final Map<GuideVariant, Map<String, Integer>> countedCache = new EnumMap<>(GuideVariant.class);
	private final Map<GuideVariant, Map<String, Integer>> baselineCache = new EnumMap<>(GuideVariant.class);
	private final Map<GuideVariant, Map<String, Integer>> manualCache = new EnumMap<>(GuideVariant.class);

	/** Emotes already performed, per variant. See isEmoteDone. */
	private final Map<GuideVariant, Map<String, Integer>> emoteCache = new EnumMap<>(GuideVariant.class);

	@Inject
	public ProgressManager(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public synchronized boolean isCompleted(GuideVariant variant, String stepId)
	{
		return completedIds(variant).contains(stepId);
	}

	/**
	 * Complete or reset a whole step. The stored set only keeps the parent
	 * id for a fully done step — its sub ids are removed as redundant
	 * (parent completed implies every sub-step completed).
	 */
	public synchronized void setCompleted(GuideVariant variant, GuideStep step, boolean completed)
	{
		Set<String> ids = completedIds(variant);
		boolean changed = completed ? ids.add(step.getId()) : ids.remove(step.getId());
		for (SubStep sub : step.getSubSteps())
		{
			changed |= ids.remove(sub.getId());
		}
		if (changed)
		{
			save(variant, ids);
		}
		if (!completed)
		{
			setManual(variant, step.getId(), false);
			// Unticking says "this isn't done" — a kept-around full counter
			// would instantly re-tick the step on the next xp drop.
			Map<String, Integer> counts = countedFor(variant);
			boolean countsChanged = false;
			for (SubStep sub : step.getSubSteps())
			{
				countsChanged |= counts.remove(sub.getId()) != null;
				// Same reasoning for purchases: a kept baseline would leave
				// the step needing ANOTHER purchase to re-tick.
				clearAcquisitionBaselines(variant, sub.getId());
				// Doing the step again means finding the emote again.
				clearEmoteDone(variant, sub.getId());
				// Reopened means undecided again: it is no longer a record
				// of detection having failed. Cleared on EVERY untick path,
				// not just the panel's, so a gather-loss reopen counts too.
				setManual(variant, sub.getId(), false);
			}
			if (countsChanged)
			{
				saveCounted(variant, counts);
			}
		}
	}

	public synchronized boolean isSubCompleted(GuideVariant variant, GuideStep step, SubStep sub)
	{
		Set<String> ids = completedIds(variant);
		return ids.contains(step.getId()) || ids.contains(sub.getId());
	}

	/**
	 * Tick or untick one sub-step. Ticking the last open sub-step collapses
	 * the whole step into "parent completed"; unticking a sub-step of a
	 * completed step expands it back out into individual sub ids first.
	 */
	public synchronized void setSubCompleted(GuideVariant variant, GuideStep step, SubStep sub, boolean completed)
	{
		Set<String> ids = completedIds(variant);
		if (completed)
		{
			ids.add(sub.getId());
			boolean allDone = true;
			for (SubStep s : step.getSubSteps())
			{
				allDone &= ids.contains(s.getId());
			}
			if (allDone)
			{
				ids.add(step.getId());
				for (SubStep s : step.getSubSteps())
				{
					ids.remove(s.getId());
				}
			}
		}
		else
		{
			if (ids.remove(step.getId()))
			{
				for (SubStep s : step.getSubSteps())
				{
					ids.add(s.getId());
				}
			}
			ids.remove(sub.getId());
			// See setCompleted: an unticked sub restarts its xp-drop count
			// and re-arms its purchase baselines.
			Map<String, Integer> counts = countedFor(variant);
			if (counts.remove(sub.getId()) != null)
			{
				saveCounted(variant, counts);
			}
			clearAcquisitionBaselines(variant, sub.getId());
			// Doing the step again means finding the emote again.
			clearEmoteDone(variant, sub.getId());
			setManual(variant, sub.getId(), false);
		}
		save(variant, ids);
	}

	/** Xp drops seen so far for a counted sub-step ("train construction (6 chairs...)"). */
	public synchronized int countedProgress(GuideVariant variant, String subId)
	{
		Integer count = countedFor(variant).get(subId);
		return count == null ? 0 : count;
	}

	/** Record one more xp drop for a counted sub-step; returns the new total. */
	public synchronized int incrementCounted(GuideVariant variant, String subId)
	{
		Map<String, Integer> counts = countedFor(variant);
		int total = counts.merge(subId, 1, Integer::sum);
		saveCounted(variant, counts);
		return total;
	}

	/**
	 * How many steps of THIS guide are done. Counts against the guide's
	 * current steps, so ids left over from an older guide version (steps
	 * whose text was edited upstream) don't inflate the number.
	 */
	public synchronized int completedCount(Guide guide)
	{
		int count = 0;
		for (String id : completedIds(guide.getVariant()))
		{
			if (guide.getStepsById().containsKey(id))
			{
				count++;
			}
		}
		return count;
	}

	/** Count of completed steps among the given steps (used per section). */
	public synchronized int completedCount(GuideVariant variant, Iterable<GuideStep> steps)
	{
		Set<String> ids = completedIds(variant);
		int count = 0;
		for (GuideStep step : steps)
		{
			if (ids.contains(step.getId()))
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * A guide refresh gave some edited steps new ids (see GuideManifest):
	 * rewrite this profile's saved progress — step ids, their "id:N" sub
	 * ids, and counted xp-drop keys — so ticks survive the edit. Only
	 * touches the ACTIVE profile; call again after a profile switch
	 * (idempotent: already-remapped ids simply aren't in the map).
	 */
	public synchronized void remapIds(GuideVariant variant, Map<String, String> remap)
	{
		if (remap.isEmpty())
		{
			return;
		}
		Set<String> ids = completedIds(variant);
		Set<String> remappedIds = new LinkedHashSet<>();
		boolean idsChanged = false;
		for (String id : ids)
		{
			String mapped = com.ironscape.guide.GuideManifest.remapId(id, remap);
			if (mapped == null)
			{
				// The clause this tick belonged to was edited away —
				// dropping it merely unticks a box the player can re-tick.
				idsChanged = true;
				continue;
			}
			idsChanged |= !mapped.equals(id);
			remappedIds.add(mapped);
		}
		if (idsChanged)
		{
			ids.clear();
			ids.addAll(remappedIds);
			save(variant, ids);
		}

		Map<String, Integer> counts = countedFor(variant);
		Map<String, Integer> remappedCounts = new LinkedHashMap<>();
		boolean countsChanged = false;
		for (Map.Entry<String, Integer> entry : counts.entrySet())
		{
			String mapped = com.ironscape.guide.GuideManifest.remapId(entry.getKey(), remap);
			if (mapped == null)
			{
				countsChanged = true; // clause gone; its count restarts at 0
				continue;
			}
			countsChanged |= !mapped.equals(entry.getKey());
			remappedCounts.merge(mapped, entry.getValue(), Math::max);
		}
		if (countsChanged)
		{
			counts.clear();
			counts.putAll(remappedCounts);
			saveCounted(variant, counts);
		}
	}

	// ------------------------------------------------------------------
	// Player POSITION — where the player actually is in the guide, as a
	// global step index. Distinct from ticks on purpose: a quest step
	// five ahead auto-ticks the moment we see the quest was done ages
	// ago, but that must not teleport the frontier past undone steps.
	// Only completing the frontier step itself, or a deliberate manual
	// tick, moves position forward; unticking at/behind it moves it back.
	// ------------------------------------------------------------------

	private final Map<GuideVariant, Integer> positionCache = new EnumMap<>(GuideVariant.class);

	/** Global index of the last step the player actually passed; -1 = start. */
	public synchronized int position(GuideVariant variant)
	{
		return positionCache.computeIfAbsent(variant, v -> {
			String stored = configManager.getConfiguration(CONFIG_GROUP, positionKey(v));
			if (stored != null)
			{
				try
				{
					return Integer.parseInt(stored);
				}
				catch (NumberFormatException e)
				{
					// fall through to unset
				}
			}
			return Integer.MIN_VALUE; // unset — caller initializes from ticks
		});
	}

	/** True when no position was ever stored for this variant. */
	public synchronized boolean positionUnset(GuideVariant variant)
	{
		return position(variant) == Integer.MIN_VALUE;
	}

	public synchronized void advancePositionTo(GuideVariant variant, int index)
	{
		if (index > position(variant))
		{
			setPosition(variant, index);
		}
	}

	public synchronized void regressPositionTo(GuideVariant variant, int index)
	{
		int current = position(variant);
		if (current != Integer.MIN_VALUE && index < current)
		{
			setPosition(variant, index);
		}
	}

	public synchronized void setPosition(GuideVariant variant, int index)
	{
		positionCache.put(variant, index);
		configManager.setConfiguration(CONFIG_GROUP, positionKey(variant), Integer.toString(index));
	}

	/**
	 * The player's position, initializing it on first use (pre-position
	 * profiles): the end of the contiguous completed prefix — the last
	 * step with no undone step before it. Auto-ticked islands further
	 * ahead deliberately don't count. Shared by the plugin's frontier
	 * window AND the panel's Resume/auto-open, so both land on the same
	 * step.
	 */
	public synchronized int playerPosition(Guide guide)
	{
		GuideVariant variant = guide.getVariant();
		if (positionUnset(variant))
		{
			java.util.List<GuideStep> steps = guide.getAllSteps();
			int prefixEnd = -1;
			while (prefixEnd + 1 < steps.size()
				&& isCompleted(variant, steps.get(prefixEnd + 1).getId()))
			{
				prefixEnd++;
			}
			setPosition(variant, prefixEnd);
			log.info("Initialized player position at step index {}", prefixEnd);
		}
		return position(variant);
	}

	private static String positionKey(GuideVariant variant)
	{
		return "position_" + variant.name();
	}

	/** Call when the active RuneLite profile changes: cached progress belongs to the old profile. */
	public synchronized void invalidate()
	{
		cache.clear();
		countedCache.clear();
		baselineCache.clear();
		manualCache.clear();
		emoteCache.clear();
		positionCache.clear();
		alternativeCache.clear();
	}

	private Set<String> completedIds(GuideVariant variant)
	{
		return cache.computeIfAbsent(variant, this::load);
	}

	private Set<String> load(GuideVariant variant)
	{
		String stored = configManager.getConfiguration(CONFIG_GROUP, key(variant));
		Set<String> ids = new LinkedHashSet<>();
		if (stored != null && !stored.isEmpty())
		{
			Collections.addAll(ids, stored.split(","));
		}
		return ids;
	}

	private void save(GuideVariant variant, Set<String> ids)
	{
		if (ids.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key(variant));
		}
		else
		{
			configManager.setConfiguration(CONFIG_GROUP, key(variant), String.join(",", ids));
		}
	}

	private static String key(GuideVariant variant)
	{
		return "progress_" + variant.name();
	}

	/**
	 * How many of an item you held when a "buy X" sub first became
	 * current. PERSISTED, unlike the session-only map this replaced: a
	 * client restart between buying and the step being evaluated used to
	 * re-capture the baseline with the goods already in hand, so the
	 * count could never rise and the step was stuck green-but-unticked
	 * forever (owner, 2026-08-08). Keyed "subId|item name" — neither part
	 * can contain the ',' or '=' the encoding uses.
	 */
	public synchronized Integer acquisitionBaseline(GuideVariant variant, String key)
	{
		return baselineFor(variant).get(key);
	}

	public synchronized void setAcquisitionBaseline(GuideVariant variant, String key, int count)
	{
		Map<String, Integer> baselines = baselineFor(variant);
		Integer previous = baselines.put(key, count);
		if (previous == null || previous != count)
		{
			saveBaselines(variant, baselines);
		}
	}

	/** Unticking a sub re-arms its purchases: buy them again to re-tick. */
	public synchronized void clearAcquisitionBaselines(GuideVariant variant, String subId)
	{
		Map<String, Integer> baselines = baselineFor(variant);
		if (baselines.keySet().removeIf(key -> key.startsWith(subId + "|")))
		{
			saveBaselines(variant, baselines);
		}
	}

	/**
	 * Was this step or sub ticked BY HAND? Detection failing silently is
	 * invisible otherwise: the player shrugs, ticks the box and plays on,
	 * and nothing records that a goal never fired. Kept per id (step AND
	 * sub), so errand-heavy steps stay individually inspectable rather
	 * than collapsing to one all-or-nothing flag.
	 *
	 * Stored as a count map for one reason: it reuses the same encoding
	 * as the counters beside it. 1 = manual, absent = detected.
	 */
	public synchronized boolean isManual(GuideVariant variant, String id)
	{
		return manualFor(variant).containsKey(id);
	}

	public synchronized void setManual(GuideVariant variant, String id, boolean manual)
	{
		Map<String, Integer> manuals = manualFor(variant);
		boolean changed = manual
			? manuals.put(id, 1) == null
			: manuals.remove(id) != null;
		if (changed)
		{
			saveManuals(variant, manuals);
		}
	}

	/**
	 * Has the player already performed the emote a step asks for?
	 *
	 * <p>Persisted rather than kept in memory: the hint exists to FIND an
	 * emote among eighty icons, so it should die once you have clicked it —
	 * and a session-only flag brought it straight back on the next restart,
	 * pointing at an emote already performed (owner, in play, wave 27).
	 * Same encoding as the manual ticks beside it.
	 */
	public synchronized boolean isEmoteDone(GuideVariant variant, String id)
	{
		return emoteFor(variant).containsKey(id);
	}

	public synchronized void setEmoteDone(GuideVariant variant, String id)
	{
		Map<String, Integer> done = emoteFor(variant);
		if (done.put(id, 1) == null)
		{
			String encoded = encodeCounts(done);
			configManager.setConfiguration(CONFIG_GROUP, emoteKey(variant), encoded);
		}
	}

	/** Cleared with the step, so unticking a step asks for its emote again. */
	public synchronized void clearEmoteDone(GuideVariant variant, String id)
	{
		Map<String, Integer> done = emoteFor(variant);
		if (done.remove(id) != null)
		{
			String encoded = encodeCounts(done);
			if (encoded.isEmpty())
			{
				configManager.unsetConfiguration(CONFIG_GROUP, emoteKey(variant));
			}
			else
			{
				configManager.setConfiguration(CONFIG_GROUP, emoteKey(variant), encoded);
			}
		}
	}

	private Map<String, Integer> emoteFor(GuideVariant variant)
	{
		return emoteCache.computeIfAbsent(variant,
			v -> decodeCounts(configManager.getConfiguration(CONFIG_GROUP, emoteKey(v))));
	}

	private static String emoteKey(GuideVariant variant)
	{
